// gwent.one API verisinden üretildi (tools/fetch_cards.py). a=art id, n=isim, c=kategori, r=nadirlik, f=fraksiyon, t=tür, fl=flavor
window.GWENT_CARDS = [{"a": 1007, "n": "Ciri", "c": "Witcher", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "I go wherever I please, whenever I please."}, {"a": 1008, "n": "Geralt: Igni", "c": "Witcher", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "A twist of a witcher's fingers can light a lamp… or incinerate a foe."}, {"a": 1009, "n": "Geralt of Rivia", "c": "Witcher", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "If that's what it takes to save the world, it's better to let that world die."}, {"a": 1010, "n": "Regis", "c": "Vampire", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Some consider me a monster. A blood-crazed, savage monster."}, {"a": 1011, "n": "Regis: Higher Vampire", "c": "Vampire", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "He becomes invisible at will. His glance hypnotizes into a deep sleep. He then drinks his fill, turns into a bat and flies off. Altogether uncouth."}, {"a": 1012, "n": "Triss Merigold", "c": "Human, Mage", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "I can take care of myself. Trust me."}, {"a": 1013, "n": "Villentretenmerth", "c": "Dragon", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Also calls himself Borkh Three Jackdaws… he's not the best at names."}, {"a": 1014, "n": "Yennefer of Vengerberg", "c": "Human, Mage", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Magic is Chaos, Art and Science. It is a curse, a blessing and a progression."}, {"a": 1015, "n": "Zoltan: Scoundrel", "c": "Dwarf", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Apologies. My exotic pet's a clever birdie, but a wee bit lewd. Paid ten thalers for the beaute."}, {"a": 1016, "n": "Ciri: Dash", "c": "Witcher", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Know when fairy tales cease to be tales? When people start believing them."}, {"a": 1017, "n": "Geralt: Aard", "c": "Witcher", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "A blast of concentrated energy that pummels everything in its path. Great for when you forget your keys."}, {"a": 1018, "n": "Avallac'h: Sage", "c": "Elf, Mage", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Amongst the free elves were a handful of Aen Saevherne, or Sages. They were an enigma, bordering on a legend."}, {"a": 1019, "n": "Yennefer: Conjurer", "c": "Human, Mage", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "A good sorceress must know when to conjure ice… and when to conjure fire."}, {"a": 1020, "n": "Dudu", "c": "Relict", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "A mimic, among the many other names for his sort: changelings, doublings, vexlings… or dopplers."}, {"a": 1021, "n": "Eskel", "c": "Witcher", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "I'm a simple witcher, Wolf. Don't fight dragons, don't fraternize with kings and don't sleep with sorceresses…"}, {"a": 1022, "n": "Vesemir", "c": "Witcher", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "If you're to be hanged, ask for water. Anything can happen before they fetch it."}, {"a": 1023, "n": "Lambert", "c": "Witcher", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Now that's the kind of negotiating I understand."}, {"a": 1024, "n": "Myrgtabrakke", "c": "Dragon", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Never get between a mother dragon and her young."}, {"a": 1025, "n": "Ocvist", "c": "Dragon", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "The Master of Quartz Mountain, the Destroyer, Trajan's Slayer. In his free time, he likes long walks and candlelight dinners."}, {"a": 1026, "n": "Olgierd von Everec", "c": "Human, Cursed, Bandit", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "At least you now know I don't easily lose my head."}, {"a": 1027, "n": "Operator", "c": "Beast, Mage", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "As time and space collapse before us, they expand behind us. In that way one moves forward through both."}, {"a": 1028, "n": "Prize-Winning Cow", "c": "Beast", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Mooooo."}, {"a": 1029, "n": "Roach", "c": "Beast", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Geralt, we gotta have a man–to–horse talk. No offense, but your riding skills? They leave a bit to be desired, buddy."}, {"a": 1030, "n": "Johnny", "c": "Relict", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Life without savoring the sound of surreptitious shananacking is like licking snails through a cloth."}, {"a": 1031, "n": "Sarah", "c": "Relict", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Little Sarah wants to play!"}, {"a": 1032, "n": "Francis Bedlam", "c": "Human, Bandit", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "I might just discover I look great without ears… or hands. Apparently the King of Beggars accepts both as partial payment."}, {"a": 1033, "n": "Cyprian Wiley", "c": "Human, Bandit", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Ever since his father died, he's become a real whoreson."}, {"a": 1034, "n": "Iris von Everec", "c": "Human, Cursed", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "I remember so little… Yet when I think of my rose, I begin to recall what was."}, {"a": 1035, "n": "Unicorn", "c": "Relict", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "They say unicorns are fond of virgins. Since finding a virgin these days is as hard as finding a unicorn, no one has been able to verify the theory."}, {"a": 1036, "n": "Chironex", "c": "Relict", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Gods, that's no unicorn! That's…! – the last words of Vilemar, a famed collector of curiosities."}, {"a": 1039, "n": "Fiend", "c": "Relict", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "A fiend looks a bit like a deer. An enormous, evil deer."}, {"a": 1040, "n": "Ragh Nar Roog", "c": "Scenario", "r": "Legendary", "f": "Neutral", "t": "Artifact", "fl": "In the Final Age, Hemdall will come forth to face the evil issuing from the land of Morhogg – the legions of wraiths, demons and specters of Chaos."}, {"a": 1041, "n": "The Last Wish", "c": "Spell", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "A djinn, good sirs, fulfills but three wishes. Thus freed, it flees to dimensions unknown."}, {"a": 1042, "n": "Decoy", "c": "Warfare", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "When you run out of peasants, decoys also make decent arrow fodder."}, {"a": 1043, "n": "Merigold's Hailstorm", "c": "Spell", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "The sky dimmed of a sudden, and clouds amassed over the town. It grew fiendishly dark, and a cold gust swept in. Oh my, gasped Yennefer. We're about to make quite the mess, I think."}, {"a": 1044, "n": "Skellige Storm", "c": "Nature", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "This ain't no normal storm. This here's the wrath of the gods."}, {"a": 1045, "n": "Stammelford's Tremors", "c": "Spell", "r": "Common", "f": "Neutral", "t": "Special", "fl": "The sorcerer Stammelford moved a mountain that obscured the view from his tower. Rumor has it he could only do so for he'd fettered a d'ao, an earth elemental."}, {"a": 1046, "n": "Dimeritium Bomb", "c": "Bomb", "r": "Common", "f": "Neutral", "t": "Special", "fl": "An important part of every Witch Hunter's kit. In one muted flash, it turns the most powerful sorcerer into pork jelly ripe for cutting."}, {"a": 1047, "n": "Blizzard", "c": "", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "Behold Tedd Deireadh, the Final Age. The world destroyed by the White Frost."}, {"a": 1048, "n": "Commander's Horn", "c": "Warfare", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "Plus one to morale, minus one to hearing."}, {"a": 1049, "n": "Vaedermakar", "c": "Human, Mage, Druid", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Vaedermakar druids control the elements. They soothe storms into silence, muster destructive hail, summon lightning to turn foes into ash. So I advise you well… treat them with utmost respect."}, {"a": 1050, "n": "Alzur's Double-Cross", "c": "Spell", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "A few of Alzur's monstrous creations roam the world still. Not least among them the horrid viy, who massacred its mage-creator and destroyed half of Maribor before fleeing into Riverdell's gloomy woodland."}, {"a": 1051, "n": "Alzur's Thunder", "c": "Spell", "r": "Common", "f": "Neutral", "t": "Special", "fl": "We stand not the slightest chance of incanting a spell so complex as Alzur's Thunder. It is claimed Alzur had a voice like a hunting horn and the diction of a master orator."}, {"a": 1052, "n": "Biting Frost", "c": "Nature", "r": "Rare", "f": "Neutral", "t": "Special", "fl": "Best thing about frost? Bodies of the fallen don't rot so quickly."}, {"a": 1053, "n": "Clear Skies", "c": "Nature", "r": "Common", "f": "Neutral", "t": "Special", "fl": "The sun's shinin', Dromle! The sun's shinin'! Maybe there's hope after all…"}, {"a": 1054, "n": "Impenetrable Fog", "c": "Nature", "r": "Rare", "f": "Neutral", "t": "Special", "fl": "A good commander's dream… and a bad one's horror."}, {"a": 1055, "n": "Manticore Venom", "c": "Organic", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "Kills quicker than you can recite the Emperor of Nilfgaard's title in full."}, {"a": 1056, "n": "Adrenaline Rush", "c": "Organic", "r": "Rare", "f": "Neutral", "t": "Special", "fl": "The beast rushed at them wildly, with fury in its eyes, immune to pain and any strikes the defenders could land. Nothing stood to stop it…"}, {"a": 1057, "n": "Epidemic", "c": "Organic", "r": "Rare", "f": "Neutral", "t": "Special", "fl": "Epidemics respect no persons, no borders."}, {"a": 1058, "n": "Scorch", "c": "Spell", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "Geralt took one step back. He'd seen men hit by Scorch before. Or more accurately, seen what remained of them afterwards."}, {"a": 1059, "n": "Swallow", "c": "Alchemy", "r": "Common", "f": "Neutral", "t": "Special", "fl": "Symbolizing spring and rejuvenation, the swallow lent its name to this potion that accelerates the rate at which wounds scab over and heal."}, {"a": 1060, "n": "Thunderbolt", "c": "Alchemy", "r": "Common", "f": "Neutral", "t": "Artifact", "fl": "The witcher's face changed… his mien turning inhuman, horrifying."}, {"a": 1061, "n": "Torrential Rain", "c": "Nature", "r": "Rare", "f": "Neutral", "t": "Special", "fl": "Even the rain in this land smells vile."}, {"a": 1062, "n": "An Craite Warcrier", "c": "Human, Warrior", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "Every man, woman and child in Skellige can split a foe with an axe. Only a select few can split enemy ears with a rage-filled cry."}, {"a": 1063, "n": "Bekker's Dark Mirror", "c": "Spell", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "Gaze long into the abyss, and the abyss will gaze back into you."}, {"a": 1064, "n": "Renew", "c": "Spell", "r": "Legendary", "f": "Neutral", "t": "Special", "fl": "Medicus curat, magicae sanat."}, {"a": 1065, "n": "Dimeritium Shackles", "c": "Alchemy", "r": "Common", "f": "Neutral", "t": "Special", "fl": "The mage's arms were twisted and bound behind his back. The Redanians gave the fetters a good shake. Terranova cried out, lurched, bent backwards, bowed forward, then retched and groaned. It was clear of what his manacles were made."}, {"a": 1068, "n": "Mardroeme", "c": "Alchemy", "r": "Common", "f": "Skellige", "t": "Special", "fl": "Eat enough of them, and the world will never be the same…"}, {"a": 1073, "n": "Bloody Baron", "c": "Human, Soldier", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "I've not been a good father, I know, but… perhaps it's not too late."}, {"a": 1074, "n": "Vernon Roche", "c": "Human, Soldier", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "A patriot… and a real pain in the rear."}, {"a": 1075, "n": "John Natalis", "c": "Human, Soldier", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "That square should bear the names of my soldiers, of the dead. Not mine."}, {"a": 5192, "n": "Lined Pockets", "c": "Leader", "r": "Legendary", "f": "Syndicate", "t": "Ability", "fl": "Really believe you can dupe me with that tale you just pulled from your arse?"}, {"a": 1078, "n": "Shani", "c": "Human", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "I'm a medic. I tend to know what I'm doing when I prescribe something."}, {"a": 1079, "n": "Triss: Butterflies", "c": "Human, Mage", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Cap'n… our arrows, they've… they've got wings!"}, {"a": 1080, "n": "Keira Metz", "c": "Human, Mage", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "If I'm to die today, I wish to look smashing for the occasion."}, {"a": 1081, "n": "Dandelion", "c": "Human, Agent", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "Dandelion, you're a cynic, a lecher, a liar – and my best friend."}, {"a": 1082, "n": "Priscilla", "c": "Human, Agent", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "Picture Dandelion in a dress and you've got the general idea."}, {"a": 1083, "n": "Thaler", "c": "Human, Agent", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "Piss off! We aren't all philanderers. Some of us have depth…"}, {"a": 1084, "n": "Ves", "c": "Human, Soldier", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "Better to live one day as a king than a whole life as a beggar."}, {"a": 1085, "n": "Síle de Tansarville", "c": "Human, Mage", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "The Lodge lacks humility. Our lust for power may yet be our undoing."}, {"a": 1086, "n": "Sabrina Glevissig", "c": "Human, Mage", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "The Daughter of the Kaedweni Wilderness."}, {"a": 1087, "n": "Dethmold", "c": "Human, Mage", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "I once made a prisoner vomit his own entrails… Ah, good times…"}, {"a": 1088, "n": "Prince Stennis", "c": "Human, Knight", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "He wears armor made of gold. Of course he's a jerk."}, {"a": 1089, "n": "Trollololo", "c": "Ogroid, Soldier", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "Join me King Ravodid army. Order got – guard boatses."}, {"a": 1090, "n": "Princess Pavetta", "c": "Human", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "They said the queen was prone to outbursts, but I did not expect that…"}, {"a": 1091, "n": "Margarita Laux-Antille", "c": "Human, Mage", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "I care only about what's good for Aretuza and my pupils."}, {"a": 1092, "n": "Nenneke", "c": "Human", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "Few know more about healing than Nenneke."}, {"a": 1093, "n": "Odrin", "c": "Human, Soldier", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "Drinkin' without Odrin is like rowin' without a paddle."}, {"a": 1094, "n": "Kaedweni Sergeant", "c": "Human, Soldier", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "Forward, you sorry sods! Forward or you'll see the Nilfgaardians are the least of your worries!"}, {"a": 1095, "n": "Carlo Varese", "c": "Dwarf, Bandit", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Everyone wantin' to trade in Novigrad's got a clear choice - agree terms with Cleaver or kiss their knees farewell."}, {"a": 1096, "n": "Ballista", "c": "Machine, Siege Engine", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "What crossbows want to be when they grow up."}, {"a": 1097, "n": "Reinforced Ballista", "c": "Machine, Siege Engine", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "Never manages to hit the same place twice, which, upon further reflection, might constitute a real problem."}, {"a": 1098, "n": "Bombardment", "c": "Warfare", "r": "Common", "f": "Northern Realms", "t": "Special", "fl": "Castle won't batter itself down, now will it? Get them trebuchets rollin'!"}, {"a": 1099, "n": "Siege Tower", "c": "Machine, Siege Engine", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "The latest rage in assaults on walled cities."}, {"a": 1107, "n": "Redanian Knight", "c": "Human, Soldier, Knight", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "For glory! For Radovid!"}, {"a": 1108, "n": "Siege Support", "c": "Human, Soldier", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "You gotta recalibrate the arm by five degrees.\\nDo what by the what now?"}, {"a": 1109, "n": "Blue Stripes Scout", "c": "Human, Soldier", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "Blue Stripes and Scoia'tael are similar in one regard – hatred fuels both."}, {"a": 1111, "n": "Blue Stripes Commando", "c": "Human, Soldier", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "I'd do anything for Temeria. Mostly though, I kill for her."}, {"a": 1113, "n": "Field Medic", "c": "Human", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "Stitch red to red, white to white, and everything will be all right."}, {"a": 1114, "n": "Dun Banner", "c": "Human, Soldier", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "Stay calm, everyone. And be alert. The true owners of those cloaks and beaver–skin caps might be elsewhere."}, {"a": 1115, "n": "Kaedweni Cavalry", "c": "Human, Soldier", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "Always wondered – how the blazes do those lads handle nature's call…?"}, {"a": 1116, "n": "Reinforced Trebuchet", "c": "Machine, Siege Engine", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "Feel that? The earth trembles each time Big Bertha looses a stone."}, {"a": 1118, "n": "Temerian Infantry", "c": "Human, Soldier", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "Temeria! Temeria! Gods shed all grace on thee! And smite thy foes with horrid woes, for all eternity!"}, {"a": 1120, "n": "Redanian Elite", "c": "Human, Soldier", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "I'll die for Redania, I'll kill for Redania… I'll even eat worms for Redania!"}, {"a": 1121, "n": "Siege Master", "c": "Human, Soldier", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "I never miss twice."}, {"a": 1122, "n": "Botchling", "c": "Cursed", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "Admit your mistakes and bury them proper – else they'll come back to haunt you."}, {"a": 1124, "n": "Vicovaro Novice", "c": "Human, Mage", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "Mages in Nilfgaard are disposable. If one disappoints the Emperor, a dozen others await to provide what he requires."}, {"a": 1125, "n": "Reinforcements", "c": "Warfare", "r": "Epic", "f": "Northern Realms", "t": "Special", "fl": "Sound the retreat! Regroup! And wait for reinforcements!"}, {"a": 5160, "n": "Carapace", "c": "Leader", "r": "Legendary", "f": "Monster", "t": "Ability", "fl": "Have some dignity. You know how this will end."}, {"a": 1128, "n": "Ge'els", "c": "Elf, Wild Hunt", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "Paintings should convey emotion, not words."}, {"a": 1130, "n": "Draug", "c": "Specter, Cursed, Knight", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "Some men cannot admit defeat. Some keep fighting from beyond the grave."}, {"a": 1131, "n": "Imlerith's Wrath", "c": "Wild Hunt", "r": "Legendary", "f": "Monster", "t": "Special", "fl": "He boasted that no weapon would ever pierce his armor. And he was right — even in death."}, {"a": 5161, "n": "Force of Nature", "c": "Leader", "r": "Legendary", "f": "Monster", "t": "Ability", "fl": "We never hunt in these woods. Not even if it means the whole village'll starve."}, {"a": 1133, "n": "Caranthir Ar-Feiniel", "c": "Elf, Wild Hunt, Mage", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "A favorite son who chose a life of villainy."}, {"a": 1134, "n": "Avallac'h", "c": "Elf, Mage", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "You humans have… unusual tastes."}, {"a": 1135, "n": "Caretaker", "c": "Relict", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "There are more things in heaven and earth than all the world's philosophers have dreamt."}, {"a": 1136, "n": "Kayran", "c": "Insectoid", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "How to kill a kayran? Simple! Take your best sword… then sell it, and hire a witcher."}, {"a": 1137, "n": "Miruna", "c": "Relict", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "Why fight? There are much better ways to work off excess energy…"}, {"a": 1138, "n": "Arachas Behemoth", "c": "Insectoid", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "Like a cross between a crab, a spider… and a mountain."}, {"a": 1139, "n": "Mourntart", "c": "Necrophage", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "Most grave hags feed on rotten remains dug out of graves. Yet some sneak into huts, steal children, kill the elderly and in general make very undesirable neighbors."}, {"a": 1140, "n": "Abaya", "c": "Necrophage", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "Seen a lot o' ugly critters in me life – morays, lampreys, blobfish… But never nothin' like this!"}, {"a": 1141, "n": "Frightener: Dormant", "c": "", "r": "Epic", "f": "Monster", "t": "Artifact", "fl": "”What have I done?” the mage cried out, frightened of his own creation."}, {"a": 1142, "n": "Morvudd", "c": "Relict", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "Ate only the entrails. Fussy."}, {"a": 1143, "n": "Whispess", "c": "Relict, Crone", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "I'd be your best – and last."}, {"a": 1144, "n": "Brewess", "c": "Relict, Crone", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "We'll cut you up, boy. A fine broth you'll make."}, {"a": 1145, "n": "Weavess", "c": "Relict, Crone", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "I sense your pain. I see your fear."}, {"a": 1146, "n": "Imperial Manticore", "c": "Beast", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "One of the world's oldest and deadliest monsters. I used to feel excitement at moments like this. Now the beast is only an obstacle in my way. Its meat and hot blood will help me survive this icy hell."}, {"a": 1147, "n": "Colossal Ifrit", "c": "Construct", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Can't stand the heat? Then you don't stand a chance."}, {"a": 1148, "n": "Nekker Warrior", "c": "Ogroid, Warrior", "r": "Common", "f": "Monster", "t": "Unit", "fl": "Take heed, gents, there's nekkers under this here bridge."}, {"a": 1149, "n": "Ice Giant", "c": "Ogroid", "r": "Common", "f": "Monster", "t": "Unit", "fl": "Fled one time in my life. From the Ice Giant. And I'm not a bit ashamed."}, {"a": 1150, "n": "Primordial D'ao", "c": "Construct", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "How do you fight an earth elemental? You don't. You run. Fast as you can."}, {"a": 1151, "n": "Nithral", "c": "Elf, Wild Hunt, Warrior", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "Each Wild Hunt warrior has gone through a rigorous selection process, but Eredin's personal cavalcade includes only the most brutal and most ferocious of the Aen Elle."}, {"a": 1152, "n": "Gaunter O'Dimm", "c": "Demon", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "He always grants exactly what you wish for. That's the problem."}, {"a": 1153, "n": "Toad Prince", "c": "Beast, Cursed", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "Big, bad, ugly. Squats in the sewers."}, {"a": 1154, "n": "Celaeno Harpy", "c": "Beast", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "Common harpies feed on carrion. Celaeno harpies… they feed on dreams."}, {"a": 1155, "n": "Old Speartip: Asleep", "c": "Ogroid", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "Do not disturb."}, {"a": 1157, "n": "Katakan", "c": "Vampire", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "Drinking the blood of the Continent since the Conjunction."}, {"a": 1158, "n": "Foglet", "c": "Necrophage", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "Fog creeps on little cat feet. Foglets creep over the bodies of their victims."}, {"a": 1159, "n": "Ancient Foglet", "c": "Necrophage", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "Many primal fears lurk in the hearts of men. The fear of the mist is well–founded…"}, {"a": 1160, "n": "Wyvern", "c": "Beast", "r": "Common", "f": "Monster", "t": "Unit", "fl": "Imagine a cross between a winged snake and a nightmare. Wyverns are worse."}, {"a": 1162, "n": "Nekker", "c": "Ogroid", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "These little guys are almost cute, if you ignore the whole vicious killer aspect."}, {"a": 1163, "n": "Ghoul", "c": "Necrophage", "r": "Common", "f": "Monster", "t": "Unit", "fl": "If ghouls are part of the Circle of Life… then it's one vicious circle."}, {"a": 1164, "n": "Griffin", "c": "Beast", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "Griffins like to toy with their prey. Eat 'em alive, piece by piece."}, {"a": 1165, "n": "Vran Warrior", "c": "Beast, Warrior", "r": "Common", "f": "Monster", "t": "Unit", "fl": "They sat still on their horses, seemingly relaxed. He saw their weapons – short spears with wide tips. Swords with oddly forged guards. Battle axes. Toothed gisarmes."}, {"a": 1166, "n": "Wild Hunt Warrior", "c": "Elf, Wild Hunt, Warrior", "r": "Common", "f": "Monster", "t": "Unit", "fl": "The White Frost is coming."}, {"a": 1168, "n": "Wild Hunt Rider", "c": "Elf, Wild Hunt, Warrior", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "First the buffalo horns atop their helms penetrate one's view, then the crest betwixt them, and finally the skull–like face exposed beneath their visors."}, {"a": 1170, "n": "Predatory Dive", "c": "Organic", "r": "Common", "f": "Monster", "t": "Special", "fl": "Afraid for their lives, the residents of Hengfors cowered behind thick city walls. A lot of good that did them..."}, {"a": 1172, "n": "Drowner", "c": "Necrophage", "r": "Common", "f": "Monster", "t": "Unit", "fl": "Though the witchman lusts for gold, for the smiting of a drowner thou shalt give him but a silver penny, or three halfpence, at most."}, {"a": 1174, "n": "Harpy Egg", "c": "Beast", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "A harpy egg omelet - a delicious delicacy, good sir. Quite dear, too, for as you might surmise, the wretches don't part with their eggs willingly."}, {"a": 1175, "n": "Wild Hunt Hound", "c": "Beast, Wild Hunt", "r": "Common", "f": "Monster", "t": "Unit", "fl": "Cry 'Havoc!', and let slip the dogs of war."}, {"a": 1176, "n": "Wolf Pack", "c": "Beast", "r": "Common", "f": "Neutral", "t": "Unit", "fl": "Relax, I know how to tame wolves…– Dunbar the Hunter's last words."}, {"a": 1177, "n": "Enraged Ifrit", "c": "Construct", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "A certain mage thought them cute. It was his fate that gave rise to the saying Don't play with fire…"}, {"a": 1178, "n": "Frenzied D'ao", "c": "Construct", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "They're easily mistaken for rocks. Many a troll's been unpleasantly surprised by gastric grief on that very account."}, {"a": 1179, "n": "Maerolorn", "c": "Relict", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "No gate nor wall can stop them. Just one tiny crack — that's all they need..."}, {"a": 1180, "n": "Imperial Golem", "c": "Construct", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "The most powerful of Nilfgaard's mages have mastered the art of creating golems. On a few occasions, they've even managed to make them fight for the imperial cause…"}, {"a": 1181, "n": "Old Speartip", "c": "Ogroid", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "Oh, you're in a heap of trouble now…"}, {"a": 1182, "n": "Hideous Feast", "c": "Organic", "r": "Rare", "f": "Monster", "t": "Special", "fl": "The fool paid heed to superstition, stuffed his ears with wax and didn't hear the warnings. He ran his ship straight into the rocks."}, {"a": 1588, "n": "Wyvern Scale Shield", "c": "", "r": "Rare", "f": "Neutral", "t": "Special", "fl": "Stronger than your average shield and far more stylish."}, {"a": 1184, "n": "Arachas Nest", "c": "Organic", "r": "Common", "f": "Monster", "t": "Special", "fl": "Damn, the filth's o'errun us… We need a witcher or there's no livin' 'ere!"}, {"a": 1188, "n": "Saesenthessis", "c": "Dragon", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "I inherited my father's ability to assume other forms - well, one other form, in my case."}, {"a": 1189, "n": "Isengrim Faoiltiarna", "c": "Elf, Soldier, Bandit", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "It dawns on them once they notice my scar: a realization of imminent death."}, {"a": 1190, "n": "Iorveth", "c": "Elf, Soldier, Bandit", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "King or beggar, what's the difference? One dh'oine less."}, {"a": 1191, "n": "Milva", "c": "Human", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "With each arrow I loose, I think of my da. He'd be proud. I think."}, {"a": 1192, "n": "Zoltan Chivay", "c": "Dwarf", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "Drinkin' alone's like crappin' with company."}, {"a": 1193, "n": "Aglaïs", "c": "Dryad", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "Brokilon bleeds… and not even I can heal it."}, {"a": 1194, "n": "Ithlinne Aegli", "c": "Elf, Mage", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "Famed for constantly prophesying the world's doom. Not much fun at parties."}, {"a": 1195, "n": "Schirrú", "c": "Elf, Agent, Bandit", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "Time to look death in the face."}, {"a": 1196, "n": "Dennis Cranmer", "c": "Dwarf, Soldier", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "I know how to execute orders, so take your advice somewhere else."}, {"a": 1197, "n": "Ida Emean aep Sivney", "c": "Elf, Mage", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "I am a Sage. My power lies in possessing knowledge. Not sharing it."}, {"a": 1198, "n": "Yaevinn", "c": "Elf, Soldier, Bandit", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "We are the drops of rain that together make a ferocious storm."}, {"a": 1199, "n": "Toruviel", "c": "Elf, Soldier, Bandit", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "I'd gladly kill you from up close, stare in your eyes… But you reek, human."}, {"a": 1200, "n": "Vrihedd Dragoon", "c": "Elf, Soldier", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "Most terrible things I've witnessed? The Catriona plague, the razing of Vengerberg and the charge of the Vrihedd Dragoons."}, {"a": 1201, "n": "Ciaran aep Easnillen", "c": "Elf, Bandit", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "The path to freedom is paved in blood, not ink."}, {"a": 1202, "n": "Barclay Els", "c": "Dwarf, Soldier", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "Our mead smells rotten to ye, do it? Easy to fix – I'll break yer nose!"}, {"a": 1203, "n": "Morenn", "c": "Dryad, Warrior", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "Lady Eithné's daughter had inherited her sublime beauty and her wild hatred for all that is human."}, {"a": 1204, "n": "Braenn", "c": "Dryad, Warrior", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "Mona…? No… no. I'm Braenn. A daughter of Brokilon."}, {"a": 1205, "n": "Malena", "c": "Elf, Bandit", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "I hate you, dh'oine. You are all the same."}, {"a": 1206, "n": "Aelirenn", "c": "Elf, Warrior", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "Better to die standing than to live on bent knee."}, {"a": 1207, "n": "Sheldon Skaggs", "c": "Dwarf, Soldier", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "I was there, on the front lines! Right where the fightin' was the thickest!"}, {"a": 1208, "n": "Yarpen Zigrin", "c": "Dwarf, Warrior", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "Ever hear o' the dragon Ocvist? From Quartz Mountain? Well, Yarpen Zigrin and his band o' dwarves did 'im in."}, {"a": 1209, "n": "Ele'yas", "c": "Elf, Bandit", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "Love justifies madness in any of its forms."}, {"a": 1210, "n": "Hawker Healer", "c": "Elf", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "Sure, I'll patch you up. Gonna cost you though."}, {"a": 1211, "n": "Vrihedd Brigade", "c": "Elf, Soldier", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "Vrihedd? What's that mean? Trouble."}, {"a": 1212, "n": "Vrihedd Officer", "c": "Elf, Soldier", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "Hatred burns brighter than any fire, and cuts deeper than any blade."}, {"a": 1213, "n": "Dol Blathanna Bomber", "c": "Elf, Soldier, Agent", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "They track like hounds, run like deer and kill like heartless demons."}, {"a": 1214, "n": "Dwarven Skirmisher", "c": "Dwarf, Soldier", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "Worked a pickaxe all me life. Battleaxe won't be any trouble."}, {"a": 1215, "n": "Mahakam Defender", "c": "Dwarf, Soldier", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "I'm telling ye, we're born fer battle – we slash straight at their knees!"}, {"a": 1216, "n": "Vrihedd Sappers", "c": "Elf, Soldier", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "No matter what you may have heard, elves don't take human scalps. Too much lice."}, {"a": 1217, "n": "Waylay", "c": "Tactic", "r": "Rare", "f": "Scoiatael", "t": "Special", "fl": "I spit on Scoia'tael ideals, but not on their coin."}, {"a": 1218, "n": "Vrihedd Vanguard", "c": "Elf, Soldier", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "Temerians, Redanians, all the same. Better off dead."}, {"a": 1219, "n": "Dol Blathanna Archer", "c": "Elf, Soldier", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "Take another step, dh'oine. You'd look better with an arrow between your eyes."}, {"a": 1220, "n": "Dwarven Mercenary", "c": "Dwarf, Soldier", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "The key's mixin' pleasure an' business – like smackin' foes and gettin' coin for it."}, {"a": 1221, "n": "Hawker Support", "c": "Human, Bandit", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "Elf, dwarf, makes no difference – long as they've got coin."}, {"a": 1222, "n": "Elven Wardancer", "c": "Elf, Agent", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "You mean to say the she–elf danced amidst the fray? Have you lost your mind, corporal?!"}, {"a": 1223, "n": "Dol Blathanna Bowman", "c": "Elf, Soldier", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "You might manage to hide from them, but once spotted, don't bother trying to run."}, {"a": 1224, "n": "Hawker Smuggler", "c": "Human, Bandit", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "I fight for whoever's paying the best. Or whoever's easiest to rob."}, {"a": 1225, "n": "Blue Mountain Elite", "c": "Elf, Agent", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "By the time we'd heard them, it was already too late…"}, {"a": 1226, "n": "Mahakam Guard", "c": "Dwarf, Soldier", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "Only one punishment for disturbin' the peace in Mahakam: a hammer to the heid."}, {"a": 1227, "n": "Scoia'tael Neophyte", "c": "Elf, Bandit", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "Many nonhumans, fed up with the racism and xenophobia they encounter in the cities, decide to join the Scoia'tael."}, {"a": 1228, "n": "Serpent Trap", "c": "Trap", "r": "Epic", "f": "Scoiatael", "t": "Artifact", "fl": "You exact from the earth a blood ransom, ripping out its riches by force. To us it bloomed, bore fruit and gave freely, for it loved us as we loved it."}, {"a": 1229, "n": "Incinerating Trap", "c": "Trap", "r": "Rare", "f": "Scoiatael", "t": "Artifact", "fl": "Careful…! One more step and you'll be turned into molten glass."}, {"a": 1233, "n": "Hjalmar an Craite", "c": "Human, Warrior", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "Instead of mournin' the fallen, let's drink to their memory!"}, {"a": 1234, "n": "Ermion", "c": "Human, Druid", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "Only the ignorant dismiss the importance of myths."}, {"a": 1235, "n": "Kambi", "c": "Beast", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "When the time comes, the cockerel Kambi shall crow and awaken Hemdall."}, {"a": 1236, "n": "Birna Bran", "c": "Human", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "Skellige must have a strong king. No matter what it takes."}, {"a": 1237, "n": "Madman Lugos", "c": "Human, Warrior", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "WAAAAAAAAAAGH!!!!"}, {"a": 1238, "n": "Coral", "c": "Human, Mage", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "Her true name's Astrid Lyttneyd Ásgeirrfinnbjornsdottir, but that never fit on any forms."}, {"a": 1239, "n": "Wild Boar of the Sea", "c": "Machine, Ship", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "Merely mention this name to a Nilfgaardian, and they'll feel a spreading warmth in their knickers…"}, {"a": 1240, "n": "Blueboy Lugos", "c": "Human, Warrior", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "I'm near ready to puke from boredom."}, {"a": 1241, "n": "Champion's Charge", "c": "Raid", "r": "Epic", "f": "Skellige", "t": "Special", "fl": "At close range, trolls never use weapons. And why would they?"}, {"a": 1242, "n": "Djenge Frett", "c": "Human", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "When a warrant says dead or alive, most bounty hunters'll just kill you. Not me. Should I catch you, you'll hang, and I'll tickle your feet as you expire."}, {"a": 1243, "n": "Donar an Hindar", "c": "Human, Warrior", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "I've gathered all the jarls together. Now make your case."}, {"a": 1244, "n": "Draig Bon-Dhu", "c": "Human", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "Hear ye now the tale of the heroic deeds of Clan an Craite."}, {"a": 1245, "n": "Gremist", "c": "Human, Druid", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "An archdruid, a master of alchemy, and the grumpiest old fart in the Isles."}, {"a": 1246, "n": "Holger Blackhand", "c": "Human, Pirate", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "Now let's drink to the Emperor of Nilfgaard – may he die of somethin' hideous!"}, {"a": 1247, "n": "Jutta an Dimun", "c": "Human, Warrior", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "Some call her the Iron Maiden."}, {"a": 1248, "n": "Morkvarg", "c": "Beast, Cursed, Pirate", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "The vilest man Skellige's ever known."}, {"a": 1249, "n": "Savage Bear", "c": "Beast", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "Tame? Och, lad, Skelligers might train bears, but that don't at all mean they tame 'em…"}, {"a": 1250, "n": "Sigrdrifa's Rite", "c": "Alchemy", "r": "Epic", "f": "Skellige", "t": "Special", "fl": "Fall on your knees and beg Modron Freya for forgiveness."}, {"a": 1251, "n": "Svanrige Tuirseach", "c": "Human, Warrior", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "The emperor also thought him an accidental king. At first."}, {"a": 1252, "n": "Udalryk an Brokvar", "c": "Human, Cursed, Warrior", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "The gods have spoken: a sacrifice is required."}, {"a": 1253, "n": "Svalblod Ravager", "c": "Human, Cultist, Warrior", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "A two-handed axe? Seems no one told him that."}, {"a": 1254, "n": "Svalblod Butcher", "c": "Human, Cultist, Warrior", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "Mercenaries fight for coin. Knights duel for honor. He kills for blood."}, {"a": 1255, "n": "An Craite Warrior", "c": "Human, Warrior", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "Our clan's bards will sing of my deeds long after you're dead and forgotten!"}, {"a": 1256, "n": "Brokvar Hunter", "c": "Human, Warrior", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "Better believe we can hunt. Thing is, not much game on Spikeroog…"}, {"a": 1257, "n": "Dimun Pirate", "c": "Human, Pirate", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "Can see the fear in their eyes. Fear o' me… fear o' Clan Dimun!"}, {"a": 1258, "n": "Dimun Pirate Captain", "c": "Human, Pirate", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "Haul together, hoist the colors high!"}, {"a": 1260, "n": "Drummond Queensguard", "c": "Human, Warrior", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "The queen is guarded by the hardiest and fiercest shieldmaidens Skellige's ever known."}, {"a": 1262, "n": "Heymaey Skald", "c": "Human", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "The deeds of Clan Heymaey will go down in history."}, {"a": 1263, "n": "Dimun Light Longship", "c": "Machine, Ship", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "Escape them? In the waters of Skellige? Good luck."}, {"a": 1264, "n": "Freya's Blessing", "c": "Alchemy", "r": "Common", "f": "Skellige", "t": "Special", "fl": "Modron Freya, the Great Mother, is the goddess of love, beauty and bounty."}, {"a": 1265, "n": "An Craite Blacksmith", "c": "Human", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "Remember me words – a good shield can save yer life."}, {"a": 1266, "n": "Tuirseach Axeman", "c": "Human, Warrior", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "Swords are for wenches. Get yourself an axe."}, {"a": 1267, "n": "Tuirseach Skirmisher", "c": "Human, Warrior", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "Friends we show heart, foes we show our axe. Remember that."}, {"a": 1268, "n": "An Craite Longship", "c": "Machine, Ship", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "They say Hemdall's heart swells whenever the longships sail out on a raid."}, {"a": 1269, "n": "Brokvar Archer", "c": "Human, Warrior", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "So ye can hit a movin' target at two hundred paces? Me, too. In a storm."}, {"a": 1270, "n": "Gutting Slash", "c": "Raid", "r": "Rare", "f": "Skellige", "t": "Special", "fl": "Man or tree, a Skelligan axe fells it all the same."}, {"a": 1271, "n": "An Craite Armorsmith", "c": "Human", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "Ye're in for a poundin'."}, {"a": 1273, "n": "Drummond Shieldmaiden", "c": "Human, Warrior", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "They'll shatter on our shields like waves on a craggy shore."}, {"a": 1276, "n": "Hemdall", "c": "Human, Warrior", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "When the time of the White Frost comes, Hemdall will sound the call for battle."}, {"a": 1277, "n": "Delirium", "c": "Alchemy", "r": "Epic", "f": "Skellige", "t": "Special", "fl": "Ehh, too big for a humpback. That's a finback. A finback? With a snout that short? Those herbs've gone to your head!"}, {"a": 1278, "n": "Elder Bear", "c": "Beast", "r": "Common", "f": "Neutral", "t": "Unit", "fl": "We're going on a bear hunt! We're going to catch a–– THAT THING'S HUGE! RUN!"}, {"a": 1279, "n": "Raging Bear", "c": "Beast", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "Roooaaar!!!"}, {"a": 1280, "n": "Restore", "c": "Alchemy", "r": "Epic", "f": "Skellige", "t": "Special", "fl": "Those cursed sorceresses are stealing our thunder! Whyever should folk choose a procedure taking several hours, when some perfumed tart can solve their problem with a wave of her hand?"}, {"a": 1281, "n": "Lacerate", "c": "Organic", "r": "Common", "f": "Neutral", "t": "Special", "fl": "A sight more horrid you've never seen… The poor soul lay shredded as the beast lapped up its blood from the ground all around."}, {"a": 1285, "n": "Letho of Gulet", "c": "Witcher", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "Witchers never die in their beds."}, {"a": 1286, "n": "Menno Coehoorn", "c": "Human, Soldier", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "I'll take an attentive reconnaissance unit over a fine brigade any day."}, {"a": 1287, "n": "Vattier de Rideaux", "c": "Human, Agent, Aristocrat", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "There's never been a problem a well–planned assassination couldn't solve."}, {"a": 1288, "n": "Cahir Dyffryn", "c": "Human, Soldier, Knight, Aristocrat", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "His eyes flashed under his winged helmet. Fire gleamed from his sword's blade."}, {"a": 1289, "n": "Vilgefortz", "c": "Human, Mage", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "We are all pawns on his board. Playing a game whose rules we do not know."}, {"a": 1290, "n": "Stefan Skellen", "c": "Human, Agent", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "My mark scars the face of our future empress. That is my proudest achievement."}, {"a": 1291, "n": "Tibor Eggebracht", "c": "Human, Soldier", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "Tibor's zeal was legendary. It was said when the emperor passed, he'd not so much bow as somersault."}, {"a": 1292, "n": "Xarthisius", "c": "Human, Mage", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "Astrology, hydromancy, haruspicy, ceromancy. Ovomancy, spodomancy, metroscopy, brontoscopy…"}, {"a": 1293, "n": "Albrich", "c": "Human, Mage", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "A ball of fire? Why, naturally. Whatsoever Your Imperial Majesty desires."}, {"a": 1294, "n": "Assire var Anahid", "c": "Human, Mage", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "Nilfgaardian mages do have a choice: servile submission, or the gallows."}, {"a": 1295, "n": "Cynthia", "c": "Human, Mage", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "Cynthia's talents can be deadly. She needs a tight leash."}, {"a": 1296, "n": "Peter Saar Gwynleve", "c": "Human, Soldier", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "These are not the hands of an Excellency, but of a farmer. So we speak peasant to peasant."}, {"a": 1297, "n": "Fringilla Vigo", "c": "Human, Mage", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "Magic is the highest good. It transcends all borders and divisions."}, {"a": 1298, "n": "Sweers", "c": "Human, Soldier, Knight", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "And hands off the girl! Whatever we may be, we're not savages."}, {"a": 1299, "n": "Vanhemar", "c": "Human, Mage", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "For a fire mage, he's not very… flamboyant."}, {"a": 1300, "n": "Auckes", "c": "Witcher", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "Letho's got a plan… what could go wrong?"}, {"a": 1301, "n": "Serrit", "c": "Witcher", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "We do what we must. I am not ashamed of that."}, {"a": 1302, "n": "Cantarella", "c": "Human, Agent", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "Men require constant alluring. Mystique and refinement do the job quite well."}, {"a": 1303, "n": "Joachim de Wett", "c": "Human, Soldier, Aristocrat", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "To describe the manner in which Duke de Wett led the Verden Group as incompetent would be far too kind."}, {"a": 1304, "n": "False Ciri", "c": "Human, Agent, Aristocrat", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "Here she comes, he thought, our imperial interest. A mock-princess, a mock-queen for Cintra. A mock-ruler for the mouth of the Yarra, future lifeblood of the empire."}, {"a": 1305, "n": "Ceallach Dyffryn", "c": "Human, Aristocrat", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "Your Imperial Highness… blurted out the seneschal, whose presence until now had been thoroughly ignored. I beg your pardon, but Cahir… My son..."}, {"a": 1306, "n": "Daerlan Soldier", "c": "Human, Soldier", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "Learned a lot at Braibant Military Academy. How to scrub potatoes, for instance."}, {"a": 1307, "n": "Rot Tosser", "c": "Machine, Siege Engine", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "Let historians debate whether spreading plague in a besieged city is ethical. We just care if it's effective."}, {"a": 1308, "n": "Spotter", "c": "Human, Soldier", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "The North has nothing with which it could surprise us."}, {"a": 1309, "n": "Experimental Remedy", "c": "Tactic", "r": "Rare", "f": "Nilfgaard", "t": "Special", "fl": "Well... At least, I can't make you more dead..."}, {"a": 1310, "n": "Deithwen Arbalest", "c": "Human, Soldier", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "I aim for the knees. Always."}, {"a": 1311, "n": "Fire Scorpion", "c": "Machine, Siege Engine", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "Name's terribly misleading, makes it sound like some corpulent reddish arachnid, not an exquisitely engineered weapon of mass destruction..."}, {"a": 1312, "n": "Impera Brigade", "c": "Human, Soldier", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "The Impera Brigade never surrenders. Ever."}, {"a": 1313, "n": "Impera Enforcers", "c": "Human, Soldier", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "Members of the emperor's fanatic body guard fight to the bitter end."}, {"a": 1314, "n": "Nauzicaa Sergeant", "c": "Human, Soldier", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "The Emperor will teach the North discipline."}, {"a": 1315, "n": "Nauzicaa Brigade", "c": "Human, Soldier", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "They call us Death's Heads. Care to find out why?"}, {"a": 1316, "n": "Alba Pikeman", "c": "Human, Soldier", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "Pledge your allegiance to our Emperor, Emhyr var Emreis… or die."}, {"a": 1317, "n": "Alba Spearman", "c": "Human, Soldier", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "Death and glory!"}, {"a": 1318, "n": "Combat Engineer", "c": "Human", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "Want irrefutable proof of civilization's advance? Look at war. Man gets better at killing with each one."}, {"a": 1319, "n": "Emissary", "c": "Human, Agent", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "But… but there's no justice in it! One does not kill the messenger!"}, {"a": 1320, "n": "Imperial Diplomacy", "c": "Tactic", "r": "Rare", "f": "Nilfgaard", "t": "Special", "fl": "A spy? No, that's saying far too much. I consider myself more of an observer."}, {"a": 1321, "n": "Alchemist", "c": "Human", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "Two ounces of calcium equum, one ounce of rubedo…"}, {"a": 1322, "n": "Mangonel", "c": "Machine, Siege Engine", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "This model specializes in slinging corpses and ripe dung."}, {"a": 1323, "n": "Nilfgaardian Knight", "c": "Human, Soldier, Knight", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "Sons of noble houses, born in the City of the Golden Towers, form the elite backbone of the Imperial Army."}, {"a": 1326, "n": "Treason", "c": "Tactic", "r": "Epic", "f": "Nilfgaard", "t": "Special", "fl": "In Nilfgaard, trustful people are considered an endangered species."}, {"a": 1327, "n": "Bribery", "c": "Tactic", "r": "Legendary", "f": "Nilfgaard", "t": "Special", "fl": "Many believe the empire's power rests upon the shoulders of its disciplined army and dutiful mages. In truth, the Nilfgaardian floren rules the world."}, {"a": 1066, "n": "Petri's Philter", "c": "Alchemy", "r": "Common", "f": "Neutral", "t": "Artifact", "fl": "A mage responsible for dozens of brilliant inventions. The mind of a generation. Commonly referred to around the Continent as that bloke with the dish."}, {"a": 1330, "n": "Korathi Heatwave", "c": "", "r": "Legendary", "f": "Neutral", "t": "Special", "fl": "Vicovaro scholars have determined that, in the absence of imperial aid, drought-stricken provinces lose half their population, two-thirds of their livestock and all their will to rebel."}, {"a": 1331, "n": "Marching Orders", "c": "Tactic", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "We are but pawns in a game played by old men, sent to fight and die on their senile whims…"}, {"a": 1332, "n": "Necromancy", "c": "Spell", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "We have ways of making you talk… alive or dead."}, {"a": 1333, "n": "Summoning Circle", "c": "Spell", "r": "Epic", "f": "Neutral", "t": "Artifact", "fl": "There exist a great many realities outside our own… With the right knowledge, one can contact them and summon beings beyond human fathoming."}, {"a": 1002, "n": "Arachas Venom", "c": "Organic", "r": "Common", "f": "Neutral", "t": "Special", "fl": "If substance makes contact with eyes, rinse immediately with cold water, then commence drawing up will."}, {"a": 1334, "n": "Wild Hunt Navigator", "c": "Elf, Wild Hunt, Mage", "r": "Common", "f": "Monster", "t": "Unit", "fl": "For hundreds of years, Avallac'h tried to recreate the Elder Blood gene through back breeding - yet the elven children thus fostered were but dim sparks compared to Lara's flame."}, {"a": 1335, "n": "Vabjorn", "c": "Human, Cultist, Warrior", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "Blood for Svalblod! Skulls for his throne!"}, {"a": 1003, "n": "Milaen", "c": "Elf", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "The old baron treated poachers mercilessly. Luckily for Milaen, the old baron was dead and his men, desperate outlaws."}, {"a": 1336, "n": "Leo Bonhart", "c": "Human", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "He would just sit there and stare at me, not saying a word. His eyes, they were… fish-like, somehow. No brows, no lashes… Just these balls of water, with a black stone sunk in each. He would devour me with those eyes in total silence. That frightened me more than the beatings."}, {"a": 1337, "n": "Rainfarn of Attre", "c": "Human, Knight", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "When Cintra fell, Attre followed, leaving its defenders a choice: accept the Nilfgaardian leash or die."}, {"a": 1338, "n": "Aretuza Adept", "c": "Human, Mage", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "The adepts' every whim is catered to - they live like princesses at Aretuza. And in turn half the city lives off servicing them: seamstresses, milliners, confectioners, delivery boys…"}, {"a": 1340, "n": "Drummond Warmonger", "c": "Human, Pirate", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "Think o' the greater good?! War's the greatest good, the greatest bad, the greatest damn anythin' man's ever come up with!"}, {"a": 1341, "n": "Cyclops", "c": "Ogroid", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "Don't stare at his eye, he hates that…"}, {"a": 1342, "n": "Archespore", "c": "Plant, Cursed", "r": "Common", "f": "Monster", "t": "Unit", "fl": "Folklore claims they sprout from soil watered with the blood of the dying. Thus they flourish in grounds consecrated by pogroms, dark rituals or brutal murders."}, {"a": 1343, "n": "Dol Blathanna Sentry", "c": "Elf, Soldier", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "As long as we stand, no human foot shall trample Dol Blathanna's meadows."}, {"a": 1344, "n": "An Craite Greatsword", "c": "Human, Warrior", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "Ahh, ye gave me a good laugh there, Nordling! Why, this bastard, ye couldn't even grip it, let alone gut me with it."}, {"a": 1345, "n": "Hefty Helge", "c": "Machine, Siege Engine", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "Not the best for taking cities, but great for razing them to the ground."}, {"a": 1346, "n": "Mahakam Marauder", "c": "Dwarf, Warrior", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "Hunting on Mahakam's craggy cliffs is not particularly easy… but nor are dwarves particularly put off by danger."}, {"a": 1347, "n": "Harald Houndsnout", "c": "Human", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "Once proud jarl of Clan Tordarroch, now a muttering madman."}, {"a": 1348, "n": "Magne Division", "c": "Human, Soldier", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "I know the Emperor defends all his lands... but a garrison in this blasted waste is like a chastity belt on a grave hag."}, {"a": 1350, "n": "Tuirseach Veteran", "c": "Human, Warrior", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "In my days I've seen wonders no man's ever dreamt of, and done things no man should ever do."}, {"a": 1351, "n": "Ban Ard Tutor", "c": "Human, Mage", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "I'm constantly comparing the achievements of Aretuza's adepts with the work done by the lads at Ban Ard, and my conclusion constantly falls in favor of the girls."}, {"a": 1352, "n": "Battering Ram", "c": "Machine, Siege Engine", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "Not gonna open up, eh? Guess we gotta knock harder."}, {"a": 1353, "n": "Vreemde", "c": "Human, Soldier", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "The Great Sun shall warm the North with its rays, even if it means I must slaughter you all!"}, {"a": 1355, "n": "Golyat", "c": "Ogroid", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "Some claim Golyat was once a famous knight. Sadly, one day he earned the wrath of the Lady of the Lake, who turned him into a monster."}, {"a": 1356, "n": "Artefact Compression", "c": "Spell", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "The figurine expanded in a flash, pulsing and throbbing, changing its shape and structure like a puff of smoke crawling over the floor. Beams of light revealed movement and hardening materials. A moment later, in the center of the magic circle a human form suddenly appeared."}, {"a": 5162, "n": "White Frost", "c": "Leader", "r": "Legendary", "f": "Monster", "t": "Ability", "fl": "No one, not even among the higher vampires, knows exactly how old the Unseen Elder is. They only know they should never, under any circumstances, defy his will."}, {"a": 1359, "n": "Aguara: True Form", "c": "Beast", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Ever heard of an anterion? Think of it as the opposite of a lycanthrope: a beast which can take on human form."}, {"a": 1361, "n": "Uma's Curse", "c": "Spell", "r": "Legendary", "f": "Neutral", "t": "Special", "fl": "I give you three solid leads, trails as fresh as morning dew, the aid of my spies and my court sorceress. Yet in my daughter's stead, you bring me this… monstrosity?"}, {"a": 1365, "n": "Aguara", "c": "Beast", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Smarten up right now, or it's off to an aguara with you!"}, {"a": 1374, "n": "Shilard Fitz-Oesterlen", "c": "Human, Agent, Aristocrat", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "A diplomat is a man who uses many more words than necessary to express much less than he knows."}, {"a": 1376, "n": "Adda: Striga", "c": "Beast, Cursed", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "And the striga's doin' fine. Sure, she takes a bite outta someone from time to time, but you get used to that."}, {"a": 1381, "n": "Trial of the Grasses", "c": "Alchemy", "r": "Legendary", "f": "Neutral", "t": "Special", "fl": "Imagine a lump of clay. In order to shape it, you must first moisten it or it will crumble. The Trial's initial part does just that. It opens the body to change, so to speak. Only then can the mutagens produce a witcher."}, {"a": 1382, "n": "Hanmarvyn's Blue Dream", "c": "Spell", "r": "Legendary", "f": "Neutral", "t": "Special", "fl": "This spell lets you see the last moments of a dead man's life… if you can survive its casting."}, {"a": 1383, "n": "Xavier Moran", "c": "Dwarf, Warrior", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "Well? Somethin' wrong? Venison a wee bit rank for ye? Ehh, princess?"}, {"a": 1384, "n": "Heymaey Herbalist", "c": "Human, Druid", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "We don't burn cunning women in Skellige - we take their advice."}, {"a": 1386, "n": "Iris' Companions", "c": "Demon", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "We'd rather keep our names to ourselves. Think of us as… friends of the house."}, {"a": 1390, "n": "Dorregaray of Vole", "c": "Human, Mage", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Like the witchers, Dorregaray is a monster aficionado, though he's developed his own classification system. Instead of dividing them into necrophages, ogroids and the like, he just thinks they're all wonderful."}, {"a": 1391, "n": "Hubert Rejk", "c": "Vampire", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "The coroner is a calm, peaceful person. He even treats corpses with the utmost delicacy."}, {"a": 1392, "n": "Nivellen", "c": "Beast, Cursed", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Lost? Well, go be lost somewhere else. Somewhere not on my property, that is. Point your left ear to the sun and keep walking, you'll hit the road soon enough. Well? What're you waiting for?"}, {"a": 1394, "n": "Stregobor", "c": "Human, Mage", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "The witcher had met thieves that looked like town councilors, town councilors that looked like beggars and kings that looked like thieves. Stregobor, though, always looked exactly like the commonly accepted imagining of what a mage should look like."}, {"a": 1401, "n": "Vincent Meis", "c": "Beast, Cursed", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "By day, Captain of the Vizima City Guard. By night, merciless avenger and defender of the downtrodden."}, {"a": 1405, "n": "Hym", "c": "Specter", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "The gods' speak to me… I hear them whisper from the shadows…"}, {"a": 1406, "n": "Olaf", "c": "Beast", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "10-time winner of the venerable title of Champion of the An Skellig Arena."}, {"a": 1407, "n": "Ulfhedinn", "c": "Beast, Cursed", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "Werewolf? Oh, no, no… this is something far, far worse."}, {"a": 1408, "n": "Dimun Warship", "c": "Machine, Ship", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "Clan Dimun warships are light and fast, perfect for racing down slow merchant frigates."}, {"a": 1416, "n": "Siren", "c": "Beast", "r": "Common", "f": "Monster", "t": "Unit", "fl": "Legends claim they lure sailors to their doom with their entrancing songs… though more likely, the sailors were more entranced by their other ample charms."}, {"a": 1419, "n": "Alpha Werewolf", "c": "Beast, Cursed", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "The most ferocious among these cursed are not even deterred by silver and alchemy's fiery pains."}, {"a": 1420, "n": "Assassination", "c": "Tactic", "r": "Rare", "f": "Nilfgaard", "t": "Special", "fl": "Assassin — one of the most popular professions at the imperial court, just after scribe and courtesan."}, {"a": 1423, "n": "Infiltrator", "c": "Human, Agent", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "You can run, but you'll never hide."}, {"a": 1429, "n": "Kingslayer", "c": "Witcher", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "The School of the Viper shall be reborn… Letho saw to that."}, {"a": 1440, "n": "Pyrotechnician", "c": "Dwarf, Soldier", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "An extraordinarily risky, and thus much revered, Mahakam trade. Its best-known practitioner was a dwarf by the name of Mikkel Bay."}, {"a": 1441, "n": "Farseer", "c": "Elf, Mage", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "Her words might seem unintelligible at times, but they always contain hidden meanings and tremendous wisdom."}, {"a": 1443, "n": "Elven Scribe", "c": "Elf, Mage", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "Knowledge, my dear, is a privilege, and privileges are only shared among equals."}, {"a": 1444, "n": "Panther", "c": "Beast", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "An Oxenfurt scholar once examined a panther and declared it was nothing more than a leopard of a different color. The panther seemed indifferent to this pronouncement and gobbled him up before he could complete his research."}, {"a": 1449, "n": "Tuirseach Bearmaster", "c": "Human, Warrior", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "Don't touch him. Don't look him in the eyes. In fact… don't go anywhere near him."}, {"a": 1450, "n": "Dimun Corsair", "c": "Human, Pirate", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "The sea's ours, along with everythin' that floats, swims or sails in it!"}, {"a": 1451, "n": "Dimun Smuggler", "c": "Human, Pirate", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "Spikeroog's a barren backwater, but that don't bother us - everythin' we need, we take from you."}, {"a": 1452, "n": "Heymaey Flaminica", "c": "Human, Druid", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "A flaminica, the highest position among the druidesses, commands a great deal of respect and wields a great deal of power."}, {"a": 1454, "n": "Heymaey Protector", "c": "Human, Warrior", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "He fears nothing save Freya's wrath... and his wife's."}, {"a": 1458, "n": "Royal Decree", "c": "Tactic", "r": "Legendary", "f": "Neutral", "t": "Special", "fl": "We, Foltest, by divine right King of Temeria, Prince of Sodden, Senior Protector of Brugge, etcetera, etcetera, do hereby decree the following…"}, {"a": 5186, "n": "Battle Trance", "c": "Leader", "r": "Legendary", "f": "Skellige", "t": "Ability", "fl": "No one can replace Bran. Though they're sure to try."}, {"a": 5184, "n": "Onslaught", "c": "Leader", "r": "Legendary", "f": "Skellige", "t": "Ability", "fl": "Nilfgaardians call 'im Tirth ys Muire, the Wild Boar o' the Sea. Use 'im to scare their kiddies!"}, {"a": 5185, "n": "Reckless Flurry", "c": "Leader", "r": "Legendary", "f": "Skellige", "t": "Ability", "fl": "No one knows how he got his nickname – no one's dared to ask."}, {"a": 5166, "n": "Imprisonment", "c": "Leader", "r": "Legendary", "f": "Nilfgaard", "t": "Ability", "fl": "They do not call me the Patient. Take care they do not call you the Headless."}, {"a": 5167, "n": "Imperial Formation", "c": "Leader", "r": "Legendary", "f": "Nilfgaard", "t": "Ability", "fl": "The summer sun reflected in the quiet waters of the Alba – that's Nilfgaard to me."}, {"a": 5168, "n": "Tactical Decision", "c": "Leader", "r": "Legendary", "f": "Nilfgaard", "t": "Ability", "fl": "A sword is but one of many tools at a ruler's disposal."}, {"a": 5180, "n": "Nature's Gift", "c": "Leader", "r": "Legendary", "f": "Scoiatael", "t": "Ability", "fl": "To live in peace, we first must kill. This is human oppression's cruel finale."}, {"a": 5181, "n": "Precision Strike", "c": "Leader", "r": "Legendary", "f": "Scoiatael", "t": "Ability", "fl": "The dryad queen has eyes of molten silver, and a heart of cold–forged steel."}, {"a": 5178, "n": "Guerilla Tactics", "c": "Leader", "r": "Legendary", "f": "Scoiatael", "t": "Ability", "fl": "That doddery dolt? Ye cannae even tell if he's alive or stuffed!"}, {"a": 5172, "n": "Inspired Zeal", "c": "Leader", "r": "Legendary", "f": "Northern Realms", "t": "Ability", "fl": "Don't need advisors and their schemes. I place my trust in my soldiers' blades."}, {"a": 5174, "n": "Mobilization", "c": "Leader", "r": "Legendary", "f": "Northern Realms", "t": "Ability", "fl": "King Henselt did not look like a thief, but, with all due respect, that's really what he was."}, {"a": 1459, "n": "Tridam Infantry", "c": "Human, Soldier", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "Soldiers loyal to the old baron of Tridam left the city with Falibor, thus becoming renegades wanted by the law."}, {"a": 1460, "n": "Cerys an Craite", "c": "Human, Warrior", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "They call me Sparrowhawk. Know why? Because I eat rats like you for breakfast."}, {"a": 1461, "n": "Saskia", "c": "Dragon, Soldier", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "I care not for kings and their titles. In the east lives one who truly deserves a crown."}, {"a": 1462, "n": "Skjall", "c": "Human, Warrior", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "Strike his name from the Saga of Elders! No one dare grant him shelter or sustenance!"}, {"a": 1463, "n": "Jotunn", "c": "Ogroid", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "Skellige legend claims the mighty and terrible Jotunn, King of Giants, reigned over the isles in ancient times. He was slain by Hemdall, but with his dying breath he vowed to return for Ragh nar Roog."}, {"a": 1464, "n": "Whispess: Tribute", "c": "Relict", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "I'd be your best – and last."}, {"a": 1465, "n": "Brewess: Ritual", "c": "Relict", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "We'll cut you up, boy. A fine broth you'll make."}, {"a": 1466, "n": "Weavess: Incantation", "c": "Relict", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "I sense your pain. I see your fear."}, {"a": 1467, "n": "Mandrake", "c": "Organic", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "There you all stand! With wonderment awake, doubting the plan and high-discovery. Some, as if grappled by the fell mandrake, some, by the black dog's devilry."}, {"a": 1468, "n": "Crow's Eye", "c": "Alchemy", "r": "Rare", "f": "Neutral", "t": "Special", "fl": "A certain famous pirate once so loved this intoxicating herb, he earned the nickname 'Crow's Eye.' The theatrical version of his legend omits this, however, to the great consternation of pirate lore sticklers."}, {"a": 1469, "n": "Vigo's Muzzle", "c": "Spell", "r": "Legendary", "f": "Neutral", "t": "Special", "fl": "Never has there been a beast Fringilla Vigo could not tame."}, {"a": 1470, "n": "Wolfsbane", "c": "Organic, Alchemy", "r": "Legendary", "f": "Neutral", "t": "Special", "fl": "Also known as 'the queen of poisons,' wolfsbane is used in many witcher Potions and alchemic brews."}, {"a": 1555, "n": "Pitfall Trap", "c": "Trap", "r": "Epic", "f": "Scoiatael", "t": "Artifact", "fl": "Simple, cheap and deadly efficient - no wonder it's one of the Scoia'tael's favorite traps."}, {"a": 1473, "n": "Cockatrice", "c": "Beast", "r": "Common", "f": "Monster", "t": "Unit", "fl": "Always strikes between the vertebrae, under your left kidney or straight into your aorta. That way, it only needs to strike once."}, {"a": 1101, "n": "Poor Fucking Infantry", "c": "Human, Soldier", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "I's a war veteran! Spare me a crown?"}, {"a": 1474, "n": "Lambert: Swordmaster", "c": "Witcher", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Go teach your grandma to suck eggs."}, {"a": 1475, "n": "Eskel: Pathfinder", "c": "Witcher", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Heard you panting from three miles away. Just didn't wanna give up that vantage point."}, {"a": 1476, "n": "Vesemir: Mentor", "c": "Witcher", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Killing monsters is not something to be taken lightly. Ciri must understand that if she's to become one of us."}, {"a": 1487, "n": "Dwarven Agitator", "c": "Dwarf, Bandit", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "Mark me words, if ye dinnae get up off yer arses, humans're gonnae come here an' steal our wenches!"}, {"a": 1488, "n": "Standard Bearer", "c": "Human, Soldier", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "You shall defend this standard if it costs you your lives! Gloir aen Ard Feainn!"}, {"a": 1489, "n": "Rotfiend", "c": "Necrophage", "r": "Common", "f": "Monster", "t": "Unit", "fl": "You'll smell them long before you see them."}, {"a": 1490, "n": "Alba Armored Cavalry", "c": "Human, Soldier", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "The wedge of riders thundered into the phalanx with crushing momentum. Like a dagger thrust into an exposed belly, the Alba Division swept unhindered through everything between it and the vital organs of the Temerian Infantry."}, {"a": 1492, "n": "Temerian Drummer", "c": "Human, Soldier", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "Not the career he had in mind when he told mummy he wanted to be a musician."}, {"a": 1493, "n": "Whale Harpooner", "c": "Machine, Ship", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "Skelligers have long known that harpoons are effective against more than mere whales..."}, {"a": 1494, "n": "The Naglfar", "c": "Wild Hunt", "r": "Legendary", "f": "Monster", "t": "Special", "fl": "Waves pummel the shore, waves pushed by the prow of the spectral Naglfar. Hemdall's horn rings in the air, and Hemdall stands facing his enemies atop Bifrost, the burning rainbow. The White Frost is nigh, nigh is the time of gale and storm…"}, {"a": 1512, "n": "Ice Troll", "c": "Ogroid", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "Trolls come in many varieties, with differing shapes, sizes and predilections, though always with about as much brains as a bucket of rusty nails."}, {"a": 1514, "n": "Venendal Elite", "c": "Human, Soldier", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "Ebbing is famed for its top-notch mercenaries and light cavalry."}, {"a": 1499, "n": "Mahakam Ale", "c": "Alchemy", "r": "Common", "f": "Neutral", "t": "Special", "fl": "Considered to be the dwarves' greatest contribution to world culture."}, {"a": 1515, "n": "Éibhear Hattori", "c": "Elf", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "Only thing that can rival his swords? His dumplings."}, {"a": 1522, "n": "Germain Piquant", "c": "Human", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "The hero Toussaint needs, but not the one it deserves."}, {"a": 1453, "n": "Heymaey Spearmaiden", "c": "Human, Warrior", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "Skellige women are wild and unpredictable. All units are to treat them as serious threats and never underestimate their capabilities. - General Directive to the Invading Forces of the Imperial Armada"}, {"a": 1507, "n": "Ronvid the Incessant", "c": "Human, Soldier", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "This self-dubbed knight roams the world defending the honor of his beloved Maid Bilberry - though none are certain where she lives, if she lives still or if she ever lived at all."}, {"a": 1472, "n": "Tainted Ale", "c": "Alchemy", "r": "Epic", "f": "Neutral", "t": "Artifact", "fl": "That beer supposed to be green…?"}, {"a": 1478, "n": "Ale of the Ancestors", "c": "Alchemy", "r": "Legendary", "f": "Neutral", "t": "Artifact", "fl": "Boros, the legendary founder of Clan Fuchs, died after overindulging in this beverage - he passed out while reaching for his golden ring, which had fallen into a brook."}, {"a": 1511, "n": "She-Troll of Vergen", "c": "Ogroid", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "Lover of elf and onion soup."}, {"a": 1593, "n": "Elven Swordmaster", "c": "Elf, Warrior", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "Combat is a dance, and you must never allow your opponent to lead."}, {"a": 1534, "n": "Slyzard", "c": "Beast", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "No man alive, no matter his brawn, no matter his skill, can parry a blow dealt by the tail of a slyzard, the pincers of a giant scorpion or the claws of a griffin."}, {"a": 1629, "n": "Aedirnian Mauler", "c": "Human, Soldier", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "Ugh, these guys can be a real headache."}, {"a": 1577, "n": "Geralt: Yrden", "c": "Witcher", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "He lay down next to Adda's mummified remains, drawing the Yrden Sign on the inner side of her sarcophagus' lid."}, {"a": 1592, "n": "Mahakam Volunteers", "c": "Dwarf, Soldier", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "Hoooahhh! Hoooaahhh! Hooo! Prepare yer hineys, clowns! Soon we'll be comin' 'round! Tae kick 'em till ye've feet for frowns!"}, {"a": 1594, "n": "An Craite Marauder", "c": "Human, Warrior", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "You daft? You mean to sail to Skellige? Those barbarians'll tear you to shreds!"}, {"a": 1595, "n": "Phoenix", "c": "Beast", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "What came first, the phoenix or the egg?"}, {"a": 5169, "n": "Toussaintois Hospitality", "c": "Leader", "r": "Legendary", "f": "Nilfgaard", "t": "Ability", "fl": "Why should something as trivial as birth decide who rules over us?"}, {"a": 1597, "n": "Stribog Runestone", "c": "Alchemy", "r": "Epic", "f": "Skellige", "t": "Special", "fl": "Ofieri runemasters can combine these into runewords of incredible power."}, {"a": 1598, "n": "Zoria Runestone", "c": "Alchemy", "r": "Epic", "f": "Northern Realms", "t": "Special", "fl": "I'm getting a palpable chill from this runestone… did I do something to hurt its feelings?"}, {"a": 1599, "n": "Dazhbog Runestone", "c": "Alchemy", "r": "Epic", "f": "Nilfgaard", "t": "Special", "fl": "Careful. Still hot."}, {"a": 1600, "n": "Devana Runestone", "c": "Alchemy", "r": "Epic", "f": "Monster", "t": "Special", "fl": "My blades're so sharp, they can cut paper!"}, {"a": 1601, "n": "Morana Runestone", "c": "Alchemy", "r": "Epic", "f": "Scoiatael", "t": "Special", "fl": "I grow faint at the very sight of it…"}, {"a": 1602, "n": "Whispering Hillock", "c": "Organic", "r": "Legendary", "f": "Monster", "t": "Special", "fl": "It will rise again. Elsewhere, beyond our reach. Blood will flow once more."}, {"a": 5179, "n": "Invigorate", "c": "Leader", "r": "Legendary", "f": "Scoiatael", "t": "Ability", "fl": "Though we are now few and scattered, our hearts burn brighter than ever."}, {"a": 5175, "n": "Shieldwall", "c": "Leader", "r": "Legendary", "f": "Northern Realms", "t": "Ability", "fl": "Her curse was lifted… but her appetite for raw meat remained."}, {"a": 5187, "n": "Rage of the Sea", "c": "Leader", "r": "Legendary", "f": "Skellige", "t": "Ability", "fl": "Eist came to Cintra to help Crach an Craite win the hand of Princess Pavetta, yet wound up winning her mother's heart for himself."}, {"a": 1603, "n": "Bone Talisman", "c": "Organic", "r": "Common", "f": "Neutral", "t": "Special", "fl": "The simplest of objects sometimes possess the greatest power."}, {"a": 1418, "n": "Werecat", "c": "Beast", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "He hates it when you scratch his belly."}, {"a": 1402, "n": "Werewolf", "c": "Beast, Cursed", "r": "Common", "f": "Monster", "t": "Unit", "fl": "Some say lycanthropy's contagious - get bit by a werewolf, you turn into one yourself. Witchers know that's nonsense, of course - only a powerful curse can bring on this condition."}, {"a": 1604, "n": "Yennefer's Invocation", "c": "Spell", "r": "Legendary", "f": "Nilfgaard", "t": "Special", "fl": "It's best not to get in Yennefer's way. Especially when she's in a hurry."}, {"a": 1605, "n": "Letho: Kingslayer", "c": "Witcher", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "Why does this monk wear studded gloves…?"}, {"a": 1537, "n": "Forktail", "c": "Beast", "r": "Common", "f": "Monster", "t": "Unit", "fl": "As for forktails, bait them thusly: pound a stake in the soil, bind a goat to it, then hide ye in nearto shrubbery posthaste."}, {"a": 1529, "n": "Slave Hunter", "c": "Human, Soldier", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "The trick is to break their wills - but not their bodies."}, {"a": 1530, "n": "Slave Infantry", "c": "Human, Soldier", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "A free man's got a choice. A slave's choices are made for him."}, {"a": 1606, "n": "Iorveth's Gambit", "c": "Tactic", "r": "Legendary", "f": "Scoiatael", "t": "Special", "fl": "Iorveth may have only one eye, but his inner vision is unmatched."}, {"a": 1533, "n": "Slave Driver", "c": "Human", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "What drives a slave driver? A solitary purpose: to see his orders carried out to the letter."}, {"a": 1360, "n": "Saesenthessis: Blaze", "c": "Dragon", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "I inherited my father's ability to assume other forms - well, one other form, in my case."}, {"a": 1607, "n": "Isengrim's Council", "c": "Nature", "r": "Legendary", "f": "Scoiatael", "t": "Special", "fl": "Before us lies Elskerdeg Pass, and beyond that, Zerrikania and Hakland. Before us lies a long and dangerous road. If we are to walk it together… let us put aside our mistrust."}, {"a": 1425, "n": "Master of Disguise", "c": "Human, Agent", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "O Great Sun which dost in Heavens fly, save us from the lice which do so stubbornly infest our bloomers."}, {"a": 1608, "n": "Recruit", "c": "Human, Soldier", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "His is not to reason why, his is but… to peel one damned spud after another."}, {"a": 1609, "n": "Seltkirk of Gulet", "c": "Human, Cursed, Knight", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "Though famed for his many virtues, his indomitable courage first and foremost, Seltkirk was not spared the fate which met all those killed in the Battle of Upper Aedirn."}, {"a": 1585, "n": "Ointment", "c": "Tactic", "r": "Common", "f": "Nilfgaard", "t": "Special", "fl": "Will it help? Who knows. Shouldn't do any harm, though. Probably."}, {"a": 1610, "n": "Vandergrift", "c": "Human, Cursed, Knight", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "The general thought the war for the Lormark would end quickly, with minimal losses… yet wound up fighting it for all eternity."}, {"a": 1611, "n": "Mad Kiyan", "c": "Witcher, Cursed", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "We live on a placid island of ignorance in the midst of black seas of infinity, and it was not meant that we should voyage far."}, {"a": 1339, "n": "Kaedweni Knight", "c": "Human, Soldier, Knight", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "Not every man in the Kaedweni Army supports his king's politics. Yet not a single one would dare say that out loud."}, {"a": 1612, "n": "Giant Boar", "c": "Beast", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "Most men, seeing a massive boar in the woods, mess their trousers and scurry up the nearest tree. A Skelliger, though - he just drools."}, {"a": 1613, "n": "Kaedweni Revenant", "c": "Specter, Cursed, Soldier", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "Doomed to repeat the same day over and over again, just like the employees of Cianfanelli Bank."}, {"a": 1614, "n": "Cursed Knight", "c": "Specter, Cursed, Knight", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "He fights an endless war whose beginning he no longer remembers."}, {"a": 1615, "n": "Ciri: Nova", "c": "Witcher", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Zireael possesses a great power she cannot control. She is a danger - to herself, to others. Until she learns to control it, she should remain isolated."}, {"a": 1484, "n": "Shupe's Day Off", "c": "", "r": "Legendary", "f": "Neutral", "t": "Special", "fl": "Shupe is known to have quite the imagination. What other troll would look at scraps of paper and see rocks?"}, {"a": 1616, "n": "Forbidden Magic", "c": "Spell", "r": "Rare", "f": "Northern Realms", "t": "Special", "fl": "Prohibited? Yes. Eliminated? Far from it."}, {"a": 1617, "n": "Damned Sorceress", "c": "Specter, Mage, Cursed", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "Sabrina's curse spared no one, not even her fellow practitioners."}, {"a": 1618, "n": "Doppler", "c": "Relict", "r": "Common", "f": "Neutral", "t": "Unit", "fl": "Humans despise dopplers so much, they feel mere execution does not suffice - so they tie any they catch to a stake, cover them in thick clay and bake them in a fire."}, {"a": 1619, "n": "Sihil", "c": "", "r": "Legendary", "f": "Neutral", "t": "Special", "fl": "What's written on this blade? That a curse? No. An insult."}, {"a": 1563, "n": "Bloody Flail", "c": "Warfare", "r": "Epic", "f": "Northern Realms", "t": "Special", "fl": "There are weapons banned in all the Northern Realms, for the wounds they deal are horrible beyond all imagining."}, {"a": 1621, "n": "Bekker's Rockslide", "c": "Spell", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "All it takes is one pebble and we're all done for."}, {"a": 1579, "n": "Glorious Hunt", "c": "Tactic", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "By the gods' gonads, witcher, why'd you bring me this filth?! I want that beast's head! - that was a ploughin' figure of ploughin' speech!"}, {"a": 1622, "n": "Half-Elf Hunter", "c": "Elf, Bandit", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "Hated by men, reviled by elves and always picked last during schoolyard games. No wonder half-elves tend to have a chip on their shoulder."}, {"a": 1589, "n": "Dragon's Dream", "c": "Bomb", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "In Zerrikania, dragon worship dominates every aspect of daily life. Thus it comes as no surprise they name weapons in their honor."}, {"a": 1538, "n": "Elven Scout", "c": "Elf, Agent", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "They say elves leave no tracks in the snow, but if you ask me, they are just a pack of village idiots, babbling nonsense."}, {"a": 1517, "n": "Garrison", "c": "Location", "r": "Epic", "f": "Neutral", "t": "Artifact", "fl": "Knock, knock… anybody home?"}, {"a": 1624, "n": "Yoana", "c": "Human", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "No one'd ever think I could be a skilled armorer - a human, and a woman to boot. A dwarven blacksmith - that's another story…"}, {"a": 1539, "n": "Crushing Trap", "c": "Trap", "r": "Rare", "f": "Scoiatael", "t": "Artifact", "fl": "When this knocks you down, you don't get up again."}, {"a": 1004, "n": "Derran", "c": "Human", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "Whatever caused this madness must have been terrifying…"}, {"a": 1625, "n": "Rock Barrage", "c": "", "r": "Common", "f": "Neutral", "t": "Special", "fl": "Someday, when you are older, you could get hit by a boulder."}, {"a": 1620, "n": "Vandergrift's Blade", "c": "Warfare, Cursed", "r": "Epic", "f": "Northern Realms", "t": "Artifact", "fl": "Seltkirk shattered Vandergrift's sword during a knights' tourney in Ard Carraigh. Afterwards Vandergrift, enraged at his weapon's failure, ordered a new one forged, this time with powerful runestones enchanted into it."}, {"a": 1626, "n": "Sabrina's Inferno", "c": "Spell", "r": "Epic", "f": "Northern Realms", "t": "Special", "fl": "With her dying breath, Sabrina Glevissig cast a powerful curse that struck not only her executioners, but all who stood nearby."}, {"a": 1584, "n": "Mahakam Horn", "c": "Trap", "r": "Epic", "f": "Scoiatael", "t": "Artifact", "fl": "Once upon a time, Mahakam held a horn-blowing contest. That day the dwarves made an important discovery: loud noises and snow-capped peaks do not play well together."}, {"a": 1562, "n": "Mastercrafted Spear", "c": "", "r": "Rare", "f": "Neutral", "t": "Special", "fl": "Hold that spear up, weakling! Not a single horse shall pass!"}, {"a": 1581, "n": "Parasite", "c": "Organic", "r": "Epic", "f": "Monster", "t": "Special", "fl": "A real eye-catcher."}, {"a": 1627, "n": "Winch", "c": "Warfare", "r": "Rare", "f": "Northern Realms", "t": "Special", "fl": "It's a winch. Not much to flap your jaw about."}, {"a": 1001, "n": "Ruehin", "c": "Insectoid", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "No one has ever entered that forest and lived to tell the tale…"}, {"a": 1628, "n": "Watchman", "c": "Human, Soldier", "r": "Rare", "f": "Neutral", "t": "Unit", "fl": "I can't even see over this bloody thing."}, {"a": 1586, "n": "Cadaverine", "c": "Tactic", "r": "Epic", "f": "Nilfgaard", "t": "Special", "fl": "I don't trust my life to chance. I trust it to a thick coating of Cadaverine on my blade."}, {"a": 1531, "n": "Vrygheff", "c": "Human, Soldier", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "An eye for an eye only ends when the whole world's blind."}, {"a": 1630, "n": "Pavko Gale", "c": "Human, Bandit", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "No one smuggled as much food to the elves of the Blue Mountains as Gale. He'd bring them sacks of turnips and, prized most of all, leeks."}, {"a": 1632, "n": "Paulie Dahlberg", "c": "Dwarf", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "Move yer arses! It's a ploughin' trap!"}, {"a": 1633, "n": "Black Blood", "c": "Alchemy", "r": "Epic", "f": "Neutral", "t": "Artifact", "fl": "Vampires all agree: use of this potion is bad sportsmanship."}, {"a": 1634, "n": "Ozzrel", "c": "Necrophage", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "Some necrophages have taken such a liking to human flesh, they no longer are content to merely dig up corpses..."}, {"a": 1510, "n": "Bridge Troll", "c": "Ogroid", "r": "Common", "f": "Monster", "t": "Unit", "fl": "This here bridge? Trolls built it a long time ago. Sat under it, made folk pay 'em a hefty copper to pass. Thing is, not many folk pass this way. So they all packed up, went their way. Not the bridge, though. It stayed."}, {"a": 1635, "n": "Barbegazi", "c": "Insectoid", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "What moments before looked like round rocks among the stalagmites now stared at him with enormous, bright, menacing eyes."}, {"a": 1067, "n": "Scout", "c": "Human, Soldier", "r": "Common", "f": "Neutral", "t": "Unit", "fl": "If our scouts don't come back, we turn around. The yokels claim these woods are full o' squirrels - and I don't mean the nut-gatherin' kind."}, {"a": 5163, "n": "Arachas Swarm", "c": "Leader", "r": "Legendary", "f": "Monster", "t": "Ability", "fl": "Her children inherited her beauty."}, {"a": 1069, "n": "Spores", "c": "Organic", "r": "Common", "f": "Neutral", "t": "Special", "fl": "Carried by the wind across the Continent... Sowing madness and blight where they fall."}, {"a": 1558, "n": "Foltest's Pride", "c": "Machine, Siege Engine", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "As King Foltest likes to say, it's not size that counts, but whether it gets the job done."}, {"a": 1640, "n": "Golden Froth", "c": "Alchemy", "r": "Rare", "f": "Neutral", "t": "Special", "fl": "Smell that? That's the smell of happiness."}, {"a": 1631, "n": "Peasant Militia", "c": "Human", "r": "Common", "f": "Neutral", "t": "Unit", "fl": "We's the militia. We keep the peace."}, {"a": 1641, "n": "Geralt: Professional", "c": "Witcher", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "I accepted a job once, did it. Asked to choose my reward, I invoked the Law of Surprise."}, {"a": 1644, "n": "Triss: Telekinesis", "c": "Human, Mage", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Bindings won't suffice. Nor will a gag render her any less dangerous. No, dimeritium is the only solution."}, {"a": 1645, "n": "Dandelion: Vainglory", "c": "Human", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Dandelion told me all about your adventures. How he'd ready you for battle with his songs, how he tamed the kayran by playin' his lute..."}, {"a": 1647, "n": "Dandelion: Poet", "c": "Human", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "The quill is mightier than the sword."}, {"a": 1648, "n": "Roche: Merciless", "c": "Human, Soldier", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "Fear does not befit us. Yet, there is a certain d'hoine... Vernon Roche. Be wary of him."}, {"a": 1650, "n": "Call of the Forest", "c": "Nature", "r": "Legendary", "f": "Scoiatael", "t": "Special", "fl": "I hold Brokilon dearer than my own life. She is a mother who cares for her children. I will defend her to my final breath."}, {"a": 1651, "n": "Yennefer: Divination", "c": "Human, Mage", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Yes, I have seen the future. And you're not in it."}, {"a": 1652, "n": "Imlerith", "c": "Elf, Wild Hunt, Warrior", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "The sisters said you would come. They saw you arrive in the water's surface."}, {"a": 1354, "n": "Ihuarraquax", "c": "Relict", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Inconceivable. Impossible, Ciri thought, returning to her senses. Unicorns don't exist, not any more, not in this world. Unicorns are extinct."}, {"a": 1688, "n": "Gimpy Gerwin", "c": "Human, Bandit", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Keep the vermin on a short leash. And don't be afraid to use that whip!"}, {"a": 1575, "n": "Elf and Onion Soup", "c": "Alchemy", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "Garnish each serving with grated cheese. Add eyeballs to taste. Serve hot."}, {"a": 1578, "n": "Ivo of Belhaven", "c": "Witcher", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "It's not reason I'm devoid of, just emotion."}, {"a": 1483, "n": "Eyck of Denesle", "c": "Human, Knight", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "The Good Book says the world is a garden which the gods once conferred upon man. And we men have this garden neglected!"}, {"a": 1520, "n": "Gascon", "c": "Human, Bandit", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Th' Strays of Spalla – 'tis you who lead them? 'Tis you they call the Duke of Dogs?"}, {"a": 1503, "n": "Prince Villem", "c": "Human", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "The boy's not fit to wear the crown. Hasn't sufficient wit nor valor. I know this, you know this… just, he knows it not."}, {"a": 1480, "n": "Count Caldwell", "c": "Human", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Your Majesty… For the queen to question commoners, why, it's simply not proper…"}, {"a": 1502, "n": "Xavier Lemmens", "c": "Human, Agent", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Your engineer's got a pate like stewed meat, but he kens his trade, that's for certain."}, {"a": 1536, "n": "Keltullis", "c": "Dragon", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "When she took roost here, they fought 'er for near a century. Then the dragon got weary o' fightin' and they realized she weren't goin' nowheres, so… they cut a deal. She dinnae bother 'em, they give 'er what she needs."}, {"a": 1501, "n": "Glustyworp", "c": "Insectoid", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "The swamp underfoot suddenly exploded with a powerful splash. Two long, mantis-like forelimbs bristling with spikes shot out from the murk. The monstrous, green hooks seized an unlucky footman, dragging him beneath the water's surface."}, {"a": 1477, "n": "Gabor Zigrin", "c": "Dwarf, Soldier", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "Brouver Hoog wanted to kick him out of Mahakam once for having a llama in his living room… it's a long story."}, {"a": 1576, "n": "Barnabas Beckenbauer", "c": "Gnome", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "Arrived here with his peddler's wagon full o' tricks an' gadgets. Went from house tae house, praised his rubbish tae the high heavens. An' what's it he sold us? Bombs that go off in yer hand! Beard-growth formula that makes yer hair catch fire!"}, {"a": 1572, "n": "Isbel of Hagge", "c": "Human, Mage", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "I promised I would never again use magic to harm others."}, {"a": 1525, "n": "Lippy Gudmund", "c": "Human, Pirate", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "The coast's picked clean since long! So we set our longships up the Yaruga – for gold and glory!"}, {"a": 1504, "n": "Dagur Two Blades", "c": "Human, Warrior", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "Shields are for flower-pickin' saps."}, {"a": 1524, "n": "Traheaern var Vdyffir", "c": "Human, Agent", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "The Nilfgaardians proceeded in the queen's very direction without a sign of panic. The man leading the Nilfgaardians was clad in rich robes. He exuded pride... and the scent of musk."}, {"a": 1479, "n": "Reynard Odo", "c": "Human, Soldier, Knight", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "Under your husband I served ten years, under you another eight. And never in that time did I fight for a more worthy cause."}, {"a": 1573, "n": "Black Rayla", "c": "Human, Soldier", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "Exceptions are a clear road to human blood spilt. All Scoia'tael must die. Leave the gods to sort the wheat from the chaff."}, {"a": 5182, "n": "Deadeye Ambush", "c": "Leader", "r": "Legendary", "f": "Scoiatael", "t": "Ability", "fl": "The king once dispatched an envoy to Eldain… despite my advice to the contrary. Found the envoy the next day, eyes gouged out, shaft of his white flag jammed down his throat."}, {"a": 5173, "n": "Royal Inspiration", "c": "Leader", "r": "Legendary", "f": "Northern Realms", "t": "Ability", "fl": "We're at war, when rulers don't strive nor choose. When rulers grasp sword and shield and ride out to defend their subjects."}, {"a": 5164, "n": "Fruits of Ysgith", "c": "Leader", "r": "Legendary", "f": "Monster", "t": "Ability", "fl": "Frescoes on the tomb walls depicted Angren's swamps and the beasts that prowled them. Two words were inscribed over the largest of the horrors: Gvaern Ichaer – the Bloody Mistress."}, {"a": 5170, "n": "Enslave", "c": "Leader", "r": "Legendary", "f": "Nilfgaard", "t": "Ability", "fl": "In my home, in the civilized world, a general commands his force. He does not rush and thrash about like some rabid hound."}, {"a": 5188, "n": "Patricidal Fury", "c": "Leader", "r": "Legendary", "f": "Skellige", "t": "Ability", "fl": "We're after killin'. Nilfgaardians, Lyrians... 's all the same to us. Strife an' blood an' guts to wash away our shame."}, {"a": 1519, "n": "Strays of Spalla", "c": "Human, Bandit", "r": "Rare", "f": "Neutral", "t": "Unit", "fl": "Awoo, awoo, awooooo!"}, {"a": 1540, "n": "Bomb Heaver", "c": "Human, Bandit", "r": "Rare", "f": "Neutral", "t": "Unit", "fl": "Knew a young couple once—got separated right after the weddin'. Bomb in the carriage'll do that."}, {"a": 5176, "n": "Stockpile", "c": "Leader", "r": "Legendary", "f": "Northern Realms", "t": "Ability", "fl": "My king enjoys life... enjoys pleasures and indulges often. But none of this has hindered his ability to govern the realm bloody well."}, {"a": 1708, "n": "Angoulême", "c": "Human, Bandit", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Don't matter if it crawls, slithers, climbs—you name it, I've eaten it. As for things that fly... I once ate a kite just 'cause it had flour stuck to it."}, {"a": 1719, "n": "Vysogota of Corvo", "c": "Human", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "It's been near half a century since I last practiced medicine. The years haven't been kind to my memory... Nor the dexterity of my fingers."}, {"a": 1000, "n": "Falibor", "c": "Human, Soldier", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "From afar, he looks like a bear. From up close, well... A larger bear."}, {"a": 1689, "n": "Anna Strenger", "c": "Human, Cursed", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "Anna hated her husband so much that she was ready to do anything in order to be free of the man — and the child he had put inside her."}, {"a": 1559, "n": "Lyrian Cavalry", "c": "Human, Soldier", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "A horseman's worth no less than his steed. And Lyrian horses are among the Continent's best."}, {"a": 1523, "n": "Rivian Pikeman", "c": "Human, Soldier", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "Get off your high horse and face me!"}, {"a": 1541, "n": "Lyrian Arbalest", "c": "Human, Soldier", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "I can find the bull's-eye from a hundred paces! Perhaps not with my first shot, mind you..."}, {"a": 1521, "n": "Lyrian Landsknecht", "c": "Human, Soldier", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "Best not laugh at their silly-arse hats. Believe me."}, {"a": 1481, "n": "Lyrian Scytheman", "c": "Human, Soldier", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "Our folk they feed, and our foes they bleed."}, {"a": 5165, "n": "Blood Scent", "c": "Leader", "r": "Legendary", "f": "Monster", "t": "Ability", "fl": "He did not love like a man, but like an animal. Madly, deeply, unconditionally. Wildly."}, {"a": 5171, "n": "Double Cross", "c": "Leader", "r": "Legendary", "f": "Nilfgaard", "t": "Ability", "fl": "As head of state, I must judge her fairly. But she is my sister, thus my heart bleeds for her…"}, {"a": 5177, "n": "Pincer Maneuver", "c": "Leader", "r": "Legendary", "f": "Northern Realms", "t": "Ability", "fl": "They call her the Lioness of Cintra. And not without good reason."}, {"a": 5183, "n": "Call of Harmony", "c": "Leader", "r": "Legendary", "f": "Scoiatael", "t": "Ability", "fl": "She revealeth herself as the Fairhaired Ladie, in flowers all, and all that liveth followeth her path and clingeth to her, as one, plant or beast."}, {"a": 5189, "n": "Ursine Ritual", "c": "Leader", "r": "Legendary", "f": "Skellige", "t": "Ability", "fl": "He proclaimed to his worshippers but one commandment: Kill."}, {"a": 1835, "n": "Crimson Curse", "c": "Organic", "r": "Legendary", "f": "Monster", "t": "Special", "fl": "When the moon burns red, latch the door and put your lambs to bed..."}, {"a": 1698, "n": "Tesham Mutna Sword", "c": "", "r": "Legendary", "f": "Neutral", "t": "Special", "fl": "Millenia have passed, but its thirst for blood has not."}, {"a": 1702, "n": "Hen Gaidth Sword", "c": "", "r": "Legendary", "f": "Neutral", "t": "Special", "fl": "Legend tells that wounds carved from this blade never heal. Blood shall flow until not a drop remains..."}, {"a": 1701, "n": "Land of a Thousand Fables", "c": "Location", "r": "Legendary", "f": "Neutral", "t": "Artifact", "fl": "The girls told me if I ever wished to visit alone, I need but crack open The Land of a Thousand Fables and utter out loud the incantation Expecto ludum!"}, {"a": 1368, "n": "Syanna", "c": "Human, Cursed", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Your Majesty... The princess has been touched by the curse o' the Black Sun. There's no hope, I'm afraid..."}, {"a": 1695, "n": "Regis: Bloodlust", "c": "Vampire", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "I've been called a monster, a bloodthirsty freak. Among other, shall we say, more colorful names."}, {"a": 1697, "n": "Lady of the Lake", "c": "Relict", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Take this sword as a sign of my favor. For centuries it lay in these depths, waiting... for you."}, {"a": 1680, "n": "Fisher King", "c": "Human", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Mhmm."}, {"a": 1397, "n": "Vivienne: Oriole", "c": "Human, Cursed", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Who'd not like to live free as a bird? Well, just ask Vivienne de Tabris."}, {"a": 1675, "n": "Gregoire de Gorgon", "c": "Human, Knight", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Gregoire? That mountain o' muscle wrapped in armor? Course, I 'eard of 'im! Who hasn't?"}, {"a": 1700, "n": "Musicians of Blaviken", "c": "Beast", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Cock-a-doodle-doo! Meeeooow! Woof woof! Hee-haw!"}, {"a": 1687, "n": "Portal", "c": "", "r": "Epic", "f": "Neutral", "t": "Artifact", "fl": "Some value them highly. Others hate them."}, {"a": 1657, "n": "Sangreal", "c": "Alchemy", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "It is the duchess's exclusive privilege to delight in the prized, oaky flavor of Sangreal... A pleasure she partakes in very, very often."}, {"a": 1655, "n": "Tempest", "c": "Nature", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "A Category 10 on the Bekker scale."}, {"a": 1696, "n": "Curse of Corruption", "c": "Spell", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "Black magic – the grislier the better."}, {"a": 1686, "n": "Sandstorm", "c": "", "r": "Common", "f": "Neutral", "t": "Special", "fl": "Best case – sand in your teeth. Worst case – buried alive."}, {"a": 1694, "n": "Dancing Star", "c": "Bomb", "r": "Common", "f": "Neutral", "t": "Special", "fl": "A spectacular sight – until it explodes in your face."}, {"a": 1693, "n": "Devil's Puffball", "c": "Bomb", "r": "Common", "f": "Neutral", "t": "Special", "fl": "As lethal as it is foul."}, {"a": 1643, "n": "Northern Wind", "c": "Bomb", "r": "Common", "f": "Neutral", "t": "Special", "fl": "That ought to cool your temper."}, {"a": 1692, "n": "Moon Dust", "c": "Bomb", "r": "Common", "f": "Neutral", "t": "Special", "fl": "The werewolf lifted and tilted his head, mystified by the silvery dust... Then howled in utter agony."}, {"a": 1691, "n": "Samum", "c": "Bomb", "r": "Common", "f": "Neutral", "t": "Special", "fl": "Zerrikanian alchemists have learned to harness the energy of hot desert storms and bind it into an arcane mixture."}, {"a": 1690, "n": "Red Haze", "c": "Bomb", "r": "Common", "f": "Neutral", "t": "Special", "fl": "Perhaps the most insidious invention of Zerrikanian alchemists. And there's no shortage to choose from."}, {"a": 1491, "n": "Inspirational Ballad", "c": "", "r": "Common", "f": "Neutral", "t": "Special", "fl": "War's not so horrific when you put a catchy tune to it."}, {"a": 1678, "n": "Thaw", "c": "Nature", "r": "Rare", "f": "Neutral", "t": "Special", "fl": "It heralds the coming of spring... Which, in turn, heralds the coming of war."}, {"a": 1770, "n": "Traveling Merchant", "c": "Human", "r": "Rare", "f": "Neutral", "t": "Unit", "fl": "Florens, orens, crowns – I accept them all!"}, {"a": 1771, "n": "Pellar", "c": "Human", "r": "Rare", "f": "Neutral", "t": "Unit", "fl": "Gather spirits for this wake,\\nA passing soul ne'er forsake,\\nHear my call, my humble plea,\\nUnbind his chains, set him free."}, {"a": 1772, "n": "Cutthroat", "c": "Human, Bandit", "r": "Rare", "f": "Neutral", "t": "Unit", "fl": "Ahhh, nothin' so soothin' as the sound o' gurglin' blood."}, {"a": 1773, "n": "Oxenfurt Scholar", "c": "Human", "r": "Rare", "f": "Neutral", "t": "Unit", "fl": "Balderdash! Your blatant obfuscation of teleological and ontological axioms is an embarrassment to the field! Ostentatious verbiage for its own sake!"}, {"a": 1699, "n": "Spring Equinox", "c": "Nature", "r": "Rare", "f": "Neutral", "t": "Special", "fl": "The days grow longer and the dresses of maidens grow shorter."}, {"a": 1583, "n": "Scepter of Storms", "c": "", "r": "Epic", "f": "Neutral", "t": "Artifact", "fl": "Some call it the Stick of Truth."}, {"a": 1683, "n": "Queen of the Night", "c": "Vampire", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "Those seduced by her charms find themselves willing to pay any price."}, {"a": 1393, "n": "Orianna", "c": "Vampire", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "Lady Orianna's been a blessin' for us... She 'elps the beggarly, supports the arts – why, she even runs a home for them poor orphans!"}, {"a": 1677, "n": "Protofleder", "c": "Vampire", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "Limited to only one region of the Continent, scholars consider them critically endangered. Gods be praised..."}, {"a": 1661, "n": "Garkain", "c": "Vampire", "r": "Common", "f": "Monster", "t": "Unit", "fl": "Blood on the ceiling, entrails on the wall... Got garkain written all over it."}, {"a": 1681, "n": "Gael", "c": "Vampire", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "A fondness for shiny trinkets is not a trait unique to magpies."}, {"a": 1656, "n": "Undying Thirst", "c": "Organic", "r": "Common", "f": "Neutral", "t": "Special", "fl": "Some appetites can never be sated."}, {"a": 1412, "n": "Feast of Blood", "c": "Organic", "r": "Common", "f": "Monster", "t": "Special", "fl": "Vampires have been known to fast for years at a time. Yet once the hunt resumes, they feed and feed until frenzied and drunk on blood."}, {"a": 1411, "n": "Fleder", "c": "Vampire", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "The children o' the night come as punishment from the gods! We's tolerated wizard-folk and non-human filth in our midst too long! Repent! 'Fore yer soul rots, repent!"}, {"a": 1385, "n": "Alp", "c": "Vampire", "r": "Common", "f": "Monster", "t": "Unit", "fl": "The townsfolk, long plagued with horrific nightmares, posted a desperate plea for help... Hmm. An alp, gotta be, the witcher grumbled to himself."}, {"a": 1660, "n": "Plumard", "c": "Vampire", "r": "Common", "f": "Monster", "t": "Unit", "fl": "One alone poses no great threat. But a dozen? Gods be with you."}, {"a": 1676, "n": "Nekurat", "c": "Vampire", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "No matter how lightly you tread, how soft your step, he will hear you. He will find you."}, {"a": 1410, "n": "Bruxa", "c": "Vampire", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "The vampiress lunged in a blur, unleashing an inhuman shriek. The wall of sound slammed into the witcher like a battering ram – splintering his ribs, forcing the air from his lungs, and sending tendrils of pain down his spine."}, {"a": 1398, "n": "Vivienne de Tabris", "c": "Human, Cursed, Aristocrat", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "Vivienne's a bit of an odd duck for a lady-in-waitin'. But by the Gods, ye can't deny her beauty an' grace!"}, {"a": 1704, "n": "Damien de la Tour", "c": "Human, Soldier, Knight", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "I served Beauclair well. At least... I hope I did."}, {"a": 1396, "n": "Palmerin de Launfal", "c": "Human, Knight", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "Rumor had it the esteemed baron Palmerin de Launfal had fallen into a profane affair with a succubus. The duchess, however, gave no credence to such baseless hearsay."}, {"a": 1395, "n": "Milton de Peyrac-Peyran", "c": "Human, Knight", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "Glinting under the rays of the Beauclair sun, there was no mistaking this knight-errant who bore the head of a great, white bull on his shield."}, {"a": 1682, "n": "Artorius Vigo", "c": "Human, Mage", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "It is said he created an illusion so realistic that he began to believe it himself..."}, {"a": 1706, "n": "Roderick of Dun Tynne", "c": "Human, Aristocrat", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "Roderick lived as a recluse, avoiding society at large. Instead, he preferred the company of a small party of knights. If they can truly be called such..."}, {"a": 1388, "n": "Tourney Shaelmaar", "c": "Beast", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "Releasing a monster that dangerous in front of a crowd? Plain irresponsible."}, {"a": 1424, "n": "Tourney Joust", "c": "Tactic", "r": "Common", "f": "Nilfgaard", "t": "Special", "fl": "Fame and glory eternal await the victor of this year's annual chivalric tourney!"}, {"a": 1428, "n": "Toussaintois Knight-Errant", "c": "Human, Knight", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "White steed, shiny-arse armor... Aye, 'tis a knight-errant alright. Fetch the coffin maker!"}, {"a": 1422, "n": "Ducal Guard", "c": "Human, Soldier", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "And whatever you do, never, EVER, mention the duchess's sister. Right, so... Welcome to Her Majesty's royal guard!"}, {"a": 1426, "n": "Menagerie Keeper", "c": "Human", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "If there's one thing Nilfgaardians love more than blood-soaked arena battles, it's blood-soaked arena battles with exotic beasts."}, {"a": 1421, "n": "Imperial Diviner", "c": "Human, Mage", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "Emperor Emhyr var Emreis spared no effort to find his daughter, even resorting to arcane magics of the mages and sorceresses he had so vehemently despised."}, {"a": 1427, "n": "Fangs of the Empire", "c": "Human, Agent", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "For a courtesan, a single drop. For a rock troll, an entire bottle. And for Nordling scum? Why waste good poison when a rusty dagger will do?"}, {"a": 1778, "n": "Duchess' Informant", "c": "Human, Agent", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "Anna Henrietta wakes every morn to the tune of her songbirds."}, {"a": 1717, "n": "King Roegner", "c": "Human, Aristocrat", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "King Roegner of Cintra, once grievously wounded at the bottom of a ravine, hollered for aid. Alas... His call was answered only by the hisses of vipers and the howls of ravenous werewolves..."}, {"a": 1707, "n": "Queen Adalia", "c": "Human, Aristocrat", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "Queen Adalia of Cintra possessed the power to raise a drawbridge with a twitch of her brow. A frightening thought what she could do with a wave of her hand..."}, {"a": 1766, "n": "Prince Anséis", "c": "Human, Knight", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "Your presence at this tourney is an affront to my honor!"}, {"a": 1718, "n": "Vissegerd", "c": "Human, Soldier, Knight", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "I will raise Cintra from the ashes no matter how great the cost."}, {"a": 1716, "n": "Coodcoodak", "c": "Human, Knight", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "Coodcoodak, throwing his head back, howled and growled, screeched and squealed, whined and bleated – all in a medley of voices both known and unknown, domestic and wild, of reality and of myth."}, {"a": 1720, "n": "Windhalm of Attre", "c": "Human, Knight", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "Off with his head! But slowly, drag it out, put on a show for all to see. His death must serve as an example."}, {"a": 1654, "n": "Runeword", "c": "Spell", "r": "Rare", "f": "Northern Realms", "t": "Special", "fl": "Probably best not to utter that."}, {"a": 1715, "n": "Cintrian Spellweaver", "c": "Human, Mage", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "Reality is so terribly tedious..."}, {"a": 1711, "n": "Cintrian Enchantress", "c": "Human, Mage", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "The ladies of the Cintrian court are oft touted for their stately elegance – and equally impressive aptitude for magic"}, {"a": 1710, "n": "Cintrian Artificer", "c": "Human", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "What shall I call it? Perhaps Andúril..."}, {"a": 1713, "n": "Cintrian Knight", "c": "Human, Knight", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "For whom does the bell toll?"}, {"a": 1714, "n": "Cintrian Royal Guard", "c": "Human, Soldier", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "Queen Calanthe handpicked her personal guard with meticulous care. Each must serve with unconditional loyalty, stand more than six feet tall, and possess a devilishly handsome jawline."}, {"a": 1712, "n": "Cintrian Envoy", "c": "Human, Agent", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "She thought service in the diplomatic corps would mean a quiet life behind a desk. She and her blistered feet were sorely mistaken..."}, {"a": 1777, "n": "Knighthood", "c": "Warfare", "r": "Epic", "f": "Northern Realms", "t": "Special", "fl": "Kneel an everyman, arise a knight!"}, {"a": 1403, "n": "Fauve", "c": "Dryad", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "At the edge of the wood, a lone dryad awaited them. Dandelion recognized her at once – the very same with green hair who had given them light in dark of night and urged the bard to continue his ballads."}, {"a": 1362, "n": "The Great Oak", "c": "Treant", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "The trees of Brokilon oft rustle amongst themselves, despairing of the ancient oak whose heart now rots with hatred."}, {"a": 1725, "n": "Weeping Willow", "c": "Treant", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "Its name misleads, for 'tis not the tree who weeps."}, {"a": 1371, "n": "Water of Brokilon", "c": "Nature", "r": "Legendary", "f": "Scoiatael", "t": "Special", "fl": "Drink, child. Wash away your past, your worries. Drink and become our sister!"}, {"a": 1404, "n": "Sirssa", "c": "Dryad, Warrior", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "With silent grace, a dark-haired dryad nimbly descended a spiralling cascade of mushrooms along the tree's trunk, her lithe body camouflaged with fallen leaves."}, {"a": 1447, "n": "Treant Boar", "c": "Treant", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "Dryads wield a mystifying power to shape the forest's trees into any form they wish. So why not a giant boar?"}, {"a": 1724, "n": "Dryad's Caress", "c": "Nature", "r": "Common", "f": "Scoiatael", "t": "Special", "fl": "Shh, shh... Evelienn va maeth, elaine blath..."}, {"a": 1722, "n": "Dryad Grovekeeper", "c": "Dryad", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "Is it true? That flowers in Brokilon bloom seven times a year? But... How can that be?"}, {"a": 1448, "n": "Treant Mantis: Stalk", "c": "Trap", "r": "Epic", "f": "Scoiatael", "t": "Artifact", "fl": "Feel to you like we're bein' followed?"}, {"a": 1439, "n": "Forest Whisperer", "c": "Dryad", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "The dryads of Brokilon mastered a unique craft – to shape trees at will... And breathe into them life."}, {"a": 1438, "n": "Brokilon Sentinel", "c": "Dryad, Warrior", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "Brokilon is not merely the forest you see before you. She yet lives on in the cities, villages, and fields you so callously carved from her flesh. We shall yet reclaim what you have stolen from her."}, {"a": 1349, "n": "Dryad Ranger", "c": "Dryad, Warrior", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "I do not live in the forest of Brokilon. I am a part of it."}, {"a": 1679, "n": "Dryad Matron", "c": "Dryad", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "She teaches young dryads many useful skills: fletching arrows, communing with the forest, slitting the throats of men..."}, {"a": 1746, "n": "Dryad Fledgling", "c": "Dryad", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "Having recently tasted of the Water of Brokilon, she yet feels strange in her new skin... Her gift for killing, on the other hand, bloomed without delay."}, {"a": 1666, "n": "Knut the Callous", "c": "Human, Cultist, Warrior", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "Knut, son of Oluf? Aye, never has a jarl's moniker fit so well."}, {"a": 1667, "n": "Svalblod Totem", "c": "Location", "r": "Legendary", "f": "Skellige", "t": "Artifact", "fl": "All totems to Svalblod were ordered destroyed, yet on distant, forgotten shores some yet stand tall... And continue to collect new victims."}, {"a": 1668, "n": "Artis", "c": "Human, Cultist, Druid", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "Not all Svalblod priests were forced from the isles... Unfortunately."}, {"a": 1669, "n": "Vildkaarl", "c": "Human, Cultist, Warrior", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "Strike me! C'mon, harder! You call this pain?!"}, {"a": 1670, "n": "Arnvald", "c": "Human, Cultist", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "His name on the island was synonymous with loyalty. For a time."}, {"a": 1671, "n": "Sigvald", "c": "Human, Cultist, Warrior", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "A vildkaarl that lives to old age earns the respect of his clan."}, {"a": 1674, "n": "Corrupted Flaminica", "c": "Human, Cultist, Druid", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "At times, even druids succumb to Svalblod's whispers..."}, {"a": 1455, "n": "Svalblod Priest", "c": "Human, Cultist, Druid", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "The cruelty of Svalblod priests proved so fierce, so merciless that – upon the cult's collapse – they were condemned and cast out to the high seas aboard longships with nary a paddle nor sail to guide them."}, {"a": 1774, "n": "Svalblod Cultist", "c": "Human, Cultist", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "They... They's butcherin' folk, Captain! S-sacrifices to a bear god or some such!"}, {"a": 1673, "n": "Svalblod Fanatic", "c": "Human, Cultist", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "Not all are worthy of Svalblod's blessing."}, {"a": 1775, "n": "Primal Savagery", "c": "Raid", "r": "Rare", "f": "Skellige", "t": "Special", "fl": "Not all of Svalblod's worshippers wield bow and blade. They've simply no need."}, {"a": 1590, "n": "Disgraced Brawler", "c": "Human, Cultist, Warrior", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "Skellige's no home to murderers and rogues... Their crimes must be repaid in blood."}, {"a": 1372, "n": "Dettlaff: Higher Vampire", "c": "Vampire", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "In his true form, the Beast of Beauclair could cause even a witcher to quake in his boots."}, {"a": 1909, "n": "Courier", "c": "Human, Agent, Blindeyes", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "'Tis not steel and blood that wins wars, but information."}, {"a": 1908, "n": "Renegade Mage", "c": "Human, Mage, Blindeyes", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "I really hope that's boot leather I smell burning..."}, {"a": 1399, "n": "Caleb Menge", "c": "Human, Witch Hunter", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "Deceivers, heretics, witches! They flood our city, corrupt our virtue, and threaten our very way of life!"}, {"a": 1907, "n": "Beggar", "c": "Human, Agent, Blindeyes", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "Say what you will about his technique, I think he captured your good side."}, {"a": 1377, "n": "Philippa Eilhart", "c": "Human, Mage", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "Soon the power of kings will wither, and the Lodge shall seize its rightful place."}, {"a": 1850, "n": "Sigi Reuven", "c": "Human, Agent, Aristocrat", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "You sure he don't look the least bit familar...?"}, {"a": 1851, "n": "Vivaldi Bank", "c": "", "r": "Legendary", "f": "Syndicate", "t": "Special", "fl": "We're sorry to lose your business, but we wish ye well with those dunderhe-- er... With those fine folk over at Cianfanelli Bank."}, {"a": 1906, "n": "Eavesdrop", "c": "Crime, Blindeyes", "r": "Common", "f": "Syndicate", "t": "Special", "fl": "There are always more ears in the room than those you can count."}, {"a": 1760, "n": "Graden", "c": "Human, Witch Hunter", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "Initially, we burned any tomes on black magic we found. Recently we decided it might be wise to read them first."}, {"a": 5190, "n": "Blood Money", "c": "Leader", "r": "Legendary", "f": "Syndicate", "t": "Ability", "fl": "A war with Whoreson will see Novigrad's gutters run red with blood."}, {"a": 1804, "n": "Kurt", "c": "Human, Witch Hunter", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "Oy, Kurt, find out what Merigold's hollerin' about, if she needs anything. A hot iron to the tongue, maybe?"}, {"a": 1853, "n": "Moreelse", "c": "Human, Witch Hunter", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "Some witch hunters truly believed the eradication of mages and sorceresses would make the world a better place. Moreelse did not require such a lofty justification."}, {"a": 1905, "n": "Blindeye Apothecary", "c": "Human, Blindeyes", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "After her husband died in a tragic carriage accident, she threw herself completely into her work."}, {"a": 1737, "n": "Horst Borsodi", "c": "Human", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "My auction house is, above all, a gathering place for the elite of the elite."}, {"a": 1904, "n": "Sly Seductress", "c": "Human, Agent, Blindeyes", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "The sweeter her words, the more bitter your losses."}, {"a": 1753, "n": "Ewald Borsodi", "c": "Human", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "I've crafted this plan for over a year, but now the time's come for action. Can I count on your help?"}, {"a": 1903, "n": "Pickpocket", "c": "Crime, Blindeyes", "r": "Epic", "f": "Syndicate", "t": "Special", "fl": "My apologies, miss... Always been a clumsy one, I have."}, {"a": 1400, "n": "Tamara Strenger", "c": "Human, Witch Hunter", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "Once the heat of the Fire has set your heart aflame, it gives you strength and leads you down the path of truth for the rest of your life."}, {"a": 1842, "n": "Whoreson Senior", "c": "Human, Cutups", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "Like father, like son."}, {"a": 1902, "n": "Adriano the Mink", "c": "Human, Agent, Blindeyes", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "Right here, beautiful. Have a sit on daddy's lap."}, {"a": 1733, "n": "Back-Alley Chemist", "c": "Human", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "I do this for my family, always for my family!"}, {"a": 1901, "n": "Adalbertus Kalkstein", "c": "Human, Blindeyes", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "Before Kalkstein departed this world, he left us with some rather unflattering words about our gracious king..."}, {"a": 1744, "n": "Oxenfurt Naturalist", "c": "Human", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "When handling mandrake, you must always remember to don a pair of protective... Wait, where are my gloves?"}, {"a": 1900, "n": "Rico Meiersdorf", "c": "Halfling, Agent, Blindeyes", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "I never did much like bees."}, {"a": 1436, "n": "Witch Hunter Executioner", "c": "Human, Witch Hunter", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "It'd be a right shame if I cut any of your beautiful hair."}, {"a": 1899, "n": "Slander", "c": "Crime", "r": "Common", "f": "Syndicate", "t": "Special", "fl": "All Novigradians have two great passions: coin and hearsay."}, {"a": 1437, "n": "Witch Hunter", "c": "Human, Witch Hunter", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "Long coats, wide-brimmed hats, and crooked grins – witch hunters are hard to miss."}, {"a": 1898, "n": "Madame Luiza", "c": "Human, Agent, Blindeyes", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "We've bedded more men than all Redania's army barracks combined."}, {"a": 1734, "n": "Fisstech", "c": "Crime", "r": "Common", "f": "Syndicate", "t": "Special", "fl": "Large pupils, chattering teeth, a mad cackle... Aye, that's fisstech for ye."}, {"a": 1841, "n": "Igor the Hook", "c": "Human, Cutups", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "In the left corner, a bloodthirsty shaelmaar, and in the right co--oh bollocks... Fight's over, hold your bets!"}, {"a": 1897, "n": "Tinboy", "c": "Human, Blindeyes", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "Tinboy's old man labored as a metalworker. On his sober days, he smelted tin. On his drinking days, he smelted his son's face."}, {"a": 1896, "n": "Doadrick Leumaerts", "c": "Human, Agent, Blindeyes", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "The emperor has high expectations for you. See that you do not disappoint him. Hael Ker'zaer!"}, {"a": 1837, "n": "Tatterwing", "c": "Beast, Cutups", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "She seems a bit sluggish. A few quick jabs to the ribs oughta liven her up."}, {"a": 5193, "n": "Off the Books", "c": "Leader", "r": "Legendary", "f": "Syndicate", "t": "Ability", "fl": "Titles and trinkets don't interest me. I desire power, and power alone."}, {"a": 1894, "n": "Dip in the Pontar", "c": "Crime, Tidecloaks", "r": "Common", "f": "Syndicate", "t": "Special", "fl": "The Pontar's got more bodies than fish these days."}, {"a": 1839, "n": "Payday", "c": "Crime, Cutups", "r": "Common", "f": "Syndicate", "t": "Special", "fl": "I-I already gave ye all me coin!"}, {"a": 1893, "n": "Tidecloak Hideaway", "c": "Machine, Ship, Tidecloaks", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "Once a terror of the high seas, it now sits idle and fat with gold, unable to leave port."}, {"a": 1840, "n": "Pugo Boom-Breaker", "c": "Ogroid, Cutups", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "Listen, troll, I can promise you a hundred crowns if you take the fa--AAAAAAGH!!!"}, {"a": 1838, "n": "Boris", "c": "Beast, Cutups", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "After getting a taste of human flesh, he won't eat anything else."}, {"a": 1892, "n": "Sewer Raiders", "c": "Human, Pirate, Tidecloaks", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "Built for movin' shite, but it moves coin just as well."}, {"a": 1855, "n": "Wretched Addict", "c": "Human", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "I'd sell me own mum for a whiff. And I'd cut 'er throat for two."}, {"a": 1891, "n": "Eventide Plunder", "c": "Crime, Tidecloaks", "r": "Rare", "f": "Syndicate", "t": "Special", "fl": "Wouldn't be right to let all this rot in port. We's doin' 'em a favor, really."}, {"a": 1738, "n": "Whoreson's Freak Show", "c": "Human, Cutups", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "Why the long face, friend?"}, {"a": 1856, "n": "Townsfolk", "c": "Human", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "You see people, but I see a flock o' sheep that needs fleecin'."}, {"a": 1890, "n": "Tidecloak Ransackers", "c": "Human, Pirate, Tidecloaks", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "There's more wealth in Novigrad than in all of Skellige – and the number of poor saps to match."}, {"a": 1857, "n": "Tax Collector", "c": "Human", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "Just between rat catcher and latrine shoveler on this year's most desirable professions list."}, {"a": 1755, "n": "Sea Jackal", "c": "Human, Pirate, Tidecloaks", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "You ever lift rings off a body that's been left to soak for two weeks? No? Then don't complain."}, {"a": 1843, "n": "Kikimore Warrior", "c": "Insectoid, Cutups", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "Come spring, the buggers start to burst through the woodwork. Literally."}, {"a": 1858, "n": "Line of Credit", "c": "Crime, Blindeyes", "r": "Common", "f": "Syndicate", "t": "Special", "fl": "Illiterate, ye say? A moment, if ye could. I'll draw us up another agreement..."}, {"a": 1889, "n": "Fence", "c": "Human, Pirate, Tidecloaks", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "I prefer the term curator."}, {"a": 1859, "n": "Fisstech Trafficker", "c": "Human, Blindeyes", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "Addictive? Why, not at all! I've quit several times before!"}, {"a": 1888, "n": "Hvitr and Aelydia", "c": "Human, Pirate, Tidecloaks", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "Inseparable. Invincible. Irresponsible."}, {"a": 5194, "n": "Congregate", "c": "Leader", "r": "Legendary", "f": "Syndicate", "t": "Ability", "fl": "Hierarch of the Eternal Fire, enthusiast of the arena, glutton of feasts, and luster of whores."}, {"a": 1860, "n": "Prophet Lebioda", "c": "Human, Firesworn, Cleric", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "To thine own self be judge and ruler for thou alone shalt answer for thine deeds before thee."}, {"a": 1741, "n": "Sacred Flame", "c": "Firesworn", "r": "Legendary", "f": "Syndicate", "t": "Artifact", "fl": "Do you feel it? I sense something else beyond its warmth, something more..."}, {"a": 1861, "n": "Grand Inquisitor Helveed", "c": "Human, Firesworn, Cleric", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "No sinful wretch shall escape his fate in the Fire. Of that, I will make sure."}, {"a": 1844, "n": "Arena Endrega", "c": "Insectoid, Cutups", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "Strong as an ox, dumb as a box."}, {"a": 1862, "n": "Damnation", "c": "Crime, Firesworn", "r": "Epic", "f": "Syndicate", "t": "Special", "fl": "I can't bloody breathe! Won't they burn the wretches someplace else?"}, {"a": 1791, "n": "Nathaniel Pastodi", "c": "Human, Firesworn, Cleric", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "Novigrad – where the impossible becomes possible. A professional torturer turned reverend, for instance."}, {"a": 1750, "n": "Procession of Penance", "c": "Human, Firesworn", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "Careful not to stand too close. Got blood splattered on me favorite tunic last time."}, {"a": 1887, "n": "Sukrus", "c": "Human, Pirate, Tidecloaks", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "One of many who sought fortune in Novigrad. And one of many more who never found it."}, {"a": 1863, "n": "Excommunication", "c": "Crime, Firesworn", "r": "Epic", "f": "Syndicate", "t": "Special", "fl": "Aye, better than the pyre, I suppose... But did ye hear the disappointment in his voice? Now that's real sufferin'."}, {"a": 1845, "n": "Arena Ghoul", "c": "Necrophage, Cutups", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "He'll be a perfect fit for your arena. Just like a mutt lickin' your plate after dinner."}, {"a": 1886, "n": "Tavern Brawl", "c": "Crime, Tidecloaks", "r": "Epic", "f": "Syndicate", "t": "Special", "fl": "About time we had some entertainment! My knuckles are itchin'!"}, {"a": 1846, "n": "Wheel of Fortune", "c": "Crime, Cutups", "r": "Epic", "f": "Syndicate", "t": "Special", "fl": "A game where good aim is considered subjective."}, {"a": 1885, "n": "Bincy Blumerholdt", "c": "Halfling, Pirate, Tidecloaks", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "In all Novigrad, she has the hairiest feet and the stickiest hands."}, {"a": 1434, "n": "Eternal Fire Priest", "c": "Human, Firesworn, Cleric", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "Closer, my sheep, gather closer. May the Eternal Fire warm your souls!"}, {"a": 1847, "n": "Cutup Lackey", "c": "Human, Cutups", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "The boss always gets to have the most fun. Truth be told, I prefer to watch anyway."}, {"a": 1884, "n": "Hammond", "c": "Human, Cultist, Pirate, Tidecloaks", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "Once mistaken for a whale calf and nearly harpooned. He's avoided swimming ever since."}, {"a": 1431, "n": "Eternal Fire Inquisitor", "c": "Human, Firesworn, Cleric", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "The burning light of the Eternal Fire reveals all!"}, {"a": 1749, "n": "Eternal Fire Disciple", "c": "Human, Firesworn, Cleric", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "Look into your hearts, dear brethen. Does a contempt for injustice not burn within it?"}, {"a": 1883, "n": "The Flying Redanian", "c": "Specter, Ship", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "Legend tells of a Redanian crew from generations past who unearthed a treasure so great they became forever destined to argue amongst themselves on how to divide their spoils."}, {"a": 1848, "n": "Casino Bouncers", "c": "Human, Cutups", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "Junior said our nasty mugs was frightenin' off all the coin. Don't rightly see 'ow this helps any..."}, {"a": 1823, "n": "Keeper of the Flame", "c": "Human, Firesworn, Cleric", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "The flame shall forever burn, for evil shall forever corrupt!"}, {"a": 1882, "n": "Imke", "c": "Human, Pirate, Tidecloaks", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "No sooner had she caught Gudrun's attention than sought to exploit it."}, {"a": 1849, "n": "Bloody Good Fun", "c": "Crime, Cutups", "r": "Common", "f": "Syndicate", "t": "Special", "fl": "What do ye mean, Why? The game was beginnin' to drag!"}, {"a": 1743, "n": "Temple Guard", "c": "Human, Soldier, Firesworn", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "Halt! Who goes there?! Firesworn or heretic?"}, {"a": 5191, "n": "Jackpot", "c": "Leader", "r": "Legendary", "f": "Syndicate", "t": "Ability", "fl": "Any hopes that a woman's presence might soften the city's underbelly proved misguided. Horribly, woefully misguided."}, {"a": 1864, "n": "Congregation", "c": "Crime, Firesworn", "r": "Common", "f": "Syndicate", "t": "Special", "fl": "Our church is not this temple, not our scripture. It is our people, our community, we who have faith."}, {"a": 1880, "n": "Halfling Safecracker", "c": "Halfling, Crownsplitters", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "With ears sharp as his, he could've been a musician. Alas, one cannot get rich as quickly from applause."}, {"a": 1865, "n": "Firesworn Scribe", "c": "Human, Firesworn, Cleric", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "Wouldn't disturb him if I were you. Those quills are bloody sharp."}, {"a": 1879, "n": "Bare-Knuckle Brawler", "c": "Dwarf, Crownsplitters", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "Is tha' all that's left of 'im?\\nThink I'm goin' tae boak..."}, {"a": 1878, "n": "Shakedown", "c": "Crime, Crownsplitters", "r": "Common", "f": "Syndicate", "t": "Special", "fl": "Nae need to be stingy, pal. There's plenty to go 'round."}, {"a": 1877, "n": "Coerced Blacksmith", "c": "Human, Crownsplitters", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "Do ye prefer a full coin purse or a full set of fingers?"}, {"a": 1876, "n": "Swindle", "c": "Crime, Crownsplitters", "r": "Common", "f": "Syndicate", "t": "Special", "fl": "There are a hundred ways to fleece a sheep. And Cleaver's crew knew them all."}, {"a": 1875, "n": "Cleaver's Muscle", "c": "Dwarf, Crownsplitters", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "Those who try to cheat Cleaver are in for a rude awakening... And a rough landing."}, {"a": 1874, "n": "Crownsplitter Thug", "c": "Dwarf, Crownsplitters", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "Frilly frock or Mahakam steel breastplate – wouldn't have mattered."}, {"a": 1873, "n": "Harald Gord", "c": "Dwarf, Crownsplitters", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "The last occasion Harald's grim countenance betrayed a smile was in 1211 when Brouver Hoog drunkenly ate five bowls of goat and cabbage stew then promptly shat his trousers."}, {"a": 1872, "n": "Novigradian Justice", "c": "Crime, Crownsplitters", "r": "Legendary", "f": "Syndicate", "t": "Special", "fl": "With both arms tied behind me back, recall ye said. So feel free to start kickin' me in the arse when the mood strikes ye."}, {"a": 1871, "n": "Sir Skewertooth", "c": "Beast, Knight, Crownsplitters", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "Here he is! My knight in swining armor!"}, {"a": 1870, "n": "Tunnel Drill", "c": "Machine, Crownsplitters", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "Though originally designed for mining excavations under Mount Carbon, the machine struck more gold under the streets of Novigrad."}, {"a": 1869, "n": "Caesar Bilzen", "c": "Dwarf, Crownsplitters", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "Avid angler, meticulous collector, and a real piece of work."}, {"a": 1868, "n": "The Sausage Maker", "c": "Dwarf, Crownsplitters", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "Body disposal and sausage makin', that's what I do. And judgin' by that expression, I'd say ye already ken th' answer to your follow-up question."}, {"a": 1867, "n": "Ferko the Sculptor", "c": "Dwarf, Crownsplitters", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "Some call it base thuggery. But me, I consider it the highest art form."}, {"a": 5195, "n": "Pirate's Cove", "c": "Leader", "r": "Legendary", "f": "Syndicate", "t": "Ability", "fl": "Me hogs willnae go hungry th' day thanks to ye."}, {"a": 1968, "n": "Walter Veritas", "c": "Human", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "In a city that feeds on lies, truth can be a weapon."}, {"a": 1916, "n": "Geralt: Axii", "c": "Witcher", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Placing his left arm around the horse's neck, Geralt makes the Axii sign with the fingers of his right hand above the steed's head and whispers the incantation."}, {"a": 1684, "n": "Knickers", "c": "Beast, Bandit", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Leave it alone, Knickers! Damn it, leave it alone!"}, {"a": 1785, "n": "Olgierd: Immortal", "c": "Human, Cursed, Bandit", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "All of my dreams have come true. Unfortunately."}, {"a": 1742, "n": "Iris: Shade", "c": "Specter, Cursed", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Olgierd's betrothed was like a dream…"}, {"a": 1925, "n": "Gascon: Iron Falcon", "c": "Human, Bandit", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "I'm doing what I used to do and they're paying me for it!"}, {"a": 1926, "n": "One-Eyed Betsy", "c": "Ogroid, Bandit", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Maybe she lacks depth perception, but she sure packs a wallop."}, {"a": 1795, "n": "Vlodimir von Everec", "c": "Specter, Bandit", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Vlodimir liked to have a good time when he was alive and greatly missed having fun after his death."}, {"a": 1803, "n": "Free Company", "c": "Human, Bandit", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "It's because we're free to do whatever we want! Ha, ha, ha!"}, {"a": 1928, "n": "Living Armor", "c": "Construct", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Sure it's expensive. But considering how much you'll save on room and board, you'll get a return on the investment by the end of this century!"}, {"a": 1929, "n": "Armory", "c": "Location", "r": "Epic", "f": "Neutral", "t": "Artifact", "fl": "Guisarmes? Maces? Spiked Maces? I have everything you could possibly need."}, {"a": 1930, "n": "Surrender", "c": "Tactic", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "There's no shame in waving the white flag."}, {"a": 1552, "n": "Wagenburg", "c": "Machine, Siege Engine", "r": "Rare", "f": "Neutral", "t": "Unit", "fl": "Dh'oine can turn anything into a weapon. Even a simple wagon…"}, {"a": 1947, "n": "Iron Falcon Knife Juggler", "c": "Human, Bandit", "r": "Rare", "f": "Neutral", "t": "Unit", "fl": "The weapon's short, but its range is long."}, {"a": 1948, "n": "Iron Falcon Infantry", "c": "Human, Bandit", "r": "Rare", "f": "Neutral", "t": "Unit", "fl": "You have to look good on the battlefield too."}, {"a": 1949, "n": "Iron Falcon Troubadour", "c": "Dwarf, Bandit", "r": "Rare", "f": "Neutral", "t": "Unit", "fl": "When I play even dying's more pleasant."}, {"a": 1950, "n": "Piercing Missile", "c": "", "r": "Rare", "f": "Neutral", "t": "Special", "fl": "There's no armor that can't be pierced."}, {"a": 1664, "n": "Wagon", "c": "Machine", "r": "Common", "f": "Neutral", "t": "Unit", "fl": "The driver swore he was carrying seeds. But seeds don't clank on bumps in the road…"}, {"a": 1556, "n": "Mantlet", "c": "Machine, Siege Engine", "r": "Common", "f": "Neutral", "t": "Unit", "fl": "Something like the bastard child of a shield and a palisade."}, {"a": 1560, "n": "Sapper", "c": "Human, Soldier", "r": "Common", "f": "Neutral", "t": "Unit", "fl": "Aim wherever you want. The shrapnel will take care of it."}, {"a": 1557, "n": "Highwaymen", "c": "Human, Bandit", "r": "Common", "f": "Neutral", "t": "Unit", "fl": "We'll torture the merchant and sell the horses."}, {"a": 1951, "n": "Armorer's Workshop", "c": "", "r": "Common", "f": "Neutral", "t": "Special", "fl": "He'll make a helm out of a pot if need be."}, {"a": 1076, "n": "Philippa: Blind Fury", "c": "Human, Mage", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "Philippa Eilhart, though very attractive, was decidedly very unkind."}, {"a": 1794, "n": "Donimir of Troy", "c": "Human, Soldier, Knight", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "I fought twice at Sodden and lived. I think you can surmise I'm not so bad at this sword thing."}, {"a": 1805, "n": "Voymir", "c": "Human, Soldier", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "Quietly, on tiptoes, no noise, no fuss. Through the back alleys. In Loxia and the port keep your mouth shut! Go!"}, {"a": 1739, "n": "Mad Charge", "c": "Warfare", "r": "Rare", "f": "Northern Realms", "t": "Special", "fl": "You can't stop a galloping cavalry horse. So if things go bad, the only thing to do is to lower your lance, close your eyes and pray to the gods."}, {"a": 1817, "n": "Radovid's Royal Guards", "c": "Human, Soldier", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "They'll do anything for their king. They know what he'll do to them if they refuse."}, {"a": 1754, "n": "Redanian Archer", "c": "Human, Soldier", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "The last thing you'll hear is the twang of the bowstring being let go."}, {"a": 1752, "n": "Azar Javed", "c": "Human, Mage, Salamandra", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "Azar Javed's specialty is the element of fire. The sorcerer not only deftly manipulates the power of fire, it can be said that fire has become a part of his very being."}, {"a": 1816, "n": "Professor", "c": "Human, Salamandra", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "I fear our conventicle may end disastrously for you."}, {"a": 1756, "n": "Savolla", "c": "Human, Mage, Salamandra", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "Witcher mutagens are a forgotten treasure. It's time the world learned of their potential."}, {"a": 1740, "n": "Dire Mutated Hound", "c": "Beast, Mutant, Salamandra", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "We couldn't decide what to name him and it just kind of came up…"}, {"a": 1761, "n": "Mutated Hounds", "c": "Beast, Mutant, Salamandra", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "Out of man's best friend we made his worst enemy."}, {"a": 1822, "n": "Assault", "c": "Crime, Salamandra", "r": "Rare", "f": "Syndicate", "t": "Special", "fl": "Human life is fragile. Especially in Novigrad."}, {"a": 1821, "n": "Salamandra Assassin", "c": "Human, Salamandra", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "A name and bag full of gold. That's all I need."}, {"a": 1435, "n": "Mutant Killer", "c": "Human, Mutant, Salamandra", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "You have to keep him on a leash, muzzled and with blinders on, otherwise it'll be trouble."}, {"a": 1967, "n": "Mutant", "c": "Human, Mutant, Salamandra", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "With the right tools you can shape the human body like wet clay."}, {"a": 1913, "n": "Kikimore Queen", "c": "Insectoid", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "Many insectoids live in a matriarchy. A bloody one at that."}, {"a": 1924, "n": "Cave Troll", "c": "Ogroid", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "Trolls have very tiny brains and huge stomachs. That's a very dangerous combination."}, {"a": 1927, "n": "Yghern", "c": "Insectoid", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "Its other name is scolopendromorph. Rarely used, as it's hard to say without spitting all over oneself."}, {"a": 1918, "n": "Endrega Queen", "c": "Insectoid", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "The Endrega Queen can be easily recognized by the specific coloring of its abdomen. Or, more easily, by its monstrous size"}, {"a": 1915, "n": "Armored Arachas", "c": "Insectoid", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "It can cut half-inch thick metal like a tailor cutting silk."}, {"a": 1952, "n": "Endrega Larva", "c": "Insectoid", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "Fat, plump… and bloodthirsty."}, {"a": 1953, "n": "Endrega Warrior", "c": "Insectoid, Warrior", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "Where I come from no one was afraid of the Big Bad Wolf or Baba Yaga. Instead, we had an Endrega nest in the shrubs beyond the village."}, {"a": 1954, "n": "Natural Selection", "c": "Organic", "r": "Common", "f": "Monster", "t": "Special", "fl": "The strongest will survive. So not you."}, {"a": 1914, "n": "Kikimore Worker", "c": "Insectoid", "r": "Common", "f": "Monster", "t": "Unit", "fl": "They say it can eat a whole man in armor down to the bone in less than a minute. I'd rather not find out if it's true."}, {"a": 1955, "n": "Endrega Eggs", "c": "Insectoid", "r": "Common", "f": "Monster", "t": "Unit", "fl": "If you find some it's best to burn the entire forest down. Then run as far away as you can."}, {"a": 1932, "n": "Affan Hillergrand", "c": "Human, Soldier", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "Jarre doesn't mention him in his books. Maybe he never heard of him. Maybe he heard too much."}, {"a": 1933, "n": "Ramon Tyrconnel", "c": "Human, Soldier, Knight", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "Colonel Ramon Tyrconnel, the young commander of the Ard Feainn division, whistled softly, staring at a point somewhere off in the distance…"}, {"a": 1934, "n": "War Council", "c": "Location, Tactic", "r": "Epic", "f": "Nilfgaard", "t": "Artifact", "fl": "Nilfgaardians fight every battle twice: first on the map, then in reality."}, {"a": 1935, "n": "Ffion var Gaernel", "c": "Human, Soldier", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "Everyone will die somehow. I'll die last."}, {"a": 1936, "n": "Glynnis aep Loernach", "c": "Human, Soldier", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "She loved every soldier like a son. She cried for each one."}, {"a": 1956, "n": "Ard Feainn Crossbowman", "c": "Human, Soldier", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "Many thought that mounted crossbowmen wouldn't work. Until they saw them in action."}, {"a": 1957, "n": "Ard Feainn Tortoise", "c": "Human, Soldier", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "Close formation, clench your sphincters! Left, right, left, steady!"}, {"a": 1958, "n": "Ard Feainn Light Cavalry", "c": "Human, Soldier", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "Light cavalry, heavy burden!"}, {"a": 1959, "n": "Ard Feainn Heavy Cavalry", "c": "Human, Soldier", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "When Emhyr declared that his cavalry would stomp his enemies into the mud, we thought he was speaking metaphorically. We were wrong."}, {"a": 1960, "n": "Battle Preparation", "c": "Tactic", "r": "Common", "f": "Nilfgaard", "t": "Special", "fl": "Many a knight met an untimely death because of his shoddily tied breastplate coming undone."}, {"a": 1917, "n": "Dracoturtle", "c": "Beast", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "Oxenfurt monstrologists claim the brain of a dracoturtle is the size of a peanut. Its maw, however, is the size of a wide-open gate."}, {"a": 1937, "n": "Covenant of Steel", "c": "Human, Pirate, Warrior", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "If you want to give Skelligers a laugh, tell them they're outnumbered."}, {"a": 1938, "n": "Morkvarg: Heart of Terror", "c": "Human, Pirate", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "He showed no mercy, didn't respect our laws or our gods. He knew how it must end. And it still didn't stop him."}, {"a": 1939, "n": "Raiding Fleet", "c": "Raid", "r": "Epic", "f": "Skellige", "t": "Special", "fl": "The rocky Skellige lands, battered by cold winds, give life only to nettles and moss. But the islanders know that there is fertile soil on the other side of the sea…"}, {"a": 1940, "n": "Terror of the Seas", "c": "Machine, Ship", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "All it takes is a small hole for the largest ship to sink."}, {"a": 1961, "n": "Armored Drakkar", "c": "Machine, Ship", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "You can't take it upriver… but you can certainly take it to chase the imperial fleet."}, {"a": 1962, "n": "Terror Crew Plunderer", "c": "Human, Pirate", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "They say diamonds are a girl's best friend. But my best friend is a knife. I can use it to get anything else I want."}, {"a": 1963, "n": "Boatbuilders", "c": "Human, Pirate", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "There's no more respected profession on the islands than boat building. The worst cutthroats bow and ask how things are going…"}, {"a": 1964, "n": "Terror Crew Axe-wielder", "c": "Human, Pirate", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "But dear Skelligers, what use do you have for axes? There are no trees in the sea…"}, {"a": 1965, "n": "Stunning Blow", "c": "Raid", "r": "Common", "f": "Skellige", "t": "Special", "fl": "It clanged like hitting a bell. The Redanian fell to the ground unconscious, dark blood gushing from underneath the dented metal…"}, {"a": 1919, "n": "Zoltan: Warrior", "c": "Dwarf, Soldier, Warrior", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "I've decided to do tangible good, that is not wasted. I am good to myself and my immediate surroundings."}, {"a": 1920, "n": "Percival Schuttenbach", "c": "Gnome", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "Underneath the wet hood, instead of a billowy beard, was a long, pointed nose, clearly marking its owner as a member of the old and noble race of gnomes."}, {"a": 1921, "n": "Munro Bruys", "c": "Dwarf, Soldier", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "Munro dreamed of building steam and water-powered hammerworks. But he ended up as bouncer at the worst bar in Vizima…"}, {"a": 1922, "n": "Figgis Merluzzo", "c": "Dwarf, Soldier", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "I'm a simple guy. I like drinking, eating, singing lewd songs… And when the party dies down, pissing on the dying bonfire."}, {"a": 1923, "n": "Zoltan's Company", "c": "Nature", "r": "Epic", "f": "Scoiatael", "t": "Special", "fl": "They'd follow each other into the fire. And laugh about it."}, {"a": 1941, "n": "Dwarven Chariot", "c": "Machine, Siege Engine", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "You can draw anything you like, my dear dwarves. But you can't build it, mark my words."}, {"a": 1942, "n": "Tempering", "c": "Nature", "r": "Rare", "f": "Scoiatael", "t": "Special", "fl": "Dwarven steel is very tough. Almost as tough as the dwarves themselves."}, {"a": 1943, "n": "Miner", "c": "Dwarf", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "Which moron's whistling in the mine?!"}, {"a": 1944, "n": "Dryad Enchantress", "c": "Dryad", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "The dryads used to stay on the sidelines, avoiding the conflict between the races. But times change…"}, {"a": 1945, "n": "Dwarf Berserker", "c": "Dwarf, Soldier", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "I know I'm going to die. So I'm making sure I'll have company."}, {"a": 2002, "n": "Radeyah", "c": "Human, Mage", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "You can hide a lot behind a beautiful smile."}, {"a": 2003, "n": "Maraal", "c": "Human, Agent", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "I know how to kill in a thousand and one ways."}, {"a": 2004, "n": "Matta Hu'uri", "c": "Human, Agent", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Sorceresses use magic to hypnotize. I use dance."}, {"a": 1977, "n": "Dulla kh'Amanni", "c": "Human", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "To know the world is to praise god's name."}, {"a": 1978, "n": "Runewright", "c": "Human", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Great power lies in words. But it's not easy to enchant it into steel."}, {"a": 2005, "n": "Saer Qu'an", "c": "Beast", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Every tiger is dangerous. Especially one that has taken a liking to human flesh…"}, {"a": 2031, "n": "Caravan Vanguard", "c": "Human", "r": "Rare", "f": "Neutral", "t": "Unit", "fl": "It's not easy to find one's way among the shifting dunes…"}, {"a": 2032, "n": "Caravan Guard", "c": "Human", "r": "Rare", "f": "Neutral", "t": "Unit", "fl": "There's a lot of ways you can die in the desert. Not just from thirst."}, {"a": 2033, "n": "King Cobra", "c": "Beast", "r": "Common", "f": "Neutral", "t": "Unit", "fl": "As long as I play it'll dance. But when I stop…"}, {"a": 2034, "n": "Ofiri Merchant", "c": "Human", "r": "Common", "f": "Neutral", "t": "Unit", "fl": "I have that which you desire. As well as that which you have never seen before…"}, {"a": 2035, "n": "Basilisk Venom", "c": "", "r": "Legendary", "f": "Neutral", "t": "Stratagem", "fl": "People think a basilisk kills with its eyes, but it's the colorless fumes from its venom that cause death…"}, {"a": 2036, "n": "Crystal Skull", "c": "", "r": "Legendary", "f": "Neutral", "t": "Stratagem", "fl": "Makes for a perfect paperweight."}, {"a": 2037, "n": "Enchanted Armor", "c": "", "r": "Legendary", "f": "Neutral", "t": "Stratagem", "fl": "Lean in, listen closely, and you'll hear a whisper…"}, {"a": 2038, "n": "Cursed Scroll", "c": "", "r": "Legendary", "f": "Neutral", "t": "Stratagem", "fl": "The seal states clearly: do not open. But of course… curiosity will win out."}, {"a": 2039, "n": "Ceremonial Dagger", "c": "", "r": "Legendary", "f": "Neutral", "t": "Stratagem", "fl": "Decorated like a prince's coronet. Sharp like a butcher's knife."}, {"a": 2040, "n": "Magic Lamp", "c": "", "r": "Legendary", "f": "Neutral", "t": "Stratagem", "fl": "It's a little tarnished. A little rubbing will make it shiny again."}, {"a": 1998, "n": "Engineering Solution", "c": "", "r": "Legendary", "f": "Northern Realms", "t": "Stratagem", "fl": "Trust me, I'm an engineer."}, {"a": 1999, "n": "War Elephant", "c": "Beast, Siege Engine", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "It's kind of like a fiend, but bald and with a nose that hangs to the ground. What? No, you're making things up!"}, {"a": 2000, "n": "Siege", "c": "Scenario", "r": "Legendary", "f": "Northern Realms", "t": "Artifact", "fl": "There's no fortress that can't be taken. There are just fortresses not worth taking."}, {"a": 1976, "n": "War Chariot", "c": "Machine, Siege Engine", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "The chariot drove into the crowd and its enemies fell to the ground like wheat before the scythe…"}, {"a": 2001, "n": "Immortals", "c": "Human, Soldier", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "Where one falls, another will take his place."}, {"a": 1981, "n": "Siege Ladder", "c": "Machine, Siege Engine", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "What?! Now you tell me you're afraid of heights?!"}, {"a": 2025, "n": "Immortal Cavalry", "c": "Human, Soldier", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "Maybe camels aren't as swift as horses… but at least they don't die after two days in the desert."}, {"a": 2026, "n": "Carroballista", "c": "Machine, Siege Engine", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "This ballista's on the wagon."}, {"a": 1982, "n": "Boiling Oil", "c": "Warfare", "r": "Common", "f": "Northern Realms", "t": "Special", "fl": "Not good for your skin."}, {"a": 1983, "n": "Mask of Uroboros", "c": "", "r": "Legendary", "f": "Skellige", "t": "Stratagem", "fl": "Time doesn't flow, it goes in circles. The past becomes the future, grandfathers repeat the mistakes of their grandsons."}, {"a": 1984, "n": "In Gedyneith's Shadow", "c": "Scenario", "r": "Legendary", "f": "Skellige", "t": "Artifact", "fl": "Rulers are crowned in its shadow. Traitors are hanged on its branches."}, {"a": 1985, "n": "Crowmother", "c": "Human, Druid", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "Some crows learn human words. And some humans learn the language of the crows."}, {"a": 1971, "n": "Gigascorpion Decoction", "c": "Alchemy", "r": "Epic", "f": "Skellige", "t": "Special", "fl": "How much of a dose would be lethal? Any."}, {"a": 1986, "n": "Axel Three-Eyes", "c": "Human, Druid", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "Though his words contain much wisdom, it is easily drowned out by its madness."}, {"a": 2011, "n": "Crow Clan Druid", "c": "Human, Druid", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "Wise men claim that animals are mindless automatons. Wise men don't know what they're talking about."}, {"a": 2012, "n": "Crow Clan Preacher", "c": "Human, Druid", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "A lot of learning awaits you. And a lot of mistakes."}, {"a": 2013, "n": "Crow's-eye Rhizome", "c": "Alchemy", "r": "Common", "f": "Skellige", "t": "Special", "fl": "Fatally poisonous. Unless you know how to prepare it…"}, {"a": 2014, "n": "Crow Messenger", "c": "Beast", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "The Crowmother has a thousand eyes and each one is closely watching."}, {"a": 2006, "n": "Urn of Shadows", "c": "", "r": "Legendary", "f": "Monster", "t": "Stratagem", "fl": "Everyone carries some darkness in them. Some have learned to bend it to their will…"}, {"a": 1387, "n": "Plague Maiden", "c": "Specter", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "To bring down humanity, she will awaken her rats and send them to die in the happy city."}, {"a": 2008, "n": "Penitent", "c": "Specter", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "The places this monster haunts are quickly covered by fog and darkness. Those that get lost in it usually don't return to the living."}, {"a": 1389, "n": "The Beast", "c": "Specter", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "The Beast didn't come from nowhere. You all summoned it. With your lust, your greed and your cruelty."}, {"a": 2010, "n": "Haunt", "c": "Scenario", "r": "Legendary", "f": "Monster", "t": "Artifact", "fl": "If you don't finish your oatmeal, a Haunt will come and eat you!"}, {"a": 1409, "n": "Barghest", "c": "Specter", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "Some claim they're the vanguard of the Wild Hunt. Others that they're vengeance incarnate. Everyone agrees that barghests have no mercy for the living."}, {"a": 2028, "n": "Desert Banshee", "c": "Specter", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "You're worried you'll die of thirst in the sands? Relax. You won't make it that long."}, {"a": 1414, "n": "Noonwraith", "c": "Specter", "r": "Common", "f": "Monster", "t": "Unit", "fl": "Contrary to popular belief, farmers don't stop work in the middle of the day to hide from the heat - they hide from the Noonwraith."}, {"a": 1413, "n": "Nightwraith", "c": "Specter", "r": "Common", "f": "Monster", "t": "Unit", "fl": "How much damage can a pale, emaciated woman, entangled in a ripped dress, do? A lot, it turns out."}, {"a": 1987, "n": "Aen Seidhe Saber", "c": "", "r": "Legendary", "f": "Scoiatael", "t": "Stratagem", "fl": "When this blade cuts through the air, you don't hear a swish, you hear music…"}, {"a": 1988, "n": "Etriel", "c": "Elf, Bandit", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "People tame wild animals. I talk to them."}, {"a": 1989, "n": "Muirlega", "c": "Beast, Bandit", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "It has brushes for ears. And human blood on its teeth."}, {"a": 1990, "n": "Vernossiel", "c": "Elf, Bandit", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "It turns out that the forest isn't inhabited by, to quote the captain of the guard, some furry fucking thing, but Scoia'tael commandos. They were led by someone named Vernossiel…"}, {"a": 1972, "n": "Feign Death", "c": "Scenario", "r": "Legendary", "f": "Scoiatael", "t": "Artifact", "fl": "In order to set a trap, you should usually hide. But… there are exceptions to this rule."}, {"a": 2015, "n": "Vernossiel's Commando", "c": "Elf, Bandit", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "Only a swish could be heard... Followed by six men tumbling dead to the ground."}, {"a": 2016, "n": "Vrihedd Saboteur", "c": "Elf, Soldier, Agent", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "The gates were ordered to be closed… But they didn't budge."}, {"a": 2017, "n": "Nature's Rebuke", "c": "Nature", "r": "Common", "f": "Scoiatael", "t": "Special", "fl": "Nature has long endured man's excesses. But even she finally ran out of patience…"}, {"a": 2018, "n": "Trained Hawk", "c": "Beast", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "I whistle once, it comes back. I whistle twice, it comes back with your eyes in its talons."}, {"a": 1991, "n": "Collar", "c": "", "r": "Legendary", "f": "Nilfgaard", "t": "Stratagem", "fl": "Those who fall into debt with the Moorlehems have two options: go into slavery or kill themselves. The smart ones choose option number two."}, {"a": 1992, "n": "Vincent van Moorlehem", "c": "Vampire, Aristocrat", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "Everyone gives the Moorlehems a wide berth. Even tax collectors."}, {"a": 1993, "n": "Masquerade Ball", "c": "Scenario", "r": "Legendary", "f": "Nilfgaard", "t": "Artifact", "fl": "Ophelie Van Moorlehem loves throwing huge galas. The fact that some attendees then disappear without a trace doesn't seem to bother anyone…"}, {"a": 1973, "n": "Philippe van Moorlehem", "c": "Vampire, Aristocrat", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "It's said that Vincent Van Moorlehem fears only one man. It's not Emhyr var Emreis or Geralt of Rivia - it’s his own son."}, {"a": 1974, "n": "Van Moorlehem's Cupbearer", "c": "Human", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "My specialty? Tartar. Of what? Ah, that depends on the host's mood…"}, {"a": 2019, "n": "Van Moorlehem Hunter", "c": "Vampire, Aristocrat", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "Rather than beasts, he prefers to stalk poachers. But they don't come as often anymore into the woods surrounding the palace…"}, {"a": 2020, "n": "Hunting Pack", "c": "Beast", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "The hounds of the Van Moorlehems have an extraordinary sense of smell - and extremely sharp teeth."}, {"a": 1979, "n": "Van Moorlehem Servant", "c": "Human", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "They say she's served the Moorlehems for thirty years. And she hasn't aged a day…"}, {"a": 2021, "n": "Thirsty Dame", "c": "Vampire, Aristocrat", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "My teeth are red? Oh, that's from the wine…"}, {"a": 1994, "n": "Tiger's Eye", "c": "", "r": "Legendary", "f": "Syndicate", "t": "Stratagem", "fl": "A diamond the size of a goose egg. And worth a small country."}, {"a": 1995, "n": "Collusion", "c": "Crime", "r": "Legendary", "f": "Syndicate", "t": "Special", "fl": "There's enough gold in this city for everyone. Well, at least for us."}, {"a": 1996, "n": "One Night at the Passiflora", "c": "Scenario", "r": "Legendary", "f": "Syndicate", "t": "Artifact", "fl": "More pilgrims come here than to the Temple of the Eternal Fire…"}, {"a": 1975, "n": "Saul de Navarette", "c": "Human, Tidecloaks", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "A connoisseur with bottomless pockets and a soul black as tar."}, {"a": 1997, "n": "Ludovicus Brunenbaum", "c": "Gnome, Crownsplitters", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "They say he'd sell his own mother. But no one was buying."}, {"a": 1980, "n": "Bloody Good Friends", "c": "Crownsplitters, Cutups", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "I'll kill you as soon as we kill them!"}, {"a": 2022, "n": "Street Urchins", "c": "Human, Blindeyes", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "When I was five, I stole candy. Now I'm six and I work in robbery."}, {"a": 2023, "n": "Payroll Specialist", "c": "Human, Blindeyes", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "Guards in Novigrad work for very little money, yet live like kings. Just another paradox of the Free City…"}, {"a": 2024, "n": "Passiflora Peaches", "c": "Human, Blindeyes", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "They'll mess with your head, break your heart and empty your purse."}, {"a": 1433, "n": "Greater Brothers", "c": "Human, Mutant, Salamandra", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "A battering ram? No need, we'll handle it another way."}, {"a": 2284, "n": "Overwhelming Hunger", "c": "Leader", "r": "Legendary", "f": "Monster", "t": "Ability", "fl": ""}, {"a": 2281, "n": "Imposter", "c": "Leader", "r": "Legendary", "f": "Nilfgaard", "t": "Ability", "fl": ""}, {"a": 2285, "n": "Uprising", "c": "Leader", "r": "Legendary", "f": "Northern Realms", "t": "Ability", "fl": ""}, {"a": 2282, "n": "Mahakam Forge", "c": "Leader", "r": "Legendary", "f": "Scoiatael", "t": "Ability", "fl": ""}, {"a": 2283, "n": "Blaze of Glory", "c": "Leader", "r": "Legendary", "f": "Skellige", "t": "Ability", "fl": ""}, {"a": 2286, "n": "Hidden Cache", "c": "Leader", "r": "Legendary", "f": "Syndicate", "t": "Ability", "fl": ""}, {"a": 2229, "n": "Master Mirror", "c": "Demon", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Some figures prefer to always remain hidden while playing the role of shadow in the most crucial events in history. One figure especially, to be precise."}, {"a": 2245, "n": "Ethereal", "c": "Demon", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Her worst nightmare can easily be yours too."}, {"a": 1852, "n": "Oneiromancy", "c": "Spell", "r": "Legendary", "f": "Neutral", "t": "Special", "fl": "Deciphering the past and the future as they appear in dreams is very difficult, even for a master."}, {"a": 1762, "n": "Siegfried of Denesle", "c": "Human, Knight", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "We're on the same side, witcher. You'll realize this one day."}, {"a": 2247, "n": "Allgod", "c": "Relict", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Make your sacrifices or face divine anger! The food better be good or prepare to face my wrath nonetheless."}, {"a": 2248, "n": "Marlene de Trastamara", "c": "Human, Cursed", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "None shall sit and dine with you at your table, no spoon you have shall sate you, never again shall you wish to spy your reflection in the mirror."}, {"a": 2249, "n": "Pact", "c": "Spell", "r": "Rare", "f": "Neutral", "t": "Special", "fl": "Your wishes he grants, as he swears to adore you – Gold, silver, jewels... he lays riches before you – Dues need be repaid, and he will come for you – All to reclaim, no smile to console you!"}, {"a": 2250, "n": "Will o' the wisp", "c": "Spell", "r": "Rare", "f": "Neutral", "t": "Special", "fl": "Fool's fires... those little shiny thingies that shall lead thee to certain doom."}, {"a": 2251, "n": "Squirrel", "c": "Beast", "r": "Rare", "f": "Neutral", "t": "Unit", "fl": "Just one badass squirrel. Nothing less, nothing more."}, {"a": 2252, "n": "Offering", "c": "", "r": "Common", "f": "Neutral", "t": "Special", "fl": "Both gods and demons alike can be appeased by a plentiful sacrifice."}, {"a": 2253, "n": "Fortune Teller", "c": "Human", "r": "Common", "f": "Neutral", "t": "Unit", "fl": "Her prophecies have never been wrong – mainly because she always predicts something bad to happen."}, {"a": 2185, "n": "Auberon: King", "c": "Elf, Wild Hunt", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "The end of one world can be the beginning of another."}, {"a": 1127, "n": "Eredin Bréacc Glas", "c": "Elf, Wild Hunt", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "Any last words?"}, {"a": 2189, "n": "Ard Gaeth", "c": "Wild Hunt", "r": "Legendary", "f": "Monster", "t": "Special", "fl": "Very useful for travels to other dimensions and bringing apocalypse upon the world."}, {"a": 2190, "n": "Winter Queen", "c": "Elf, Wild Hunt", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "Truth is but a shard of ice."}, {"a": 2191, "n": "The Apiarian Phantom", "c": "Beast, Wild Hunt", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "Who's a good boy? Well, surely not him."}, {"a": 2192, "n": "Red Riders", "c": "Wild Hunt", "r": "Rare", "f": "Monster", "t": "Special", "fl": "They paint the sky with snow and the earth with fire."}, {"a": 2195, "n": "Wild Hunt Bruiser", "c": "Elf, Wild Hunt", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "He considers it an excellent joke - to split the skulls of the living with the skulls of the dead."}, {"a": 2193, "n": "Naglfar Crew", "c": "Elf, Wild Hunt", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "Humans don’t know what powers the Naglfar. What is the source of its magic? For those that discover the truth... Well, it’s already too late for them."}, {"a": 2194, "n": "Naglfar Taskmaster", "c": "Elf, Wild Hunt", "r": "Common", "f": "Monster", "t": "Unit", "fl": "She ensures the ship is sustained by squeezing the life essence from those insignificant human vermin."}, {"a": 2196, "n": "Aen Elle Conqueror", "c": "Elf, Wild Hunt", "r": "Common", "f": "Monster", "t": "Unit", "fl": "For his noble kind morality is but a whim enjoyed by others. More specifically, those who lose."}, {"a": 2232, "n": "Harald an Craite", "c": "Human, Warrior", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "His battle with the bear made him a different man, no doubt. But many argue if for the better."}, {"a": 2235, "n": "Tyrggvi Tuirseach", "c": "Human, Pirate, Warrior", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "It’s not betrayal if you side with the winner."}, {"a": 2236, "n": "Blood Eagle", "c": "Raid", "r": "Legendary", "f": "Skellige", "t": "Special", "fl": "Fly like an eagle – Let my spirit carry me – I want to fly like an eagle."}, {"a": 2237, "n": "Skjordal Drummond", "c": "Human, Warrior", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "He believed in honor, and that became his undoing."}, {"a": 2238, "n": "Herkja Drummond", "c": "Human, Warrior", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "Faithful to her clan and its jarl, her father – to the very end."}, {"a": 2239, "n": "War of Clans", "c": "Raid", "r": "Rare", "f": "Skellige", "t": "Special", "fl": "Brother against brother, sister against sister. One blood that soaks up the ground."}, {"a": 2241, "n": "Tuirseach Invader", "c": "Human, Pirate, Warrior", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "Mother of four, ya sayeth? Well, then she shouldst been smarter than running 'round with an axe."}, {"a": 2240, "n": "An Craite Raiders", "c": "Human, Pirate, Warrior", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "Cabbage, really? It’s just the worst when there’s nothing good to plunder."}, {"a": 2242, "n": "Drummond Villager", "c": "Human, Warrior", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "The lovely jointress, mother of four, wondrous cook, and last but not least – a fierce warrior."}, {"a": 2243, "n": "Drummond Berserker", "c": "Human, Cultist, Warrior", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "Tis but a scratch, aye?"}, {"a": 2197, "n": "Jacques: Miracle Child", "c": "Human", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "As a child he loved two things: playing with his toy soldiers and a game called “Kill the Elf”."}, {"a": 1780, "n": "Ulrich", "c": "Human, Knight, Firesworn", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "When the Order was disbanded, those who didn't join the witch hunters formed the Fallen Knights, of which Ulrich became the Grand Master."}, {"a": 2200, "n": "Dies Irae", "c": "Crime, Firesworn", "r": "Legendary", "f": "Syndicate", "t": "Special", "fl": "The righteous wrath of the Eternal Fire! Justice of the Flaming Rose!"}, {"a": 1793, "n": "Roderick de Wett", "c": "Human, Knight, Firesworn", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "Count de Wett is exceptionally loathsome and arrogant, but at least he enjoys a little dice poker on the side."}, {"a": 1751, "n": "Lieutenant von Herst", "c": "Human, Knight, Firesworn", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "The fall of the Order wasn’t so hard for him like for the others. He is still required to count the goods and manage supplies, only now it has become even easier… Less strict at least."}, {"a": 2201, "n": "Smuggle", "c": "Crime, Firesworn", "r": "Rare", "f": "Syndicate", "t": "Special", "fl": "Whoever said that the dead are good for nothing? They make for such great smuggle-bags."}, {"a": 1430, "n": "Cleric of the Flaming Rose", "c": "Human, Firesworn, Cleric", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "We have two eyes, two ears, but only one tongue, so that we would look and listen twice more than we speak."}, {"a": 1758, "n": "Fallen Knight", "c": "Human, Knight, Firesworn", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "He abandoned the righteous fight and the flame in him has long gone."}, {"a": 1812, "n": "Lonely Champion", "c": "Human, Knight, Firesworn", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "So long as he continues the righteous fight, the Order and its flame endure."}, {"a": 2204, "n": "Mutants Maker", "c": "Human, Firesworn, Salamandra", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "I’m a scientist, truly. I can’t help it if the Oxenfurt professors were just too narrow-sighted to appreciate my particular research methods."}, {"a": 2217, "n": "Viraxas: Prince", "c": "Human", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "Parents often envy their children's strength and vigor. And children rarely notice it."}, {"a": 2223, "n": "Ildiko", "c": "Human, Mage, Aristocrat", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "The necklace was Ildiko’s gift to king Belohun in honor of their impending marriage. By choking the old fool, it solved that problem quite nicely."}, {"a": 2221, "n": "Amphibious Assault", "c": "Warfare", "r": "Legendary", "f": "Northern Realms", "t": "Special", "fl": "One ship here, one ship there, and the kingdom will be ours!"}, {"a": 2220, "n": "King Belohun", "c": "Human, Aristocrat", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "The king, quite rightly, didn’t trust anyone. He also didn’t believe anybody capable of outsmarting him. This proved a fatal assumption."}, {"a": 2222, "n": "Egmund", "c": "Human, Soldier", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "Since father has never appreciated nor trusted Egmund, it was but a simple decision to betray him."}, {"a": 2225, "n": "Smoke Them Out!", "c": "Warfare", "r": "Rare", "f": "Northern Realms", "t": "Special", "fl": "Fight fire with fire, fight people with fire, fight non-humans with fire... Basically it’s best to fight everything with fire!"}, {"a": 2224, "n": "Kerack Frigate", "c": "Machine, Siege Engine, Ship", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "“I should buy a boat”, said a Kerackian cat once. Or so claims the drunken ballad."}, {"a": 2226, "n": "Kerack City Guard", "c": "Human, Soldier", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "Geralt thought there were no ugly women, but in the guardhouse of Kerack he felt compelled to revise this view."}, {"a": 2227, "n": "Kerack Marine", "c": "Human, Soldier, Pirate", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "I spy with my little eye something that is… green. Oh, shite! That’s a dryad!"}, {"a": 2228, "n": "Kerack Cutthroat", "c": "Human, Soldier, Bandit", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "He massacred that poor dryad’s body to the point that even her own mother would no longer be able to recognize it."}, {"a": 2070, "n": "Usurper: Officer", "c": "Human, Soldier", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "He was an ordinary soldier until his mind was open to the madness around him."}, {"a": 2073, "n": "Braathens", "c": "Human, Mage, Agent", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "His name sounded so similar to “urchin” in Nilfgaardian that Braathens decided to turn him into one. Years later Emhyr paid the mage back in kind. Braathens sounds just like “fried” after all."}, {"a": 2074, "n": "Coup de Grâce", "c": "Tactic", "r": "Legendary", "f": "Nilfgaard", "t": "Special", "fl": "Sometimes death is but a simple act of mercy."}, {"a": 2075, "n": "Fergus var Emreis", "c": "Human, Aristocrat", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "Usurper demanded that the fallen emperor grant legitimacy to the coup, and when Fergus refused, his 13-year-old son, Emhyr, was tortured. But that changed nothing."}, {"a": 2076, "n": "Urcheon of Erlenwald", "c": "Human, Cursed, Knight", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "This is how I look, which you well knew, Calanthe. King Roegner, in telling you of the oath, would not have omitted such a detail in his tale."}, {"a": 2078, "n": "Amnesty", "c": "Tactic", "r": "Rare", "f": "Nilfgaard", "t": "Special", "fl": "You did what to who? To be fair, I can’t even recall the specifics anymore."}, {"a": 2077, "n": "Mage Torturer", "c": "Human, Mage, Agent", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "Your pain is my delight."}, {"a": 2081, "n": "Seditious Aristocrats", "c": "Human, Agent, Aristocrat", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "They love expensive wine, horse riding, and good old backstabbing."}, {"a": 2080, "n": "Mage Infiltrator", "c": "Human, Mage, Agent", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "In her spare time, she likes playing practical jokes on others. Her favorite gag is switching footwraps and headwear."}, {"a": 2183, "n": "Angry Mob", "c": "Human", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "Wanna know their secret? They are always angry."}, {"a": 2205, "n": "Eithné: Young Queen", "c": "Dryad", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "She used to instruct her Dryads to warn people two or even three times before shooting with lethal intention. Used to anyhow."}, {"a": 2208, "n": "Forest Protector", "c": "Treant", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "You know today is not your day when you go searching for firewood but the wood ends up seeing you as good fertilizer instead."}, {"a": 2209, "n": "Shaping Nature", "c": "Nature", "r": "Legendary", "f": "Scoiatael", "t": "Special", "fl": "You talk to me of kings and princes. Who are they? Those whom I know are white skeletons lying in the necropolises of Craag An, deep in the forest."}, {"a": 2210, "n": "Freixenet", "c": "Human", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "He was only meant to be a breeding stud to her. But in the end, they fell in love regardless."}, {"a": 2211, "n": "Dunca", "c": "Dryad, Warrior", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "She does no warning shot, always aims to kill. No mercy, even for the little ones."}, {"a": 2212, "n": "Circle of Life", "c": "Nature", "r": "Rare", "f": "Scoiatael", "t": "Special", "fl": "Those who want to destroy Brokilon, who try to burn its trees and kill all the living things in it, will soon enough become nourishment for its soil."}, {"a": 2213, "n": "Hamadryad", "c": "Dryad", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "Hamadryads form a deep life-long bond with their tree – and its squirrels, of course."}, {"a": 2215, "n": "Duén Canell Guardian", "c": "Dryad, Warrior", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "You have conquered the world, d'hoine, you are everywhere, everywhere you bring with you what you call progress. But we don't want you or your progress here."}, {"a": 2214, "n": "Oakcritters", "c": "Treant", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "They especially like to chew on fingers, which to them are just like juicy carrots."}, {"a": 2216, "n": "Abandoned Girl", "c": "Human", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "People believe that sick girls will spread their illness among the dryads, but in reality, Brokilon protects its children. Abandoned ones, too."}, {"a": 2365, "n": "Alzur", "c": "Human, Mage, Knight", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "A rebel… outcast... knight… even sorcerer if you can believe that."}, {"a": 2439, "n": "Snowdrop", "c": "Human", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "There’s more to life than song and dance, probably..."}, {"a": 2367, "n": "Cosimo Malaspina", "c": "Human, Mage", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Children keep asking him for gifts. He doesn’t know why, but it really helps with finding subjects for his experiments."}, {"a": 2368, "n": "Idarran of Ulivo", "c": "Human, Mage, Mutant", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "They say beauty is in the eye of the beholder, but no one wants to see what Idarran considers beautiful..."}, {"a": 2369, "n": "Geralt: Quen", "c": "Witcher", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Geralt, feeling the iron taste of blood in his mouth, shouted a spell, throwing his hand out in front of him with his fingers open in the Quen Sign."}, {"a": 2370, "n": "Selective Mutation", "c": "Alchemy", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "We can destroy what we have created, but we cannot uncreate it."}, {"a": 1456, "n": "Triangle Within a Triangle", "c": "Spell", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "Adepts of magic often confuse it with a pentacle, which can lead to an infernal disaster."}, {"a": 1457, "n": "Berengar", "c": "Witcher", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Talking the vodyanoi out of sacrificing the prize-winning cow wasn’t an easy task."}, {"a": 1486, "n": "Leo", "c": "Witcher", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "He would have caught the arrow if he only had some heads-up."}, {"a": 2366, "n": "Maxii van Dekkar", "c": "Human, Cursed", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Magic doesn’t work on her, as she is a proud daughter of the Black Sun—and a bounty hunter that has her eyes on some very powerful sorcerers."}, {"a": 2305, "n": "Ivar Evil-Eye", "c": "Witcher", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "There’s a terrible tale behind each and every scar⁠—you’d be surprised just how many are true."}, {"a": 2307, "n": "Vypper", "c": "Beast", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "Vicious, cunning. Known to wait patiently for hours before striking their prey. Once it uncoils to strike, there is no escape. Death is inevitable. ⁠— Ivar Evil-Eye"}, {"a": 2309, "n": "Gorthur Gvaed", "c": "Location", "r": "Legendary", "f": "Nilfgaard", "t": "Artifact", "fl": "There were many scrolls and manuscripts about the legend of the Wild Hunt in the stronghold—and for a good reason."}, {"a": 2306, "n": "Kolgrim", "c": "Witcher", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "Fortune only smiled upon him if it was accompanied by a stroke of very bad luck."}, {"a": 2308, "n": "Warritt the All-Seeing", "c": "Witcher", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "By slightly modifying the Supirre sign, Warritt gained the ability to see... everything."}, {"a": 2310, "n": "Viper Witcher", "c": "Witcher", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "Viper Witchers are trained to fight with twin blades, often referred to as “fangs”. This style focuses on fast and furious strikes aimed to overwhelm their target, be it monster or man."}, {"a": 2312, "n": "Viper Witcher Mentor", "c": "Witcher", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "Viper mentors are especially cold and ruthless in order to prepare their students for the harsh life that awaits them."}, {"a": 2313, "n": "Viper Witcher Alchemist", "c": "Witcher", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "What doesn’t kill you makes you stronger. Or weaker. It depends, really."}, {"a": 2311, "n": "Viper Witcher Adept", "c": "Witcher", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "Each student is given a pet to raise during their stay at Gorthur Gvaed, in order to form a strong emotional bond throughout their training. Years later, before becoming a fully-fledged witcher, they are ordered to slaughter their companion in cold blood."}, {"a": 2314, "n": "Coated Weapons", "c": "Tactic", "r": "Common", "f": "Nilfgaard", "t": "Special", "fl": "No need to strike deep when but a scratch will prove fatal."}, {"a": 2335, "n": "Gezras of Leyda", "c": "Witcher", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "“Take a contract from Aen Seidhe over a dh'oine any day, as you’re far less likely to receive a knife between the ribs in place of coin.” ⁠— Gezras"}, {"a": 2338, "n": "Saber-Tooth Tiger", "c": "Beast", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "The prized possession of a royal menagerie, until a commando of Scoia'tael assaulted the exhibition, released the beast, and set it upon its cruel masters. Since that day, it has acquired a selective taste for human flesh."}, {"a": 2339, "n": "Stygga Castle", "c": "Location", "r": "Legendary", "f": "Scoiatael", "t": "Artifact", "fl": "The Feline witchers did not stay in Stygga Castle for long. Nor anywhere else, actually."}, {"a": 2336, "n": "Brehen", "c": "Witcher", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "Known as the Cat of Iello. A moniker earned not from origins, but as a result of slaughtering peasants there. More of a massacre, really."}, {"a": 2337, "n": "Gaetan", "c": "Witcher", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "“Murder me just to save few crowns? I’m supposed to protect whoresons like that?” ⁠— Gaetan"}, {"a": 2340, "n": "Cat Witcher", "c": "Witcher", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "Members of the School of the Cat are ill-famed due to their penchant for frenzy and bloodlust in the heat of battle. Even when their enemies capitulate, beg for mercy... Cats never stop killing."}, {"a": 2342, "n": "Cat Witcher Mentor", "c": "Witcher", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "If you fall, it’s over. Your nine lives are up, kid."}, {"a": 2343, "n": "Cat Witcher Saboteur", "c": "Witcher", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "“Needless to say, the ill fame of their deeds hangs like a dark cloud over our reputation to this day.” ⁠— Vesemir"}, {"a": 2341, "n": "Cat Witcher Adept", "c": "Witcher", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "Cat students hone their balance by walking a tightrope blindfolded. Failure is easy to shrug off at first, but throughout their training, the walk gets higher⁠—and more perilous⁠—as they work toward their final Trial, where failure is not so forgiving."}, {"a": 2344, "n": "Making a Bomb", "c": "Bomb", "r": "Common", "f": "Scoiatael", "t": "Special", "fl": "You’ll probably want to follow the instructions…"}, {"a": 2345, "n": "Arnaghad", "c": "Witcher", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "“A witcher’s job is to kill monsters and collect coin. No more, no less.” ⁠— Arnaghad"}, {"a": 2347, "n": "Dire Bear", "c": "Beast", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "After countless attempts to slay the savage beast, one could now easily consider it… a mobile armory."}, {"a": 2349, "n": "Haern Caduch", "c": "Location", "r": "Legendary", "f": "Skellige", "t": "Artifact", "fl": "Carved into the icy rock of the Amell Mountains, hidden amid jagged crags and snowdrifts, the location of the long-abandoned School of the Bear remains a well-kept secret."}, {"a": 2346, "n": "Gerd", "c": "Witcher", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "He was contracted to slay a dragon, a siren, and a striga. He was also being pursued by a vengeful knight, bounty hunters, and bandits. Despite all this, he still found time for a round of Gwent."}, {"a": 2348, "n": "Junod of Belhaven", "c": "Witcher", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "Rumour has it he was born of an unusual love between a lady giant and one VERY brave dwarf."}, {"a": 2350, "n": "Bear Witcher", "c": "Witcher", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "Life alone on the road can be tough⁠—be sure to bring all the bare necessities."}, {"a": 2352, "n": "Bear Witcher Mentor", "c": "Witcher", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "If you’re unsure of the way, just keep a lookout for markers⁠—the frozen corpses of would-be witchers."}, {"a": 2353, "n": "Bear Witcher Quartermaster", "c": "Witcher", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "Supply him with enough Mahakam mead, and he might just tell you a tale of how a bear took his shield and arm too!"}, {"a": 2351, "n": "Bear Witcher Adept", "c": "Witcher", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "To become a Bear Witcher, all students must pass the Trial of the Mountain. This requires venturing to the peak of Mount Gorgon to retrieve a special runestone as proof of ascent—an especially brutal challenge, as many boys freeze to death long before they find the summit."}, {"a": 2354, "n": "Armor Up", "c": "Raid", "r": "Common", "f": "Skellige", "t": "Special", "fl": "Why try to sidestep the blow, when you can easily bear the brunt?"}, {"a": 2355, "n": "Erland of Larvik", "c": "Witcher", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "Erland founded the School of the Griffin, and hoped his emphasis on knightly values would help elevate the reputation of witchers among the common folk. Alas, his efforts would go in vain."}, {"a": 2357, "n": "Archgriffin", "c": "Beast", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "Considered the embodiment of courage, loyalty and fighting spirit, the very essence of what Griffin Witchers are known for. However, the School of the Griffin was actually named after a knight errant known as Gryphon, who had long ago instilled these values into its founder."}, {"a": 2359, "n": "Kaer Seren", "c": "Location", "r": "Legendary", "f": "Northern Realms", "t": "Artifact", "fl": "Kaer Seren’s literary collection was its greatest treasure and the envy of a group of overzealous mages. In their attempt to seize it for themselves, they destroyed the very thing they desired most."}, {"a": 2356, "n": "Coën", "c": "Witcher", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "“There is no such thing as a fair fight. Every advantage and every opportunity that arises is used in combat.” ⁠— Coën"}, {"a": 2358, "n": "Keldar", "c": "Witcher", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "“You blunt, brainless humanoids! What do you mean by ‘I don't know?’. You would go hunt the vampires with the Lebioda idol, smeared in garlic!” ⁠— Keldar"}, {"a": 2360, "n": "Griffin Witcher", "c": "Witcher", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "Silver swords are great, yeah. But have you ever tried silver-plated arrowheads?"}, {"a": 2362, "n": "Griffin Witcher Mentor", "c": "Witcher", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "Knowledge will keep you alive far longer than might, dear boy."}, {"a": 2363, "n": "Griffin Witcher Ranger", "c": "Witcher", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "Griffin Witcher Rangers are unparalleled masters in the art of tracking and hunting, even amid the most inhospitable of environments. No matter the trail, they won’t rest until their prey is captured, or killed."}, {"a": 2361, "n": "Griffin Witcher Adept", "c": "Witcher", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "At Kaer Seren, students are afforded the luxury of choice when it comes to their final Trial. They either locate and retrieve a griffin’s egg, or recite the entirety of Liber Tenebrarum verbatim. To Old Keldar’s dismay, no one has ever chosen the latter."}, {"a": 2364, "n": "Target Practice", "c": "Warfare", "r": "Common", "f": "Northern Realms", "t": "Special", "fl": "Most Griffins can split an apple in two from a hundred paces. Just make sure you don’t move."}, {"a": 2316, "n": "Viy", "c": "Insectoid", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "What has a million legs and can eat a city whole?"}, {"a": 2315, "n": "Koshchey", "c": "Insectoid", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "If I tell you koshchey is death, you'll go to the creek anyway, right?"}, {"a": 2319, "n": "Dol Dhu Lokke", "c": "Location", "r": "Legendary", "f": "Monster", "t": "Artifact", "fl": "A monster lair unlike any other. Home to countless horrors and monstrosities. Even a witcher would think twice about setting foot near this hellhole."}, {"a": 2317, "n": "Idr", "c": "Insectoid", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "Who's a good boy? ⁠— Idarran"}, {"a": 2318, "n": "Wererat", "c": "Beast", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "As a child, Idarran lived in the canals of Vizima. He was a natural-born genius, and at the age of five, he had already started experimenting on sewer rats."}, {"a": 2323, "n": "Succubus", "c": "Relict", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "Hydration is of utmost importance."}, {"a": 2321, "n": "Phooca", "c": "Ogroid", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "Particularly troublesome are the larger, stronger breed—a rare kind of nekker known as phoocas. If you see one, run."}, {"a": 2322, "n": "Chimera", "c": "Beast, Mutant", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "At first, Cosimo combined genes of a fiend and a griffin. Then he added some traces of insectoid and wyvern to the pool, resulting in a creature far worse than the sum of its parts."}, {"a": 2324, "n": "Spontaneous Evolution", "c": "Organic", "r": "Common", "f": "Monster", "t": "Special", "fl": "Professor Malaspina accidentally added an extra ingredient to the concoction—compound X."}, {"a": 2327, "n": "Fallen Rayla", "c": "Human, Mutant, Salamandra", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "Slain by the arrows of those she had hunted. Or so many thought. The Salamandra had different plans for her."}, {"a": 2328, "n": "Salamander", "c": "Salamandra", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "Despite their cute little faces, it's best to avoid petting them, as the salamander, when threatened, secretes a deadly toxin that boils the very skin it comes into contact with."}, {"a": 2329, "n": "Salamandra Hideout", "c": "Location, Salamandra", "r": "Legendary", "f": "Syndicate", "t": "Artifact", "fl": "Those who go lurking in the sewers beneath Vizima better watch out, as there are things far worse than rats hidden amid the darkness of the city’s underbelly."}, {"a": 2325, "n": "Roland Bleinheim", "c": "Human, Salamandra", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "“How's my brother doing in the sewers, I wonder...” ⁠— Roland"}, {"a": 2326, "n": "Gellert Bleinheim", "c": "Human, Salamandra", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "“How's my brother doing in the woods, I wonder...” ⁠— Gellert"}, {"a": 2330, "n": "Salamandra Lackey", "c": "Human, Salamandra", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "Lackeys are expected to perform their first five jobs for no pay, demonstrating their passion for the gig."}, {"a": 2331, "n": "Salamandra Abomination", "c": "Beast, Mutant, Salamandra", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "Salamandra’s scientists were so preoccupied with whether they could, they never once considered if they should."}, {"a": 2332, "n": "Salamandra Mage", "c": "Human, Mage, Salamandra", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "Building a fire warms people for a day, but setting them on fire…"}, {"a": 2333, "n": "Failed Experiment", "c": "Human, Mutant, Salamandra", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "Even failed experiments can serve a purpose. How else would one be expected to push the boundaries of knowledge?"}, {"a": 2334, "n": "Stolen Mutagens", "c": "Crime, Salamandra", "r": "Common", "f": "Syndicate", "t": "Special", "fl": "Like organ harvesting—but far more lucrative."}, {"a": 2320, "n": "Hybrid", "c": "Beast, Mutant", "r": "Common", "f": "Monster", "t": "Unit", "fl": "When one head just isn’t enough."}, {"a": 1813, "n": "Madoc", "c": "Witcher", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "In a flash, Madoc pulled out a leathery orb with a fuse, ignited it with a snap of his fingers, and tossed it at the feet of the caterwauling behemoth."}, {"a": 1373, "n": "Anna Henrietta", "c": "Human, Aristocrat", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "As head of state, I must judge her fairly. But she is my sister, thus my heart bleeds for her…"}, {"a": 1282, "n": "Emhyr var Emreis", "c": "Human, Aristocrat", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "They do not call me the Patient. Take care they do not call you the Headless."}, {"a": 1231, "n": "Crach an Craite", "c": "Human, Pirate, Warrior", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "Nilfgaardians call 'im Tirth ys Muire, the Wild Boar o' the Sea. Use 'im to scare their kiddies!"}, {"a": 1363, "n": "Eist Tuirseach", "c": "Human, Warrior", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "Eist came to Cintra to help Crach an Craite win the hand of Princess Pavetta, yet wound up winning her mother's heart for himself."}, {"a": 1187, "n": "Brouver Hoog", "c": "Dwarf", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "That doddery dolt? Ye cannae even tell if he's alive or stuffed!"}, {"a": 1505, "n": "Eldain", "c": "Elf, Bandit", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "The king once dispatched an envoy to Eldain… despite my advice to the contrary. Found the envoy the next day, eyes gouged out, shaft of his white flag jammed down his throat."}, {"a": 1070, "n": "King Foltest", "c": "Human, Soldier, Aristocrat", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "Don't need advisors and their schemes. I place my trust in my soldiers' blades."}, {"a": 1566, "n": "Queen Meve", "c": "Human, Soldier, Aristocrat", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "We're at war, when rulers don't strive nor choose. When rulers grasp sword and shield and ride out to defend their subjects."}, {"a": 1367, "n": "Dettlaff van der Eretein", "c": "Vampire", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "He did not love like a man, but like an animal. Madly, deeply, unconditionally. Wildly."}, {"a": 1358, "n": "Unseen Elder", "c": "Vampire", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "No one, not even among the higher vampires, knows exactly how old the Unseen Elder is. They only know they should never, under any circumstances, defy his will."}, {"a": 1866, "n": "Cleaver", "c": "Dwarf, Crownsplitters", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "Me hogs willnae go hungry th' day thanks to ye."}, {"a": 1836, "n": "Whoreson Junior", "c": "Human, Cutups", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "A war with Whoreson will see Novigrad's gutters run red with blood."}, {"a": 1369, "n": "Rience", "c": "Human, Mage, Agent", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "“I, Rience, taught her pain. With these hands, with these fingers. And I promised her that should you fall into my hands, princess, I would also teach you pain. With these hands, with these fingers…” - Rience"}, {"a": 1828, "n": "Dead Man's Tongue", "c": "Spell", "r": "Epic", "f": "Nilfgaard", "t": "Special", "fl": "They say the dead tell no tales. Truth is, they speak no lies."}, {"a": 1829, "n": "Blightmaker", "c": "Human, Mage, Agent", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "In an attempt to manufacture a superior grapevine, the empire’s botanists stumbled upon the creation of a malignant alchemical, and thus was sown the seed of a scheme most sinister."}, {"a": 1830, "n": "Mage Assassin", "c": "Human, Mage, Agent", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "Somewhere deep within Nilfgaard’s imperial archives is a manuscript titled “Forty-Seven Ways to Kill a Man”. It’s a surprisingly jovial read."}, {"a": 1854, "n": "Fulmar", "c": "Human, Cultist, Druid", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "“Praise the Goddess for all the paths that she opens before you, and turn your greedy gaze away from those She closes in her wisdom” - Fulmar"}, {"a": 1931, "n": "Bride of the Sea", "c": "Human, Cultist, Druid", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "Chosen from among the descendants of Rioghan the Undying. A man whose deeds have cast a dark shadow over his kin for decades."}, {"a": 1824, "n": "Melusine Cultist", "c": "Human, Cultist, Druid", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "But we can still eat fish, can't we?"}, {"a": 2066, "n": "Tears of Siren", "c": "Alchemy", "r": "Common", "f": "Skellige", "t": "Special", "fl": "It is said they only cry for love lost. A pity they only love once in a lifetime…"}, {"a": 1185, "n": "Francesca Findabair", "c": "Elf, Mage", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "Francesca Findabair's blue elven eyes were as impenetrable and hard as glass. When he was introduced to her, the Daisy of the Valleys smiled. The smile, though incredibly beautiful, filled the witcher with terror."}, {"a": 2009, "n": "Vanadáin", "c": "Elf, Soldier", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "It’s better to first gag humans, then listen to what they have to say."}, {"a": 2027, "n": "Sorceress of Dol Blathanna", "c": "Elf, Mage", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "Whilst you are mesmerized by the fishes, a different elf moves to cut your throat."}, {"a": 2029, "n": "Whisperer of Dol Blathanna", "c": "Elf, Mage", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "You won't find more fertile land than in the Valley of Flowers, and with a little magic you can count on a ripe harvest up to three times a year."}, {"a": 2030, "n": "Gerhart of Aelle", "c": "Human, Mage", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "Gerhart of Aelle, otherwise known as Hen Gedymdeith, was the oldest living sorcerer. That is, until his death on Thanedd Island during the coup, where his heart, feeble from inconceivable age, simply gave out among the ruckus."}, {"a": 2041, "n": "Istredd", "c": "Human, Mage", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "Love can make one do crazy things. The loss of love, even more so."}, {"a": 2049, "n": "Casting Contest", "c": "Spell", "r": "Rare", "f": "Northern Realms", "t": "Special", "fl": "Tales of Yennefer of Vengerberg have spurred many an inebriated attempt to replicate her fabled foot-casting. It never ends well."}, {"a": 2042, "n": "Ban Ard Student", "c": "Human, Mage", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "Kaedweni Intelligence considers Ban Ard a hot spot for recruitment, and expelled students⁠—of which there are many⁠—often find themselves swiftly enlisted within the secret service."}, {"a": 2050, "n": "She Who Knows", "c": "Relict", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "She knows well what kind of clay her daughters are made of. After all, she kneaded it herself."}, {"a": 2051, "n": "Rat Catcheress", "c": "Relict", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "The witch grabbed the bells and started to play a lively melody that attracted small rodents and children alike."}, {"a": 2053, "n": "Gan Ceann", "c": "Relict", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "A head in the hands is worth two on the neck."}, {"a": 2052, "n": "Witch Apprentice", "c": "Relict", "r": "Common", "f": "Monster", "t": "Unit", "fl": "Mistress said I would have to toss it on the spit after I finish my studies, but she was just kidding. Right...?"}, {"a": 3348, "n": "The Witchfinder", "c": "Human, Witch Hunter", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "Woe to all those who find themselves on the wrong side of Octavia Hale, the self-proclaimed world-renowned finder⁠—and punisher⁠—of witches, warlocks, and were-things."}, {"a": 2054, "n": "Fabian Hale", "c": "Human, Witch Hunter", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "Fabian takes great pride in his work, with each “victory” etched upon his skin as a permanent reminder of memories most pleasant."}, {"a": 2057, "n": "Hysteria", "c": "Crime", "r": "Rare", "f": "Syndicate", "t": "Special", "fl": "Somebody’s poisoned the waterhole! With innards!"}, {"a": 2059, "n": "Vigilantes", "c": "Human, Witch Hunter", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "The alderman’s wife worked all night on these here costumes⁠—you should be damned grateful, you swines!"}, {"a": 3350, "n": "Teleportation", "c": "Spell", "r": "Common", "f": "Neutral", "t": "Special", "fl": "There was a flash and he stopped seeing, hearing or feeling anything⁠—apart from cold. Cold was the only thing felt inside the black nothingness, amid silence, amorphousness and timelessness, because the teleport dulled and extinguished all other senses."}, {"a": 3349, "n": "Megascope", "c": "", "r": "Common", "f": "Neutral", "t": "Artifact", "fl": "In order to communicate at a distance, one must construct a magical artefact⁠—a megascope⁠—using magic."}, {"a": 3356, "n": "Artaud Terranova", "c": "Human, Mage", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "Ambition can be blinding."}, {"a": 2280, "n": "Sunset Wanderers", "c": "Witcher", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "It seemed like Dandelion meant to journey with the witcher, even to the edge of the world."}, {"a": 3357, "n": "Fercart", "c": "Human, Mage", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "Pawns will never know of the unseen hands, maneuvering them toward certain doom."}, {"a": 3358, "n": "Master of Puppets", "c": "Human, Mage, Agent", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "Do you feel in control?"}, {"a": 3359, "n": "Thanedd Turncoat", "c": "Human, Mage, Agent", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "Hell hath no fury like a sorceress scorned."}, {"a": 3360, "n": "Melusine", "c": "Beast", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "The Lady sits on her throne, devouring our offerings and demanding more. Yet, She does not try to rule over us in any particular way, so She is actually better than any jarl."}, {"a": 1825, "n": "Offering to the Sea", "c": "Alchemy", "r": "Epic", "f": "Skellige", "t": "Special", "fl": "Cultists proclaim that the maidens are offered to the sea, not eaten by its monsters. Yet, for the latter, the semantics makes no difference."}, {"a": 3361, "n": "Havfrue Singer", "c": "Human, Cultist, Druid", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "No human can match sirens in singing. Some, however, are talented enough to compel sirens to listen."}, {"a": 1966, "n": "Hermit", "c": "Human, Cultist, Druid", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "Oh, good Lady, bless your faithful servant with a fat flounder."}, {"a": 3362, "n": "Simlas Finn aep Dabairr", "c": "Elf, Mage", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "I am a Sage. Naturally I know more than you do."}, {"a": 3363, "n": "Saov Ainmhi'dh", "c": "Spell", "r": "Epic", "f": "Scoiatael", "t": "Special", "fl": "Expecto pa⁠— No, wait. That’s not right."}, {"a": 3364, "n": "Orb of Insight ", "c": "Spell", "r": "Rare", "f": "Scoiatael", "t": "Special", "fl": "It shows only one of many possible futures."}, {"a": 3365, "n": "Elven Seer", "c": "Elf, Mage", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "I predict a bad future for your race, dh’oine."}, {"a": 3368, "n": "Tissaia de Vries", "c": "Human, Mage", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "“They will not enter here. No one invited those royalist lackeys, who carry out the orders of their short-sighted kings!” - Tissaia de Vries"}, {"a": 3366, "n": "Leticia Charbonneau", "c": "Human, Mage", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "“You cannot control what the world throws at you, but you can decide on how to react.” - Leticia Charbonneau"}, {"a": 3367, "n": "Practice Makes Perfect", "c": "Spell", "r": "Rare", "f": "Northern Realms", "t": "Special", "fl": "A lesson a day keeps mediocrity away."}, {"a": 3369, "n": "Aretuza Student", "c": "Human, Mage", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "Knowledge beyond measure is a sorceress’s greatest treasure."}, {"a": 3371, "n": "Bloody Mistress", "c": "Relict", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "Once the effigy is on a tree, even the most virtuous of souls will find themselves inexplicably drawn toward her domain."}, {"a": 1820, "n": "Mammuna", "c": "Relict", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "Finders keepers."}, {"a": 3370, "n": "Selfeater", "c": "Relict", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "Omnomnomnom."}, {"a": 3372, "n": "Bleeding Effigy", "c": "Organic", "r": "Common", "f": "Monster", "t": "Special", "fl": "A drop of blood, a hair from the head, a fragment of a nail…"}, {"a": 3373, "n": "The Scoundrel", "c": "Human, Witch Hunter", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "There have been sightings of a slender, sinister-looking man slipping in and out of shadow⁠. The Hales must be in town."}, {"a": 2055, "n": "Ignatius Hale", "c": "Human, Witch Hunter", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "He’s a good boy."}, {"a": 3374, "n": "Confession Extractor", "c": "Crime", "r": "Rare", "f": "Syndicate", "t": "Special", "fl": "Whether they spit lies or cry truths, it matters not⁠—the Extractor always gets its confession."}, {"a": 3375, "n": "Scapegoat", "c": "Human", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "Fact often gives way to fiction."}, {"a": 3377, "n": "Bearification", "c": "Spell", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "Just bear with me."}, {"a": 3376, "n": "Dwimveandra", "c": "Human, Mage", "r": "Rare", "f": "Neutral", "t": "Unit", "fl": "There are those who stay at home and those who leave."}, {"a": 3379, "n": "Vilgefortz: Renegade", "c": "Human, Mage, Agent", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "Four times, Geralt struck. To the temple, to the neck, under the arm, to the thigh. Each blow should have been fatal. Yet each was parried by the mage."}, {"a": 3380, "n": "Lydia van Bredevoort", "c": "Human, Mage", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "Whether by brush or by sorcery, there was no event, emotion, or scene beyond Lydia's power to depict. Apart from joy."}, {"a": 3381, "n": "Imperial Practitioner", "c": "Human, Mage", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "The body is a slab of wet clay. One need only use the correct tools to shape it into something... more."}, {"a": 3382, "n": "Illusionist", "c": "Human, Mage, Soldier", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "“When you are few, make them believe you are many. If they still attack, well... you were fucked either way.” ⁠- Unnamed Nilfgaardian strategist"}, {"a": 3383, "n": "Fucusya", "c": "Beast", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "Like mermaids, the sea witches can experience true love only once in a lifetime. And Fucusya wasted her only time on a human."}, {"a": 3401, "n": "Rioghan the Undying", "c": "Human, Cursed, Cultist, Pirate", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "“Your life will burn as bright as the love between us.” - Fucusya"}, {"a": 3384, "n": "Messenger of the Sea", "c": "Beast", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "A cute little nightmare."}, {"a": 3385, "n": "Little Havfrue", "c": "Beast", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "They will not hesitate to shower you with gifts and affection. They will proudly profess their unwavering adoration and unyielding devotion. Yet, I ask you, when has a man ever given up his legs for love? Hmm?"}, {"a": 1378, "n": "Filavandrel aén Fidháil", "c": "Elf", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "He has pride⁠—the pride of someone who has never had to bow."}, {"a": 3386, "n": "Torque", "c": "Relict", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "Where an elf cannot go himself, he sends a devil."}, {"a": 3387, "n": "Bountiful Harvest", "c": "Nature", "r": "Rare", "f": "Scoiatael", "t": "Special", "fl": "Never have we tilled nor torn up the land, unlike you dh'oine with your hoes and ploughs. You wrest bloody tributes from the Queen of the Fields, while we celebrate her every gift."}, {"a": 3388, "n": "Watcher of the Valley", "c": "Elf, Mage, Soldier", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "He notched his staff for every interloper who thought to try their luck. Soon, the notches, much like the intruders, could no longer be distinguished."}, {"a": 3389, "n": "Chapter of Wizards", "c": "Location", "r": "Legendary", "f": "Northern Realms", "t": "Artifact", "fl": "In the wake of the Novigradian Union, the Chapter of the Gift and the Art sought to ensure all magic was adequately regulated. Yet, some mages refused to be restrained by the fetters of absolute authority, choosing instead to practice their craft away from prying eyes. Deemed 'enemies of the institution', these renegades were promptly hunted down and punished."}, {"a": 3390, "n": "Raffard’s Vengeance", "c": "Machine, Mage, Siege Engine", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "Step 1. Lock the long arm lever to the hook trigger, and place the load into the sling harness.\\nStep 2. Set the counterweight to no less than eighty times the load, and line the glide track with pyrite.\\nStep 3. Conjure and align the portal to target location, and unleash hell."}, {"a": 3391, "n": "Alumni", "c": "Human, Mage", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "Deep down, they had both been waiting for this moment for a long time. Live targets had been a bit of a taboo in academia."}, {"a": 3392, "n": "Meditating Mage", "c": "Human, Mage", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "To become one with air, think away the ground."}, {"a": 1815, "n": "Yaga", "c": "Relict", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "The Witch Queen sat upon her throne of bones, gorging herself on all and sucking the life out of everything that came her way. For centuries, she feasted, until one day, she could no longer stand at all. And so, she ate some more."}, {"a": 3393, "n": "Witches' Sabbath", "c": "Organic", "r": "Epic", "f": "Monster", "t": "Special", "fl": "For the sabbath, at least three witches are required. With two, it’s only a quarrel."}, {"a": 3394, "n": "Incubus", "c": "Relict", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "Women exist to be worshiped."}, {"a": 1819, "n": "Lesser Witch", "c": "Relict", "r": "Common", "f": "Monster", "t": "Unit", "fl": "Less powerful, but no less terrible."}, {"a": 3395, "n": "The Brute", "c": "Human, Witch Hunter", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "He’s a slayer of all things wicked, a saviour of the common folk, and a very good boy. At least, that’s what his mum tells him."}, {"a": 3396, "n": "Octavia Hale", "c": "Human, Witch Hunter", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "A mother is more than just the sum of her children."}, {"a": 3397, "n": "Purge", "c": "Crime", "r": "Rare", "f": "Syndicate", "t": "Special", "fl": "Thought you could outrun justice, did you, you heathen swine?"}, {"a": 3398, "n": "Savvy Huckster", "c": "Human, Witch Hunter", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "Good sir, half a crown per stone!? That’s a crime! I’ll take twenty."}, {"a": 3399, "n": "The Mushy Truffle", "c": "Location", "r": "Legendary", "f": "Neutral", "t": "Artifact", "fl": "Some drink to celebrate. Others, to forget. But here? Here we don't need no reason."}, {"a": 3400, "n": "Alissa Henson", "c": "Human, Mage", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "You either die a hero, or live long enough to be exposed as a villain."}, {"a": 3792, "n": "The Eternal Eclipse", "c": "Scenario", "r": "Legendary", "f": "Nilfgaard", "t": "Artifact", "fl": "For the uninitiated, the Grand Scheme will manifest itself as an avalanche: a series of seemingly insignificant events putting the entire mountain slope in motion to sweep away the ancien régime. Only the madmen and the thorough historians, studying the developments of these days in retrospect, many decades later, will discover the truth:  it was a mechanism as precise as a clock, counting down to the advent of a new world order."}, {"a": 3793, "n": "Master of Ceremonies", "c": "Human, Cultist", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "With the indepth understanding of both human and heavenly affairs comes the realisation that the Grand Scheme is not a chessboard at all. It is a clockwork."}, {"a": 3794, "n": "Eternal Eclipse Deacon", "c": "Human, Cultist", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "Once you see beyond the occult fumes and elitist allure, only then you cease to be a piece and become a player."}, {"a": 3795, "n": "Eternal Eclipse Initiate", "c": "Human, Cultist", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "The air of mystery, the promise of power - enough to obtain a whole set of pawns for your chessboard."}, {"a": 3796, "n": "Endless Voyage", "c": "Scenario, Cursed", "r": "Legendary", "f": "Skellige", "t": "Artifact", "fl": "Time has failed to halt Bjorn's search. What good will the elements do?"}, {"a": 3797, "n": "Bjorn Stormursson", "c": "Human, Cursed, Pirate", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "Bjorn, son of Stormur the Feared, known to his village as Storm Son, to his friends as Thundersocket, to his enemies as Whale Eater, to continentals as the Cyclops of Skellige, to his daughter as Stuffy Old Fuck, and to history as the Unreturned..."}, {"a": 3798, "n": "Deranged Corsair", "c": "Human, Cursed, Pirate", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "Who ever said you had to be dead to haunt the seas?"}, {"a": 3799, "n": "Seagull", "c": "Beast, Cursed, Pirate", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "People often fear crows and ravens as portents of death, while ignoring the ultimate source of shock and terror: the common seagull."}, {"a": 3800, "n": "Mysteries of Loc Feainn", "c": "Scenario, Cursed", "r": "Legendary", "f": "Scoiatael", "t": "Artifact", "fl": "Here, all nature returns to its source; all life finds renewal."}, {"a": 3801, "n": "Lake Guardian: Dusk Aspect", "c": "Beast, Cursed", "r": "Epic", "f": "Scoiatael", "t": "Unit", "fl": "Like a moonflower, it lives to curtail the dark of night."}, {"a": 3802, "n": "Antherion", "c": "Beast, Cursed", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "To lay eyes upon a mythical antherion is to know one was well off the beaten path."}, {"a": 3803, "n": "Chameleon", "c": "Beast", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "Its own mother wouldn't be able to tell you of its true colors."}, {"a": 3804, "n": "Damsel in Distress", "c": "Scenario, Cursed", "r": "Legendary", "f": "Northern Realms", "t": "Artifact", "fl": "Understandably, it had never occurred to any young knight or princeling, that the towers were erected for their own protection."}, {"a": 3805, "n": "The Maiden's Shield", "c": "Human, Knight", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "Her great, quiet guardian, now known to most only as Scruffy, had soon abandoned his old name after meeting fierce little Bronwen for the first time. In this tribulation, he saw his one opportunity for penance."}, {"a": 3807, "n": "Knight-Errant", "c": "Human, Knight", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "Traversing the fine line between idiom and idiot."}, {"a": 3808, "n": "Squire", "c": "Human, Knight", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "25th of Blathe -- Vizima is four days off. Provisions are running low. Nothing to hunt.\\n26th of Blathe -- Ambushed. Lost the cauldron to a brigand's battle-axe.\\n27th of Blathe -- Half an hour is not enough to wash a sallet. I can still smell our makeshift stew."}, {"a": 3809, "n": "The Manor’s Dark Secret", "c": "Scenario, Cursed", "r": "Legendary", "f": "Monster", "t": "Artifact", "fl": "In this manor, the doors lock YOU up."}, {"a": 3810, "n": "Sir Scratch-a-Lot", "c": "Beast, Cursed, Knight", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "If you value your eyesight... Don't call him a pussy."}, {"a": 3811, "n": "Cursed Damsel", "c": "Human, Cursed", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "An innocent girl surrounded by mutilated corpses of her sisters and servants. Don't you pity her? She must be yearning for a comforting embrace."}, {"a": 3812, "n": "Orchard Mantrap", "c": "Plant, Cursed", "r": "Common", "f": "Monster", "t": "Unit", "fl": "Retribution for all innocent fruit cannibalized by mankind!"}, {"a": 3813, "n": "In Search of Forgotten Treasures", "c": "Scenario, Cursed", "r": "Legendary", "f": "Syndicate", "t": "Artifact", "fl": "Fabled, elusive, unmapped. This place sparks the wildest dreams and turns stately sailors into swashbuckling adventurers."}, {"a": 3814, "n": "Flyndr's Crew", "c": "Human, Pirate, Tidecloaks", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "Wretches and thieves drunk on grog, bloodshed and booty - could you ever hope for a better crew?"}, {"a": 3815, "n": "Treasure Huntress", "c": "Human, Pirate, Tidecloaks", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "No island, cape nor bay can guard their secrets from this restless soul and her trusted companion."}, {"a": 3816, "n": "Pearl Diver", "c": "Human, Pirate, Tidecloaks", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "Can ye hold yer breath 'till dis candle burns out? No? Then don't tell me five hundred oren is too much for a pearl."}, {"a": 3817, "n": "Renfri", "c": "Human, Cursed, Bandit", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "In this fairytale, the princess and the monster are the same person."}, {"a": 3818, "n": "Renfri's Gang", "c": "Human, Bandit", "r": "Rare", "f": "Neutral", "t": "Unit", "fl": "What would a princess be without six bloodthirsty henchmen?"}, {"a": 3819, "n": "Saskia: Commander", "c": "Dragon, Soldier", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "We won't be fighting mere minions, but their King! And the King himself will have to recognize our victory! Could a soldier dream of better than defeating a monarch?"}, {"a": 1071, "n": "King Radovid V", "c": "Human, Soldier, Aristocrat", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "“They say it’s the game of kings. That chess teaches one to think strategically. What a load of rubbish! Both sides have identical pieces, the rules stay invariably the same. How does that mirror real life?”"}, {"a": 1284, "n": "Jan Calveit", "c": "Human, Aristocrat", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "“To prepare for the future, it’s best to first know it.”"}, {"a": 1639, "n": "Arachas Queen", "c": "Insectoid", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "Her children inherited her beauty."}, {"a": 1532, "n": "Ardal aep Dahy", "c": "Human, Aristocrat", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "“In my home, in the civilized world, a general commands his forces. He does not rush and thrash about like some rabid hound.”"}, {"a": 1230, "n": "King Bran", "c": "Human, Warrior", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "He lived life on his own terms—died on them, too."}, {"a": 1649, "n": "Cerys: Fearless", "c": "Human, Warrior", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "“If you want something done, send your best man. If you want something done right, send a woman.”"}, {"a": 3822, "n": "Milva: Sharpshooter", "c": "Human, Bandit", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "Rarely did Milva hunt beasts larger than red deer or armor-clad men."}, {"a": 1072, "n": "King Henselt", "c": "Human, Soldier, Aristocrat", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "Fuck with the unicorn and you get the horn."}, {"a": 3844, "n": "Regis: Reborn", "c": "Vampire", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "“You surround your dead with veneration, you dream of immortality, and in your myths and legends someone is always being resurrected—conquering death itself. But were your revered late great-grandfather to spring from his grave and order a beer, hysteria would surely ensue.”"}, {"a": 1895, "n": "King of Beggars", "c": "Human, Blindeyes", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "You say tribute, I say taxes. ⁠— Francis Bedlam"}, {"a": 1759, "n": "Cyrus Engelkind Hemmelfart", "c": "Human, Firesworn, Cleric", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "Behind the Hierarch's pious pageant, his luxurious silks and exotic wines, his whores and slaves, beneath all that lust, greed, and vanity, stands an honorable man."}, {"a": 3932, "n": "Aerondight", "c": "", "r": "Legendary", "f": "Neutral", "t": "Special", "fl": "A deceptively light blade, razor-sharp, and perfectly balanced.\\n\\nThe sword is said to only reveal itself to worthy champions and therefore spends most of its time hidden, patiently awaiting its next bearer."}, {"a": 3933, "n": "Arcane Tome", "c": "", "r": "Legendary", "f": "Neutral", "t": "Artifact", "fl": "Alzur’s opus magnum. Contains the accumulated knowledge of the legendary mage.\\n\\nMages across the realms knew of the simplicity and elegance of Alzur's repertoire, but the sheer, overwhelming mechanics behind them remained forever guarded."}, {"a": 3934, "n": "Mysterious Puzzle Box", "c": "", "r": "Epic", "f": "Neutral", "t": "Artifact", "fl": "A masterfully decorated box brought from a faraway land.\\n\\nDue to the intricate security, one can assume that the contents are either extremely valuable or unimaginably dangerous. Only the brave⁠—or foolish—would ever consider opening it."}, {"a": 3821, "n": "Vial of Forbidden Knowledge", "c": "", "r": "Epic", "f": "Neutral", "t": "Artifact", "fl": "A single globule of the magical liquid can turn a simpleton into a savant."}, {"a": 3935, "n": "Ring of Favor", "c": "", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "Wearing it provides its bearer with a surge of lucky encounters, like meeting a friendly stranger or stumbling upon a treasure. Although, some say such happenings are mere coincidence."}, {"a": 3936, "n": "Ornate Censer", "c": "Alchemy", "r": "Epic", "f": "Neutral", "t": "Special", "fl": "The burner is suited for such tasks as warding off evil spirits, diffusing pleasant aromas, or creating spooky atmospheres for one’s lair."}, {"a": 3937, "n": "Troll Porter", "c": "Ogroid", "r": "Epic", "f": "Neutral", "t": "Unit", "fl": "Although he came from a known line of haberdashers, Kurtz' Kart was certainly a far cry from his grandfather's legacy, Wurr's Wares."}, {"a": 3938, "n": "Runemage", "c": "Human, Mage", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "To you, perhaps, they are mere rocks, but to me they are the cornerstones to building a new world. In each etch I see a city; in each resonance I hear the anthems of a generation!"}, {"a": 3939, "n": "Obsidian Mirror", "c": "Tactic", "r": "Rare", "f": "Nilfgaard", "t": "Special", "fl": "Beware to those who would gaze too long into its obsidian sheen, for one knows not what might gaze back."}, {"a": 3940, "n": "Prophet", "c": "Human, Cultist", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "In his vision, he saw a mage beckon to a black sky as it split open. From the breach, he saw an enormous monstrosity with hooked limbs descending upon a city, smashing and crushing it to rubble. He saw destruction, death, and chaos incarnate, and he was paralysed with fear."}, {"a": 3941, "n": "Magic Compass", "c": "", "r": "Epic", "f": "Skellige", "t": "Special", "fl": "Helps you find exactly what you need. Or what you think you need."}, {"a": 3942, "n": "Highland Warlord", "c": "Human, Warrior", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "Honor!? Ha! You know what happens to honorable men? They’re mourned."}, {"a": 3943, "n": "Prism Pendant", "c": "", "r": "Epic", "f": "Scoiatael", "t": "Artifact", "fl": "Its light, glassy design—inspired by a simple wonder of nature—makes channeling magical energy as easy as breathing."}, {"a": 3944, "n": "Giantslayer", "c": "Dwarf, Warrior", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "Aye, they call me the Giantslayer, and nay, it ain't from bein' a humongous bastard now, is it, ye cocknosed shite!"}, {"a": 3945, "n": "Mutagenerator", "c": "", "r": "Epic", "f": "Northern Realms", "t": "Artifact", "fl": "An alchemy device capable of storing the essence of slain creatures. Transmutes the energy into mutagens.\\n\\nPrimitive in its current form, the apparatus usually produces haphazard results, making experimentation exceedingly difficult to replicate."}, {"a": 3946, "n": "Traveling Priestess", "c": "Human, Cleric", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "Many devotees of the goddess Melitele branch out from the central sanctuary in Ellander to roam the Northern Realms. Most head out as midwives or healers. Others preach messages of peace and love. The rare few choose an itinerant lifestyle, living off of wild berries, and helping out folks along their travels who are struck by misfortune. The presence of such pilgrims is a sign for the forlorn that Melitele has not forsaken them."}, {"a": 3947, "n": "Necromancer's Tome", "c": "", "r": "Epic", "f": "Monster", "t": "Artifact", "fl": "Some of the pages are made of human flesh, and the various prophecies, burial rites, and resurrection passages found enclosed are inked in blood."}, {"a": 3948, "n": "Giant Toad", "c": "Beast", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "Don't expect to end up like Sleeping Beauty once the Toad kisses you. Oh, no. You will swell rapidly into what can only be described as a pustulous, varicose grape, and this is before your pores begin to rupture and discharge the coalescent gravy that is your four humors."}, {"a": 3949, "n": "Conjurer's Candle", "c": "", "r": "Epic", "f": "Syndicate", "t": "Artifact", "fl": "The ornament’s aesthetic is particularly pleasing to those with a fondness for the macabre, yet its true allure lies with its mystical properties; for any old candle can light up a dark space, but only a few can illuminate the truth."}, {"a": 3950, "n": "Shady Vendor", "c": "Human", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "If he ain’t got it, you don’t need it."}, {"a": 4018, "n": "Golden Nekker", "c": "", "r": "Legendary", "f": "Neutral", "t": "Special", "fl": "For what seems like centuries, the most brilliant minds in the world⁠—from theorists to fanatics⁠—have frequently gathered to speculate and debate the purpose of the Golden Nekker. Although they have not yet agreed upon the nature and origin of the strange, elusive statuette, they vow to have an answer “soon”."}, {"a": 4061, "n": "Beauclair", "c": "Location", "r": "Legendary", "f": "Nilfgaard", "t": "Artifact", "fl": "Beauclair, with its ivory spires and amber rooftops against the backdrop of Mount Gorgon, embodies the essential Toussaint: it never feels like anything other than a fairy tale."}, {"a": 4062, "n": "Guillaume de Launfal", "c": "Human, Knight", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "A true exemplar of the five knightly virtues, save perhaps wisdom."}, {"a": 4063, "n": "Buhurt", "c": "Tactic", "r": "Rare", "f": "Nilfgaard", "t": "Special", "fl": "The one ONLY absolute iron-clad rule is: no crotch shots!"}, {"a": 4064, "n": "Knight Challenger", "c": "Human, Knight", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "While you were studying the blade, he mastered his hair."}, {"a": 4065, "n": "Sove", "c": "Human, Warrior", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "The chimera was child's play compared to what awaited at home."}, {"a": 4066, "n": "Ulula", "c": "Human, Warrior", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "Not all beann'shies float around, foul and rotten. Some happen to be great beauties who will kick your arse, rip your ears off, and impale your intestines before shrieking in your face."}, {"a": 4067, "n": "Feral Bond", "c": "Raid", "r": "Rare", "f": "Skellige", "t": "Special", "fl": "When your hour comes, choose the axe. Wolves in these parts tend to take their time."}, {"a": 4068, "n": "Brokvar Warrior", "c": "Human, Warrior", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "RAAAAAAAAAGH!!!"}, {"a": 4069, "n": "Aucwenn", "c": "Dryad, Naiad", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "They are not born of magic, but of nature's long forgotten ways."}, {"a": 4070, "n": "Frog Mating Season", "c": "Nature", "r": "Epic", "f": "Scoiatael", "t": "Special", "fl": "Would ya look at all those eyeballs?\\nYa! They sure look tasty!"}, {"a": 4071, "n": "Naiad Pondkeeper", "c": "Dryad, Naiad", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "Anyone wandering this far from civilization couldn't possibly expect to be missed."}, {"a": 4072, "n": "Naiad Fledgling", "c": "Dryad, Naiad", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "There's more to life than frolicking about naked in ponds. No one has a convincing answer as to what, however."}, {"a": 4074, "n": "Boholt", "c": "Human, Soldier", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "The bounty was often more than whatever the peasants were willing to offer, for the advance payments of lesser hunters also awaited the Reavers in the beasts' lairs."}, {"a": 4075, "n": "Kennet and Gar", "c": "Human, Soldier", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "What tattoo should we get after this 'un?\\n'Ow 'bout a pair of flamin' tits?"}, {"a": 1104, "n": "Reaver Hunters", "c": "Human, Soldier", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "See this here tattoo? 'At's me, hackin' at a dragon. A DRAGON, m'lady."}, {"a": 1106, "n": "Reaver Scout", "c": "Human, Soldier", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "Haven't had much luck with monsters of late, so we enlisted."}, {"a": 4076, "n": "Tir ná Lia", "c": "Location, Wild Hunt", "r": "Legendary", "f": "Monster", "t": "Artifact", "fl": "Great beauty requires great sacrifice. Of entire civilizations, if need be."}, {"a": 4077, "n": "Caranthir: Golden Child", "c": "Elf, Wild Hunt, Mage", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "The future of the Aen Elle spans not kingdoms, but worlds, and mine is the hand that guides us toward that destiny."}, {"a": 4078, "n": "Aen Elle Aristocrat", "c": "Elf, Wild Hunt, Aristocrat", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "Those born with a silver spoon in their mouth rarely care to learn how it got there in the first place."}, {"a": 4079, "n": "Aen Elle Slave Trader", "c": "Elf, Wild Hunt", "r": "Common", "f": "Monster", "t": "Unit", "fl": "Why, we treat our stock with the utmost dignity of course, by providing them with every opportunity to serve the greatest of the Aen Elle."}, {"a": 4080, "n": "Sigi Reuven: Mastermind", "c": "Human, Agent, Aristocrat", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "Ahh, Novigrad: a veritable cornucopia of culture and beauty. That is, if a shiv up the arse behind the Butcher's Yard's what tickles your fancy."}, {"a": 4081, "n": "Bart", "c": "Ogroid", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "Bart brain hurt."}, {"a": 4082, "n": "Little Bird", "c": "Human, Agent", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "Hearsay and rumours were generally dismissed as mere half-truths. Yet Reuven, with his slew of little birds perched in public houses throughout Novigrad, knew instinctively which half could be put to use."}, {"a": 4083, "n": "Pulling the Strings", "c": "Crime", "r": "Common", "f": "Syndicate", "t": "Special", "fl": "Aptly named, the Crown represents an authority of the highest degree. One to whom folks sink to their lowest depths for in order to avoid becoming indebted."}, {"a": 1814, "n": "Yennefer: Illusionist", "c": "Human, Mage", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Have limited trust in your sight when a mage is around."}, {"a": 2064, "n": "Triss: Meteor Shower", "c": "Human, Mage", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "Next time you get the feeling I'm about to piss off Merigold, make sure and knock me upside the head - Lambert"}, {"a": 2062, "n": "Eltibald", "c": "Human, Mage", "r": "Legendary", "f": "Neutral", "t": "Unit", "fl": "A torturer, a doomsayer, a madman. Eltibald was the first mage to delve into the secrets of the Black Sun curse. He heeded the warnings found in ancient texts and started the widespread hunt for the cursed children. Never hesitated to follow the voice of lesser evil..."}, {"a": 4170, "n": "Ard Feainn", "c": "", "r": "Legendary", "f": "Nilfgaard", "t": "Artifact", "fl": "The Great Sun does not extend its light to those destined for the gutters."}, {"a": 4171, "n": "Torres var Emreis: Founder", "c": "Human, Cleric, Aristocrat", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "Like emperor, like empire: Grandiose, entitled, and hell-bent."}, {"a": 1665, "n": "Svalblod", "c": "Beast", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "He proclaimed to his worshippers but one commandment: Kill."}, {"a": 1364, "n": "Tyr: Slayer of Yngvar", "c": "Human, Warrior", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "His sword, forged in the fires of the deep, worthy of being wielded by a god, could crack the earth like lightning. And yet, only his were the hands capable of such artifice."}, {"a": 4173, "n": "Dana Méadbh: Provider", "c": "Relict", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "Every living thing is a child of the Queen of the Fields."}, {"a": 4174, "n": "Quarixis", "c": "Relict", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "Those who come close enough to feel Loc Feainn's breeze on their skin hear a gentle voice. For the good-hearted, it's a warning to turn back swiftly. For the greedy and irreverent, it's a subtle call to a new life. To a new purpose. To eternal penitence in a new body."}, {"a": 4175, "n": "Melitele", "c": "Relict", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "You've seen one goddess of fertility, you've seen them all."}, {"a": 4176, "n": "Temple of Melitele: Congregation", "c": "Location", "r": "Legendary", "f": "Northern Realms", "t": "Artifact", "fl": "Here in Ellander, mistaking our girls' vows of silence for tacit approval will get your arse tanned right quick."}, {"a": 1129, "n": "Dagon: Promised", "c": "Relict", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "That is not dead which can eternal lie, and with strange aeons even death may die."}, {"a": 4177, "n": "Lilit's Omen", "c": "Cursed", "r": "Legendary", "f": "Monster", "t": "Special", "fl": "If you ever happen to witness what looks like the overwhelming shadow of humanity's hatred and cruelty suffocating the skies ... be thankful it's just an omen."}, {"a": 4178, "n": "Saint Gregory: Justicar", "c": "Human, Firesworn, Cleric", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "Retreat, heathen! I will not axe you twice."}, {"a": 4179, "n": "Count Reuven's Treasure", "c": "Crime", "r": "Legendary", "f": "Syndicate", "t": "Artifact", "fl": "Dijkstra's famed profanity - expressed in more than words."}, {"a": 4215, "n": "Abduction", "c": "Tactic", "r": "Legendary", "f": "Nilfgaard", "t": "Special", "fl": "Steady, steady, just a little lower... There we go. That thing ate the Captain's helmet. We'll need to get it back."}, {"a": 4216, "n": "Sandor de Baccalà", "c": "Human, Agent", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "Having been denied a rightful tract of land by his duke of an uncle, Sandor set out to build his own duchy from the ground up, starting with the realm of seedy, bottom-shelf operations within the Imperial Military Intelligence best suited for fools and madmen..."}, {"a": 4217, "n": "Contaminator", "c": "Human, Agent", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "Destroying the supplies was merely a convenient side effect of the main goal: make them believe the food from their allies is tainted, and leave them with a choice: Nilfgaard or famine."}, {"a": 4218, "n": "Toxicologist", "c": "Human", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "Voted least likely to live to old age by the other chemists in the academy. And that was really saying something."}, {"a": 4219, "n": "Kraken", "c": "Beast", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "Once released, there's no un-releasing it."}, {"a": 5556, "n": "Kelpie", "c": "Beast", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "Tis a malevolent spirit! 'Tis animated seaweed! Nay, ye hallucinatin' dolts, 'tis clearly a horse!"}, {"a": 5557, "n": "Sea Serpent", "c": "Beast", "r": "Rare", "f": "Skellige", "t": "Unit", "fl": "Hire a dragonslayer? For some oversized eel? Ha! Mainlander nonsense!"}, {"a": 5558, "n": "Anglerfish", "c": "Beast", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "The good news is, you'll never actually encounter one outside of your deepest, darkest nightmares."}, {"a": 5559, "n": "Telianyn aep Collen", "c": "Elf, Agent, Bandit", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "Months spent foolproofing this operation, only to find I should have hired better listeners... My mother must be laughing somewhere."}, {"a": 5560, "n": "The Heist", "c": "Tactic", "r": "Epic", "f": "Scoiatael", "t": "Special", "fl": "Plan's simple: same as last time, but better."}, {"a": 5561, "n": "Backup Plan", "c": "Tactic", "r": "Rare", "f": "Scoiatael", "t": "Special", "fl": "If we can't rob them in the streets, we fight them in the woods!"}, {"a": 5562, "n": "Trickster", "c": "Elf, Agent, Bandit", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "Living among humans for so many years had revealed some unique vulnerabilities to the Scoia'tael. For one, apparently not all dh'oine recognize sarcasm..."}, {"a": 1077, "n": "Sigismund Dijkstra", "c": "Human, Agent, Aristocrat", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "Checkmate... your majesty."}, {"a": 5564, "n": "Drakenborg", "c": "Location", "r": "Epic", "f": "Northern Realms", "t": "Artifact", "fl": "It's not exactly a holiday, no, but there is plenty of singing, if that's what you're into."}, {"a": 5565, "n": "Redanian Secret Service", "c": "Human, Agent", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "They say the aristocracy can sniff out a commoner among them. However, liberal application of alcohol and perfume can throw off the scent for long enough to strike up a conversation or two. Perhaps even gain their trust."}, {"a": 5566, "n": "Redanian Agent", "c": "Human, Agent", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "Eight-time champion of solo hide-and-seek."}, {"a": 5567, "n": "Hive Mind", "c": "Organic", "r": "Legendary", "f": "Monster", "t": "Special", "fl": "A thousand mindless horrors, all racing toward you in perfect accord, relentless, ravenous."}, {"a": 5568, "n": "Acid Spit", "c": "Organic", "r": "Epic", "f": "Monster", "t": "Special", "fl": "Bugspray doesn't always mean what you think it means."}, {"a": 5569, "n": "Kikimore Stalker", "c": "Insectoid", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "Peek-a-boo, it's after you!"}, {"a": 5570, "n": "Kikimore Hatchling", "c": "Insectoid", "r": "Common", "f": "Monster", "t": "Unit", "fl": "As a general rule, the more brightly colored the egg, the less you'll want to fry it."}, {"a": 5571, "n": "Casimir Bassi", "c": "Dwarf, Crownsplitters", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "He would have done anything for love, but a fireworks display never quite felt this warranted."}, {"a": 5572, "n": "Eveline Gallo", "c": "Elf", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "One somersault into a crossbow shot, aimed with the feet, through a pigeon, mid-flight, blindfolded—and suddenly nothing's impossible."}, {"a": 5573, "n": "Open, Sesame!", "c": "Crime", "r": "Rare", "f": "Syndicate", "t": "Special", "fl": "I'll have any lock you need picked before you even hire me."}, {"a": 5574, "n": "Oxenfurt Guard", "c": "Human, Soldier", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "Cooler heads will prevail... provided they're holding the cards."}, {"a": 5581, "n": "Baccalà", "c": "Location", "r": "Legendary", "f": "Nilfgaard", "t": "Artifact", "fl": "Ever hungry for tar and timber, for cloth and cable, for lard and labor. It's a point of pride for Baccalà that thirty fresh frigates leave its shipyard every year."}, {"a": 5582, "n": "Admiral Rompally", "c": "Human, Soldier, Aristocrat", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "Some call him a hero, some call him a genius. Others prefer to call him a pompous prick. Funnily enough, all are in the right."}, {"a": 5583, "n": "The Catriona", "c": "Machine, Ship", "r": "Epic", "f": "Nilfgaard", "t": "Unit", "fl": "This humble, rat-infested excuse for a hulk will go down in history as the harbinger of plague."}, {"a": 5584, "n": "Battle Stations!", "c": "Tactic", "r": "Epic", "f": "Nilfgaard", "t": "Special", "fl": "Those who desire hegemony over the seas must be ready to pay for it with blood."}, {"a": 5585, "n": "Imperial Fleet", "c": "Machine, Ship", "r": "Rare", "f": "Nilfgaard", "t": "Unit", "fl": "Sirens scatter, tritons tremble, krakens burrow in the mud when the Emperor's mighty fleet ventures forth to rule the waves!"}, {"a": 5586, "n": "Imperial Marine", "c": "Human, Soldier", "r": "Common", "f": "Nilfgaard", "t": "Unit", "fl": "The canvas to trap the winds, the ropes to direct them, and the muscle to pull the ropes—all necessary components of a sea-going vessel."}, {"a": 5587, "n": "Hjalmar: Seawolf", "c": "Human, Pirate, Warrior", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "Heave, lads, heave! ...I meant the SHIP, not yer blasted entrails!"}, {"a": 5590, "n": "Kaer Trolde", "c": "Location", "r": "Legendary", "f": "Skellige", "t": "Artifact", "fl": "Skalds say Kaer Trolde is at its most beautiful during a raging storm, when the thundering sea crashes against its blood-soaked battlements."}, {"a": 5588, "n": "Yustianna an Craite", "c": "Human, Pirate", "r": "Epic", "f": "Skellige", "t": "Unit", "fl": "Never EVER get between an an Craite and glory."}, {"a": 5589, "n": "Naval Supremacy", "c": "Raid", "r": "Epic", "f": "Skellige", "t": "Special", "fl": "The black-clads are wise to outnumber us like this. It's still their funeral, but with at least a bit o' fun."}, {"a": 5591, "n": "Abordage", "c": "Raid", "r": "Rare", "f": "Skellige", "t": "Special", "fl": "Let some other fool go first. And try not to slip on blood. Oh, and make sure the captain sees you killing someone, if you hope for a share in the booty."}, {"a": 5592, "n": "Funeral Boat", "c": "Machine, Ship", "r": "Common", "f": "Skellige", "t": "Unit", "fl": "Those who won their fortune at sea go back to the sea. Farewell, warrior."}, {"a": 5593, "n": "Angus Bri Cri", "c": "Elf, Soldier, Bandit", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "These pests seem to think US surrounded, Riordain. Ha!"}, {"a": 5594, "n": "Riordain", "c": "Elf, Soldier, Bandit", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "Curb your excitement, Angus. You want the dh'oine to suspect?"}, {"a": 5595, "n": "Deception", "c": "Trap", "r": "Epic", "f": "Scoiatael", "t": "Artifact", "fl": "Should have known better than to think you'd have known better!"}, {"a": 5596, "n": "Sticky Situation", "c": "Trap", "r": "Epic", "f": "Scoiatael", "t": "Artifact", "fl": "Revenge is sweet."}, {"a": 5597, "n": "Hostage Taker", "c": "Elf, Soldier, Bandit", "r": "Rare", "f": "Scoiatael", "t": "Unit", "fl": "Of all the words that the Scoia'tael have never adopted, negotiation really stands out."}, {"a": 5598, "n": "Trapmaker", "c": "Elf, Soldier, Bandit", "r": "Common", "f": "Scoiatael", "t": "Unit", "fl": "Always the same with these people: Ahhh, I can't feel my legs! You'd think they'd at least appreciate the craftsmanship..."}, {"a": 5599, "n": "Ravanen Kimbolt", "c": "Human, Soldier, Aristocrat", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "A man who almost wore the crown is a deadly enemy—for once he's had a whiff of royal power, he'll never cede his ambitions."}, {"a": 1375, "n": "King Demavend III", "c": "Human, Aristocrat", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "Even after his kingdom was ripped apart by a Nilfgaardian invasion and a perfidious Kaedweni land grab, he remained the most dignified of the Northern monarchs."}, {"a": 5601, "n": "Bernard Loredo", "c": "Human, Soldier", "r": "Epic", "f": "Northern Realms", "t": "Unit", "fl": "Any border town needs a strong-arm rule. A toast to the commandant!"}, {"a": 5602, "n": "Flotsam", "c": "Location", "r": "Epic", "f": "Northern Realms", "t": "Artifact", "fl": "There are backwaters, there are shitholes, and then there's Flotsam."}, {"a": 5603, "n": "Ship Ballista", "c": "Machine, Siege Engine, Ship", "r": "Rare", "f": "Northern Realms", "t": "Unit", "fl": "Shoot first, worry about the whom later."}, {"a": 5604, "n": "Onager", "c": "Machine, Siege Engine", "r": "Common", "f": "Northern Realms", "t": "Unit", "fl": "By order of the commander, the following are no longer to be used as payload:\\n-Vegetables\\n-Dung\\n-Heads of prisoners\\n-Other parts of said prisoners"}, {"a": 5605, "n": "King Chrum", "c": "Ogroid, Warrior", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "Thrum's valley kingdom was little more than a glorified toll road. Chrum, however, had expansion on his mind. Expansion, and reform."}, {"a": 5606, "n": "Tugo the Elder", "c": "Ogroid, Druid", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "The wisest troll on the entire Continent... likely never had much competition in the first place."}, {"a": 5607, "n": "Lord Riptide", "c": "Ogroid, Warrior", "r": "Epic", "f": "Monster", "t": "Unit", "fl": "It ain't superstition, brother. Coastal waters vanishing when they shouldn't? Might as well give it a name."}, {"a": 5608, "n": "Girdle of Giant Strength", "c": "", "r": "Epic", "f": "Monster", "t": "Special", "fl": "A sturdy leather belt, clearly crafted for a titan, yet inexplicably fits the torso of anyone who tries it on. Although the girdle makes its wearer as strong as a giant, it does not make them giant-size."}, {"a": 5609, "n": "Ogre Warrior", "c": "Ogroid, Warrior", "r": "Rare", "f": "Monster", "t": "Unit", "fl": "You is idiot steak!"}, {"a": 5610, "n": "Enraged Cyclops", "c": "Ogroid, Warrior", "r": "Common", "f": "Monster", "t": "Unit", "fl": "You won’t like him when he’s angry. Or any other time, come to think of it…"}, {"a": 5611, "n": "The Acherontia", "c": "Machine, Ship", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "No amount of gold could ever weigh this ship down. Like a force of nature, its pursuit of riches was unstoppable."}, {"a": 5612, "n": "Captain Yago", "c": "Human, Pirate", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "Often mistaken for a Zerrikanian emissary for his refined clothing and composed demeanor... but what kind of diplomat carries a fucking ballista?"}, {"a": 5613, "n": "Ixora", "c": "Human, Pirate", "r": "Epic", "f": "Syndicate", "t": "Unit", "fl": "The marching clink of Ixora's iron heel showed that she'd never quite left her old life as a Kerack city guard behind. Only the pay, and the laws."}, {"a": 5614, "n": "Mercenary Contract", "c": "Crime", "r": "Epic", "f": "Syndicate", "t": "Special", "fl": "Sign right here, on the dotted... ignore the blood."}, {"a": 5615, "n": "Magpie", "c": "Beast, Pirate", "r": "Rare", "f": "Syndicate", "t": "Unit", "fl": "The captain named each of his magpies Tymon, yet whenever he'd calls out this name, they would somehow always know which one he meant."}, {"a": 5616, "n": "Acherontia Deckhand", "c": "Human, Pirate", "r": "Common", "f": "Syndicate", "t": "Unit", "fl": "Hard not to learn humility over the years, watching all that fortune shuffled along, behind crossed blades, and under threat of a beating."}, {"a": 1471, "n": "Henry var Attre", "c": "Human, Aristocrat", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "The line between diplomacy and espionage is a thin one, especially in Nilfgaard."}, {"a": 5617, "n": "Rosa and Edna var Attre", "c": "Human, Aristocrat", "r": "Legendary", "f": "Nilfgaard", "t": "Unit", "fl": "Double trouble!"}, {"a": 5618, "n": "Otkell", "c": "Human, Warrior", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "In his hour of doom, All-mother Freya appeared to Otkell on his ship, and gave him the means to soothe the raging tempest, for she already knew that Otkell, like his brothers, had a greater tale to tell."}, {"a": 5619, "n": "Heulyn", "c": "Human", "r": "Legendary", "f": "Skellige", "t": "Unit", "fl": "Legends, in all their embellishment and exaggeration, are only spun by those who weren't around to witness the mundane. Heulyn, Mother of Forefathers, never raised her sons on dragons and thunderstorms, but instead on chores and responsibilities."}, {"a": 5620, "n": "Mahakam Pass", "c": "Location", "r": "Legendary", "f": "Scoiatael", "t": "Artifact", "fl": "The roads to Mount Carbon shall one day be paved with steel."}, {"a": 5621, "n": "Eudora Breckenriggs", "c": "Dwarf", "r": "Legendary", "f": "Scoiatael", "t": "Unit", "fl": "Dinnae just follow yer heart tae yer sweetums. Yer wits matter every bit as much."}, {"a": 1366, "n": "Princess Adda", "c": "Human, Cursed, Aristocrat", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "Freed from a curse inflicted out of jealousy, only to return to a court filled with little else."}, {"a": 5623, "n": "Radovid: Judgment", "c": "Human, Soldier, Aristocrat", "r": "Legendary", "f": "Northern Realms", "t": "Unit", "fl": "Judge. Jury. Excecutioner. King."}, {"a": 5624, "n": "Lara Dorren", "c": "Elf, Wild Hunt", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "The tragedy of Lara Dorren echoes throughout the centuries. Wherever Hen Ichaer flows, heartbreak is bound to follow."}, {"a": 5625, "n": "Vereena", "c": "Vampire", "r": "Legendary", "f": "Monster", "t": "Unit", "fl": "Your heart, your life—MINE. If not mine—NO ONE'S."}, {"a": 5626, "n": "Novigrad", "c": "Location", "r": "Legendary", "f": "Syndicate", "t": "Artifact", "fl": "In the free city of Novigrad, one is always free to do as one's told."}, {"a": 5627, "n": "Madam Marquise Serenity", "c": "Human, Blindeyes", "r": "Legendary", "f": "Syndicate", "t": "Unit", "fl": "If you're looking for something different, perhaps a round of Gwent?"}];
